import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { Transaction, Category, BalanceSummary, AppSettings, Debt, Account, Budget, Goal, SystemAlert, DashboardWidgetConfig } from '../types';
import { StorageService } from '../services/storageService';
import { DEFAULT_CATEGORIES } from '../constants';

interface FinanceContextType {
  transactions: Transaction[];
  categories: Category[];
  debts: Debt[];
  accounts: Account[];
  budgets: Budget[];
  goals: Goal[];
  settings: AppSettings;
  user: any;
  loading: boolean;
  cloudSyncStatus: 'synced' | 'syncing' | 'error' | 'local';

  addTransaction: (t: Omit<Transaction, 'id' | 'createdAt'>) => Promise<void>;
  updateTransaction: (t: Transaction) => Promise<void>;
  deleteTransaction: (id: string) => Promise<void>;
  addAccount: (acc: Omit<Account, 'id'>) => Promise<void>;
  updateAccount: (acc: Account) => Promise<void>;
  deleteAccount: (id: string) => Promise<void>;
  reconcileBalance: (accountId: string, actualBalance: number) => Promise<void>;
  addDebt: (debt: Omit<Debt, 'id'>, config: any) => Promise<void>;
  updateDebt: (id: string, name: string, installments: number) => Promise<void>;
  deleteDebt: (id: string) => Promise<void>;
  addCategory: (c: Omit<Category, 'id'>) => Promise<void>;
  updateCategory: (c: Category) => Promise<void>;
  deleteCategory: (id: string) => Promise<void>;
  updateSettings: (s: Partial<AppSettings>) => Promise<void>;
  getBalanceSummary: (month: string, projectionDate: string) => BalanceSummary;
  getDebtProgress: (debtId: string) => any;
  getAccountBalance: (accountId: string) => number;
  getSystemAlerts: () => SystemAlert[];
  logout: () => void;
  saveBudget: (budget: Budget) => Promise<void>;
  deleteBudget: (categoryId: string) => Promise<void>;
  addGoal: (goal: Omit<Goal, 'id'>) => Promise<void>;
  updateGoal: (goal: Goal) => Promise<void>;
  deleteGoal: (id: string) => Promise<void>;
  refreshData: () => void;
  recalculateDebtSeries: (transactionId: string, newAmount: number) => Promise<void>;
  restoreAutoBackup: () => boolean;
  getBackupInfo: () => any;
}

const FinanceContext = createContext<FinanceContextType | undefined>(undefined);

const DEFAULT_LAYOUT: DashboardWidgetConfig[] = [
  { id: 'balance', visible: true, label: 'Saldo' },
  { id: 'shortcuts', visible: true, label: 'Atalhos' },
  { id: 'status', visible: true, label: 'Status' },
  { id: 'recent', visible: true, label: 'Recentes' },
  { id: 'debts', visible: true, label: 'Dívidas' }
];

export const FinanceProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<any>({ uid: 'local-user', displayName: 'Usuário Local' });
  const [loading, setLoading] = useState(true);
  const [cloudSyncStatus] = useState<'local'>('local');

  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [categories, setCategories] = useState<Category[]>(DEFAULT_CATEGORIES);
  const [debts, setDebts] = useState<Debt[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [budgets, setBudgets] = useState<Budget[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<AppSettings>({ 
    theme: 'light', 
    dashboardLayout: DEFAULT_LAYOUT,
    userName: 'Usuário Local'
  } as any);

  // Load initial data from StorageService
  useEffect(() => {
    const loadData = () => {
      setTransactions(StorageService.getTransactions());
      setCategories(StorageService.getCategories());
      setDebts(StorageService.getDebts());
      setAccounts(StorageService.getAccounts());
      setBudgets(StorageService.getBudgets());
      setGoals(StorageService.getGoals());

      const savedSettings = StorageService.getSettings();
      if (savedSettings) {
        setSettings({
          ...settings,
          ...savedSettings,
          dashboardLayout: savedSettings.dashboardLayout || DEFAULT_LAYOUT
        });
      }
      setLoading(false);
    };

    loadData();
  }, []);

  // Save data to StorageService whenever state changes
  useEffect(() => { if (!loading) StorageService.saveTransactions(transactions); }, [transactions, loading]);
  useEffect(() => { if (!loading) StorageService.saveCategories(categories); }, [categories, loading]);
  useEffect(() => { if (!loading) StorageService.saveDebts(debts); }, [debts, loading]);
  useEffect(() => { if (!loading) StorageService.saveAccounts(accounts); }, [accounts, loading]);
  useEffect(() => { if (!loading) StorageService.saveBudgets(budgets); }, [budgets, loading]);
  useEffect(() => { if (!loading) StorageService.saveGoals(goals); }, [goals, loading]);
  useEffect(() => { if (!loading) StorageService.saveSettings(settings); }, [settings, loading]);

  const addTransaction = async (t: any) => {
    const newTx = { ...t, id: crypto.randomUUID(), createdAt: Date.now() };
    setTransactions(prev => [newTx, ...prev]);
  };

  const updateTransaction = async (t: Transaction) => {
    setTransactions(prev => prev.map(tx => tx.id === t.id ? t : tx));
  };

  const deleteTransaction = async (id: string) => {
    setTransactions(prev => prev.filter(tx => tx.id !== id));
  };

  const addAccount = async (acc: Omit<Account, 'id'>) => {
    const newAcc = { ...acc, id: crypto.randomUUID() };
    setAccounts(prev => [...prev, newAcc]);
  };

  const updateAccount = async (acc: Account) => {
    setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a));
  };

  const deleteAccount = async (id: string) => {
    setAccounts(prev => prev.filter(a => a.id !== id));
  };

  const reconcileBalance = async (accId: string, actualBalance: number) => {
    const account = accounts.find(a => a.id === accId);
    if (!account) return;
    const current = getAccountBalance(accId);
    const diff = actualBalance - current;
    await updateAccount({ ...account, initialBalance: account.initialBalance + diff });
  };

  const getAccountBalance = (accountId: string): number => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;
    let balance = Number(account.initialBalance || 0);
    transactions.forEach(t => {
      if (t.status === 'pending') return;
      if (t.accountId === accountId) {
        if (t.type === 'income') balance += t.amount;
        else if (t.type === 'expense') balance -= t.amount;
      }
      if (t.type === 'transfer' && t.destinationAccountId === accountId) {
        balance += t.amount;
      }
    });
    return parseFloat(balance.toFixed(2));
  };

  const getBalanceSummary = (month: string, projectionDate: string): BalanceSummary => {
    const limit = new Date(projectionDate + 'T23:59:59').getTime();
    const realBalance = accounts.reduce((s, acc) => s + getAccountBalance(acc.id), 0);
    let projectedBalance = realBalance;
    let monthlyIncome = 0, monthlyExpense = 0, pendingIncome = 0, pendingExpense = 0;

    transactions.forEach(t => {
      const isPaid = t.status === 'paid';
      const isInc = t.type === 'income';
      const tTime = new Date(t.date + 'T12:00:00').getTime();

      if (!isPaid && tTime <= limit) {
        if (isInc) projectedBalance += t.amount;
        else if (t.type === 'expense') projectedBalance -= t.amount;
      }

      if (t.date.startsWith(month) && t.type !== 'transfer') {
        if (isInc) { 
          if (isPaid) monthlyIncome += t.amount; 
          else pendingIncome += t.amount; 
        } else { 
          if (isPaid) monthlyExpense += t.amount; 
          else pendingExpense += t.amount; 
        }
      }
    });

    return { realBalance, projectedBalance, monthlyIncome, monthlyExpense, pendingIncome, pendingExpense };
  };

  const getSystemAlerts = (): SystemAlert[] => {
    const alerts: SystemAlert[] = [];
    const today = new Date().toISOString().slice(0, 10);
    const next7 = new Date(); next7.setDate(next7.getDate() + 7);
    const next7Str = next7.toISOString().slice(0, 10);

    transactions.filter(t => t.status === 'pending' && t.date <= next7Str).forEach(t => {
      alerts.push({
        id: `alert_${t.id}`,
        title: t.description,
        amount: t.amount,
        date: t.date,
        type: t.date < today ? 'overdue' : t.date === today ? 'today' : 'week',
        isCovered: getAccountBalance(t.accountId) >= t.amount,
        transactionId: t.id
      });
    });
    return alerts;
  };

  const addDebt = async (debt: Omit<Debt, 'id'>, config: any) => {
    const debtId = crypto.randomUUID();
    const newTxs: Transaction[] = [];
    for(let i=0; i<config.installments; i++){
      const tid = crypto.randomUUID();
      const d = new Date(config.firstDate + 'T12:00:00'); d.setMonth(d.getMonth() + i);
      const tx: Transaction = {
        id: tid, debtId,
        description: `${debt.name} (${i+1}/${config.installments})`,
        amount: config.fixedInstallmentValue,
        date: d.toISOString().slice(0, 10),
        type: 'expense', 
        categoryId: config.categoryId, 
        accountId: config.accountId,
        status: config.autoPayPast && d < new Date() ? 'paid' : 'pending',
        installmentNumber: i+1, 
        installmentTotal: config.installments, 
        createdAt: Date.now()
      };
      newTxs.push(tx);
    }
    setTransactions(prev => [...newTxs, ...prev]);
    setDebts(prev => [...prev, { ...debt, id: debtId }]);
  };

  const recalculateDebtSeries = async (transactionId: string, newAmount: number) => {
    const sourceTx = transactions.find(t => t.id === transactionId);
    if (!sourceTx || !sourceTx.debtId) return;

    const diff = newAmount - sourceTx.amount;
    const relatedTxs = transactions.filter(t => t.debtId === sourceTx.debtId && t.status === 'pending' && t.id !== transactionId);

    if (relatedTxs.length === 0) {
      // Just update this one if no more pending
      setTransactions(prev => prev.map(t => t.id === transactionId ? { ...t, amount: newAmount } : t));
      return;
    }

    // Amortization logic: distribute the difference across future pending installments
    const adjustmentPerInstallment = diff / relatedTxs.length;

    setTransactions(prev => prev.map(t => {
      if (t.id === transactionId) return { ...t, amount: newAmount };
      if (t.debtId === sourceTx.debtId && t.status === 'pending') {
        return { ...t, amount: Math.max(0, t.amount - adjustmentPerInstallment) };
      }
      return t;
    }));
  };

  return (
    <FinanceContext.Provider value={{
      transactions, categories, debts, accounts, budgets, goals, settings, user, loading, cloudSyncStatus: 'local',
      addTransaction, updateTransaction, deleteTransaction, 
      addAccount, updateAccount, deleteAccount, reconcileBalance,
      addDebt,
      updateDebt: async (id, name) => setDebts(prev => prev.map(d => d.id === id ? { ...d, name } : d)),
      deleteDebt: async (id) => {
        setDebts(prev => prev.filter(d => d.id !== id));
        setTransactions(prev => prev.filter(t => t.debtId !== id));
      },
      addCategory: async (c) => setCategories(prev => [...prev, { ...c, id: `cat_${Date.now()}` }]),
      updateCategory: async (c) => setCategories(prev => prev.map(cat => cat.id === c.id ? c : cat)),
      deleteCategory: async (id) => setCategories(prev => prev.filter(c => c.id !== id)),
      updateSettings: async (s) => setSettings(prev => ({ ...prev, ...s })),
      getBalanceSummary, 
      getDebtProgress: (id) => {
        const d = debts.find(x => x.id === id);
        if(!d) return { paid: 0, remaining: 0, progress: 0, status: 'paid', totalReal: 0 };
        const txs = transactions.filter(t => t.debtId === id);
        const p = txs.filter(t => t.status === 'paid').reduce((s,t) => s+t.amount, 0);
        const tr = txs.reduce((s,t) => s+t.amount, 0);
        return { paid: p, remaining: Math.max(0, tr - p), progress: tr > 0 ? (p/tr)*100 : 0, status: (tr-p) <= 0.01 ? 'paid' : 'active', totalReal: tr };
      },
      getAccountBalance, getSystemAlerts, logout: () => {
        // For local storage, logout just clears the mock user or doesn't do much
        StorageService.clearData();
        window.location.reload();
      },
      saveBudget: async (b) => setBudgets(prev => [...prev.filter(x => x.categoryId !== b.categoryId), b]),
      deleteBudget: async (id) => setBudgets(prev => prev.filter(b => b.categoryId !== id)),
      addGoal: async (g) => setGoals(prev => [...prev, { ...g, id: crypto.randomUUID() }]),
      updateGoal: async (g) => setGoals(prev => prev.map(x => x.id === g.id ? g : x)),
      deleteGoal: async (id) => setGoals(prev => prev.filter(x => x.id !== id)),
      refreshData: () => window.location.reload(),
      recalculateDebtSeries,
      restoreAutoBackup: () => StorageService.restoreAutoBackup(),
      getBackupInfo: () => StorageService.getAutoBackupInfo()
    }}>
      {children}
    </FinanceContext.Provider>
  );
};

export const useFinance = () => {
  const context = useContext(FinanceContext);
  if (!context) throw new Error("useFinance deve ser usado dentro de FinanceProvider");
  return context;
};

import React from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import { FinanceProvider, useFinance } from './context/FinanceContext';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { TransactionList } from './components/TransactionList';
import { FinancialInsights } from './components/FinancialInsights';
import { TransactionForm } from './components/TransactionForm';
import { Settings } from './components/Settings';
import { CategoryList } from './components/CategoryList';
import { FinancialSummary } from './components/FinancialSummary';
import { DebtList } from './components/DebtList';
import { AlertsScreen } from './components/AlertsScreen';
import { CalendarScreen } from './components/CalendarScreen';
import { PlanningScreen } from './components/PlanningScreen';
import { Loader2 } from 'lucide-react';

const AppContent = () => {
  const { loading } = useFinance();
  const [isAddModalOpen, setIsAddModalOpen] = React.useState(false);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950">
        <div className="flex flex-col items-center space-y-4">
           <Loader2 className="animate-spin text-indigo-600" size={48} />
           <p className="text-slate-400 font-medium text-sm animate-pulse">Carregando seus dados...</p>
        </div>
      </div>
    );
  }

  return (
    <HashRouter>
      <Layout onOpenAdd={() => setIsAddModalOpen(true)}>
        <Routes>
          <Route path="/" element={<Dashboard />} />
          <Route path="/summary" element={<FinancialSummary />} />
          <Route path="/transactions" element={<TransactionList />} />
          <Route path="/calendar" element={<CalendarScreen />} />
          <Route path="/debts" element={<DebtList />} />
          <Route path="/alerts" element={<AlertsScreen />} />
          <Route path="/insights" element={<FinancialInsights />} />
          <Route path="/planning" element={<PlanningScreen />} />
          <Route path="/settings" element={<Settings />} />
          <Route path="/categories" element={<CategoryList />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>

        {isAddModalOpen && (
          <TransactionForm onClose={() => setIsAddModalOpen(false)} />
        )}
      </Layout>
    </HashRouter>
  );
};

const App = () => {
  return (
    <FinanceProvider>
      <AppContent />
    </FinanceProvider>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { 
  ChevronRight, Layers, Trash2, Moon, Sun, Download, 
  Upload, CheckCircle2, RefreshCw, 
  Landmark, History, User, AppWindow,
  ChevronLeft, LayoutGrid, Database,
  Eye, EyeOff, ArrowUp, ArrowDown
} from 'lucide-react';
import { StorageService } from '../services/storageService';
import { useFinance } from '../context/FinanceContext';
import { Account } from '../types';

export const Settings = () => {
  const { 
    refreshData, settings, updateSettings, transactions, categories, 
    debts, accounts, budgets, goals,
    addAccount, updateAccount, deleteAccount, reconcileBalance, getAccountBalance, 
    restoreAutoBackup, getBackupInfo
  } = useFinance();

  const [isAccountModalOpen, setIsAccountModalOpen] = useState(false);
  const [isReconcileModalOpen, setIsReconcileModalOpen] = useState(false);
  const [isLayoutModalOpen, setIsLayoutModalOpen] = useState(false);

  const [editingAccount, setEditingAccount] = useState<Account | null>(null);
  const [accName, setAccName] = useState('');
  const [accType, setAccType] = useState<'wallet'|'bank'|'investment'>('bank');
  const [accColor, setAccColor] = useState('#6366f1');

  const [reconcileAccountId, setReconcileAccountId] = useState('');
  const [actualBalance, setActualBalance] = useState('');

  const backupInputRef = useRef<HTMLInputElement>(null);
  const backupInfo = getBackupInfo();

  const handleClearData = () => {
    if (confirm('Tem certeza que deseja apagar todos os dados? Esta ação não pode ser desfeita.')) {
      StorageService.clearData();
      refreshData();
    }
  };

  const openAccountModal = (acc?: Account) => {
    if (acc) {
      setEditingAccount(acc);
      setAccName(acc.name);
      setAccType(acc.type as any);
      setAccColor(acc.color);
    } else {
      setEditingAccount(null);
      setAccName('');
      setAccType('bank');
      setAccColor('#6366f1');
    }
    setIsAccountModalOpen(true);
  };

  const handleSaveAccount = () => {
    if (!accName) return;
    const accountData = {
      name: accName, type: accType, color: accColor,
      initialBalance: editingAccount ? editingAccount.initialBalance : 0,
      enabled: true
    };
    if (editingAccount) updateAccount({ ...editingAccount, ...accountData });
    else addAccount(accountData);
    setIsAccountModalOpen(false);
  };

  const openReconcileModal = (acc: Account) => {
    setReconcileAccountId(acc.id);
    setActualBalance(getAccountBalance(acc.id).toString());
    setIsReconcileModalOpen(true);
  };

  const handleReconcile = () => {
    if (!reconcileAccountId || isNaN(parseFloat(actualBalance))) return;
    reconcileBalance(reconcileAccountId, parseFloat(actualBalance));
    setIsReconcileModalOpen(false);
  };

  const handleAutoRestore = () => {
    if (!backupInfo) return;
    if (confirm(`Deseja restaurar o backup automático de ${backupInfo.date.toLocaleString()}?`)) {
       const success = restoreAutoBackup();
       if (success) { alert('Backup restaurado!'); window.location.reload(); }
       else alert('Falha ao restaurar.');
    }
  };

  const toggleWidget = (id: string) => {
    const newLayout = settings.dashboardLayout.map(w => w.id === id ? { ...w, visible: !w.visible } : w);
    updateSettings({ dashboardLayout: newLayout });
  };

  const moveWidget = (index: number, direction: 'up' | 'down') => {
    const newLayout = [...settings.dashboardLayout];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newLayout.length) return;
    [newLayout[index], newLayout[targetIndex]] = [newLayout[targetIndex], newLayout[index]];
    updateSettings({ dashboardLayout: newLayout });
  };

  const colors = [
    { key: 'indigo', label: 'Índigo', hex: '#6366f1' },
    { key: 'blue', label: 'Azul', hex: '#3b82f6' },
    { key: 'emerald', label: 'Esmeralda', hex: '#10b981' },
    { key: 'violet', label: 'Violeta', hex: '#8b5cf6' },
    { key: 'rose', label: 'Rosa', hex: '#f43f5e' },
    { key: 'orange', label: 'Laranja', hex: '#f97316' },
  ];

  const handleExport = () => {
      const data = { version: '1.2', timestamp: new Date().toISOString(), transactions, categories, settings, debts, accounts, budgets, goals };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a'); 
      a.href = url; a.download = `financas_pro_backup_${new Date().toISOString().slice(0,10)}.json`;
      document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url);
  };

  const handleRestoreClick = () => { if (backupInputRef.current) { backupInputRef.current.value = ''; backupInputRef.current.click(); } };
  const processRestoreFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]; if (!file) return;
      if (!confirm('ATENÇÃO: Restaurar um backup substituirá TODOS os dados atuais.')) return;
      try {
          const text = await file.text(); const data = JSON.parse(text);
          StorageService.saveTransactions(data.transactions || []); 
          StorageService.saveCategories(data.categories || []);
          StorageService.saveSettings(data.settings || {}); 
          StorageService.saveDebts(data.debts || []); 
          StorageService.saveAccounts(data.accounts || []);
          StorageService.saveBudgets(data.budgets || []);
          StorageService.saveGoals(data.goals || []);
          window.location.reload(); 
      } catch (err) { alert('Erro ao processar backup.'); console.error(err); }
  };

  return (
    <div className="pb-32 animate-fade-in text-slate-900 dark:text-slate-100 max-w-md mx-auto">
      <div className="sticky top-0 bg-slate-50/80 dark:bg-slate-950/80 backdrop-blur-lg z-30 pt-4 pb-6 px-1 flex items-center">
        <Link to="/" className="p-2 mr-2 hover:bg-white dark:hover:bg-slate-800 rounded-2xl transition-all active:scale-90">
           <ChevronLeft size={24} />
        </Link>
        <h1 className="text-2xl font-black tracking-tight text-slate-800 dark:text-white">Ajustes</h1>
      </div>

      <div className="space-y-8 px-1">

        {/* Profile Section */}
        <section className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800">
           <div className="flex items-center space-x-4">
              <div className="w-16 h-16 bg-gradient-to-tr from-indigo-600 to-indigo-400 rounded-3xl flex items-center justify-center text-white">
                 <User size={32} strokeWidth={1.5} />
              </div>
              <div className="flex-1">
                 <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest block mb-1">Seu Nome</span>
                 <input value={settings.userName || ''} onChange={(e) => updateSettings({ userName: e.target.value })} placeholder="Como quer ser chamado?" className="w-full bg-transparent text-xl font-bold text-slate-800 dark:text-white outline-none placeholder:text-slate-300 dark:placeholder:text-slate-700" />
              </div>
           </div>
        </section>

        {/* Layout Customization */}
        <section className="px-2">
           <button onClick={() => setIsLayoutModalOpen(true)} className="w-full bg-white dark:bg-slate-900 rounded-3xl p-5 shadow-sm border border-slate-100 dark:border-slate-800 flex items-center justify-between group active:scale-[0.98] transition-all">
              <div className="flex items-center space-x-3">
                 <div className="p-2.5 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400 rounded-2xl"><LayoutGrid size={22} /></div>
                 <div className="text-left">
                    <span className="text-sm font-bold text-slate-800 dark:text-white block">Organizar Início</span>
                    <span className="text-[10px] text-slate-400">Personalize seus widgets</span>
                 </div>
              </div>
              <ChevronRight size={18} className="text-slate-300 group-hover:translate-x-1 transition" />
           </button>
        </section>

        {/* Accounts Management */}
        <section>
           <div className="flex justify-between items-center mb-4 px-2">
              <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center">Patrimônio & Contas</h2>
              <button onClick={() => openAccountModal()} className="text-[10px] font-bold bg-indigo-600 text-white px-3 py-1.5 rounded-full">Nova</button>
           </div>
           <div className="grid gap-3">
              {accounts.map(acc => (
                <div key={acc.id} className="group bg-white dark:bg-slate-900 rounded-[2rem] p-4 shadow-sm border border-slate-100 dark:border-slate-800 flex items-center justify-between">
                   <div className="flex items-center space-x-3 cursor-pointer flex-1" onClick={() => openAccountModal(acc)}>
                      <div className="w-12 h-12 rounded-2xl flex items-center justify-center text-white" style={{ backgroundColor: acc.color }}>
                         <Landmark size={24} strokeWidth={1.5} />
                      </div>
                      <div>
                         <h3 className="font-bold text-slate-800 dark:text-white text-sm">{acc.name}</h3>
                         <span className="text-[10px] font-medium text-slate-400 uppercase">{acc.type}</span>
