                   <div className="text-right">
                      <p className={`font-black text-sm ${getAccountBalance(acc.id) >= 0 ? 'text-slate-800 dark:text-white' : 'text-rose-500'}`}>R$ {getAccountBalance(acc.id).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
