                    <button onClick={() => updateSettings({ theme: 'light' })} className={`p-4 rounded-3xl border-2 flex flex-col items-center space-y-2 ${settings.theme === 'light' ? 'border-indigo-500 bg-indigo-50/50 text-indigo-600' : 'border-slate-50 dark:border-slate-800 text-slate-400'}`}>
