                    <button onClick={() => updateSettings({ theme: 'dark' })} className={`p-4 rounded-3xl border-2 flex flex-col items-center space-y-2 ${settings.theme === 'dark' ? 'border-indigo-500 bg-indigo-950/50 text-indigo-400' : 'border-slate-50 dark:border-slate-800 text-slate-500'}`}>
