                      <button key={c.key} onClick={() => updateSettings({ primaryColor: c.key })} className={`w-10 h-10 rounded-full transition-all flex items-center justify-center relative ${(settings.primaryColor || 'indigo') === c.key ? 'scale-110 shadow-xl ring-4 ring-white dark:ring-slate-800' : 'opacity-60'}`} style={{ backgroundColor: c.hex }}>
