                          <span className="text-sm font-bold text-slate-700 dark:text-slate-200 block">Nuvem Local</span>
                          <span className="text-[10px] text-slate-400">Backup Automático Browser</span>
                       </div>
                    </div>
                    {backupInfo && <span className="text-[10px] font-black bg-emerald-50 text-emerald-600 px-2 py-1 rounded-lg">{backupInfo.date.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>}
                 </div>
                 <button onClick={handleAutoRestore} disabled={!backupInfo} className="w-full py-3 text-[11px] font-black uppercase text-emerald-600 bg-emerald-50 dark:bg-emerald-900/10 rounded-2xl disabled:opacity-30">Restaurar do Local</button>
              </div>
              <div className="p-6 grid grid-cols-2 gap-4">
                 <button onClick={handleExport} className="flex flex-col items-center justify-center p-4 bg-slate-50 dark:bg-slate-800/50 rounded-[2rem]"><Download size={24} className="text-indigo-50 mb-2 text-indigo-500" /><span className="text-[10px] font-black uppercase tracking-tighter">Exportar</span></button>
                 <button onClick={handleRestoreClick} className="flex flex-col items-center justify-center p-4 bg-slate-50 dark:bg-slate-800/50 rounded-[2rem]"><Upload size={24} className="text-purple-500 mb-2" /><span className="text-[10px] font-black uppercase tracking-tighter">Importar</span></button>
                 <input type="file" accept=".json" ref={backupInputRef} onChange={processRestoreFile} className="hidden" />
              </div>
              <div className="p-6">
                 <button onClick={handleClearData} className="w-full py-4 flex items-center justify-center space-x-2 text-rose-500 font-black text-xs uppercase"><Trash2 size={16} /><span>Resetar Tudo</span></button>
