               </div>
               <div className="space-y-6">
                  <div>
                     <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 px-1">Nome da Conta</label>
                     <input value={accName} onChange={e => setAccName(e.target.value)} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-800 border-2 border-transparent focus:border-indigo-500 rounded-[1.5rem] dark:text-white outline-none font-bold text-lg" placeholder="Ex: Nubank..." />
                  </div>
                  <div>
                     <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 px-1">Categoria</label>
                     <div className="flex p-1 bg-slate-50 dark:bg-slate-800 rounded-2xl">
                        {(['bank', 'wallet', 'investment'] as const).map(t => (
                           <button key={t} onClick={() => setAccType(t)} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${accType === t ? 'bg-white dark:bg-slate-700 text-indigo-600 shadow-md scale-[1.02]' : 'text-slate-400'}`}>{t === 'bank' ? 'Banco' : t === 'wallet' ? 'Bolso' : 'Inv.'}</button>
                        ))}
                     </div>
                  </div>
                  <button onClick={handleSaveAccount} className="w-full py-5 bg-indigo-600 text-white rounded-[1.5rem] font-black text-sm uppercase tracking-widest shadow-xl">Salvar Conta</button>
                  {editingAccount && <button onClick={() => { if(confirm('Excluir esta conta?')) { deleteAccount(editingAccount.id); setIsAccountModalOpen(false); }}} className="w-full py-4 text-rose-500 font-bold text-xs uppercase">Excluir</button>}
               </div>
            </div>
         </div>
      )}

      {/* Reconcile Modal */}
      {isReconcileModalOpen && (
         <div className="fixed inset-0 bg-slate-900/60 z-[70] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
            <div className="bg-white dark:bg-slate-900 rounded-[3rem] p-8 w-full max-w-sm shadow-2xl border border-slate-100 dark:border-slate-800 animate-scale-in">
               <div className="text-center mb-8">
                 <div className="w-20 h-20 bg-indigo-50 dark:bg-indigo-900/30 rounded-[2rem] flex items-center justify-center mx-auto mb-4 text-indigo-600 shadow-inner"><RefreshCw size={36} strokeWidth={1.5} /></div>
                 <h3 className="text-2xl font-black text-slate-800 dark:text-white">Ajuste de Saldo</h3>
                 <p className="text-xs text-slate-500 dark:text-slate-400 mt-2 px-4">Informe o valor real para sincronizar.</p>
               </div>
               <div className="space-y-6">
                 <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 px-1">Novo Saldo Real</label>
                    <div className="relative">
                       <span className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 font-black text-xl">R$</span>
                       <input type="number" step="0.01" value={actualBalance} onChange={e => setActualBalance(e.target.value)} className="w-full pl-14 pr-5 py-5 bg-white dark:bg-slate-800 border-2 border-indigo-100 dark:border-indigo-900/50 focus:border-indigo-500 rounded-[1.5rem] dark:text-white outline-none font-black text-2xl shadow-sm" placeholder="0,00" />
                    </div>
                 </div>
                 <div className="flex space-x-3 pt-4">
                    <button onClick={() => setIsReconcileModalOpen(false)} className="flex-1 py-4 text-slate-400 font-black text-xs uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-800 rounded-2xl transition">Cancelar</button>
                    <button onClick={handleReconcile} className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-indigo-700 transition active:scale-[0.98]">Confirmar</button>
                 </div>
               </div>
            </div>
         </div>
      )}

      {/* Layout Modal */}
      {isLayoutModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 z-[70] flex items-end sm:items-center justify-center backdrop-blur-md animate-fade-in p-0 sm:p-4">
           <div className="bg-white dark:bg-slate-900 rounded-t-[3rem] sm:rounded-[3rem] p-8 w-full max-w-sm shadow-2xl border border-slate-100 dark:border-slate-800 animate-slide-up max-h-[90vh] overflow-y-auto no-scrollbar">
              <div className="flex justify-between items-center mb-8">
                 <h3 className="text-2xl font-black text-slate-800 dark:text-white">Organizar Início</h3>
                 <button onClick={() => setIsLayoutModalOpen(false)} className="p-2 bg-slate-50 dark:bg-slate-800 rounded-full transition-all active:scale-90">X</button>
              </div>
              <div className="space-y-3">
                 {settings.dashboardLayout.map((widget, index) => (
                    <div key={widget.id} className="bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-800 p-4 rounded-3xl flex items-center justify-between">
                       <div className="flex items-center space-x-3">
                          <div className="flex flex-col space-y-1">
                             <button onClick={() => moveWidget(index, 'up')} disabled={index === 0} className="p-1 text-slate-300 hover:text-indigo-500 disabled:opacity-20"><ArrowUp size={14} /></button>
                             <button onClick={() => moveWidget(index, 'down')} disabled={index === settings.dashboardLayout.length - 1} className="p-1 text-slate-300 hover:text-indigo-500 disabled:opacity-20"><ArrowDown size={14} /></button>
                          </div>
                          <span className="text-sm font-bold text-slate-700 dark:text-slate-200">{widget.label}</span>
                       </div>
                       <button onClick={() => toggleWidget(widget.id)} className={`p-2 rounded-xl transition-all ${widget.visible ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-200 text-slate-400 opacity-50'}`}>{widget.visible ? <Eye size={20} /> : <EyeOff size={20} />}</button>
                    </div>
                 ))}
              </div>
              <button onClick={() => setIsLayoutModalOpen(false)} className="w-full mt-8 py-5 bg-indigo-600 text-white rounded-[1.5rem] font-black text-sm uppercase tracking-widest shadow-xl">Concluir</button>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { useFinance } from '../context/FinanceContext';
import { getIcon } from '../constants';
import { 
  Eye, EyeOff, TrendingUp, TrendingDown, Calendar, Wallet, 
  ChevronRight, ArrowDownCircle, Bell, 
  Settings as SettingsIcon, CreditCard, Sparkles, PieChart, 
  Layers, ArrowUpRight, ArrowDownLeft, Clock,
  Zap, CalendarDays, Landmark, Check,
  ShieldCheck, Database
} from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';

const ShortcutButton = ({ icon: Icon, label, color, onClick }: { icon: any, label: string, color: string, onClick: () => void }) => {
  const bgColors: Record<string, string> = {
    orange: 'bg-orange-50 dark:bg-orange-900/20 text-orange-600 dark:text-orange-400',
    purple: 'bg-purple-50 dark:bg-purple-900/20 text-purple-600 dark:text-purple-400',
    blue: 'bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400',
    emerald: 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400',
    indigo: 'bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400'
  };

  return (
    <button 
      onClick={onClick}
      className="flex flex-col items-center min-w-[75px] group"
    >
      <div className={`w-14 h-14 rounded-[1.5rem] flex items-center justify-center mb-2 transition-all group-active:scale-90 shadow-sm border border-slate-100 dark:border-slate-800 ${bgColors[color] || bgColors.blue}`}>
        <Icon size={24} strokeWidth={1.5} />
      </div>
      <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest text-center">{label}</span>
    </button>
  );
};

export const Dashboard = () => {
  const { 
    getBalanceSummary, transactions, categories, getSystemAlerts, 
    accounts, settings, getDebtProgress, debts, getAccountBalance, updateTransaction
  } = useFinance();

  const navigate = useNavigate();
  const [showValues, setShowValues] = useState(true);
  const [balanceMode, setBalanceMode] = useState<'real' | 'projected'>('real');

  const [isLoaded, setIsLoaded] = useState(false);
  useEffect(() => { setIsLoaded(true); }, []);

  const [currentMonth] = useState(new Date().toISOString().slice(0, 7));
  const [projectionDate, setProjectionDate] = useState(() => {
    const now = new Date();
    const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    return endOfMonth.toISOString().slice(0, 10);
  });

  const summary = useMemo(() => 
    getBalanceSummary(currentMonth, projectionDate), 
  [transactions, currentMonth, projectionDate, getBalanceSummary]);

  const alerts = useMemo(() => getSystemAlerts(), [transactions, getSystemAlerts]);

  const totalIncome = summary.monthlyIncome + summary.pendingIncome;
  const totalExpense = summary.monthlyExpense + summary.pendingExpense;
  const flowBalance = totalIncome - totalExpense;
  const budgetUsedPct = totalIncome > 0 ? Math.min(100, (totalExpense / totalIncome) * 100) : 0;

  const recentTransactions = useMemo(() => {
    const futureLimit = new Date();
    futureLimit.setDate(futureLimit.getDate() + 2);
    const limitStr = futureLimit.toISOString().slice(0, 10);

    return [...transactions]
      .filter(t => t.date <= limitStr)
      .sort((a, b) => {
        const dateA = new Date(a.date).getTime();
        const dateB = new Date(b.date).getTime();
        if (dateB !== dateA) return dateB - dateA;
        return (b.createdAt || 0) - (a.createdAt || 0);
      })
      .slice(0, 5);
  }, [transactions]);

  const activeDebts = useMemo(() => {
    return debts.filter(d => getDebtProgress(d.id).status === 'active').slice(0, 2);
  }, [debts, getDebtProgress]);

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handleQuickPay = (e: React.MouseEvent, t: any) => {
    e.stopPropagation();
    updateTransaction({ ...t, status: 'paid' });
  };

  const renderBalance = () => (
    <div key="balance" className="relative bg-slate-900 dark:bg-black rounded-[2.5rem] p-8 text-white shadow-2xl shadow-indigo-100 dark:shadow-none overflow-hidden group">
      <div className="absolute top-0 right-0 -mr-20 -mt-20 w-72 h-72 bg-indigo-600 rounded-full blur-[100px] opacity-40"></div>

      <div className="absolute top-8 right-8 z-20 flex items-center space-x-1.5 opacity-60">
        <div className="flex items-center space-x-1 text-[9px] font-black uppercase text-indigo-300">
           <Database size={12} />
           <span>Modo Local</span>
        </div>
      </div>

      <div className="relative z-10">
        <div className="flex justify-between items-start mb-8">
          <div className="flex bg-white/5 backdrop-blur-md rounded-2xl p-1 border border-white/10">
             <button onClick={() => setBalanceMode('real')} className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest ${balanceMode === 'real' ? 'bg-indigo-500 text-white' : 'text-slate-400'}`}>Real</button>
             <button onClick={() => setBalanceMode('projected')} className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest ${balanceMode === 'projected' ? 'bg-indigo-500 text-white' : 'text-slate-400'}`}>Previsto</button>
          </div>
          <button onClick={() => setShowValues(!showValues)} className="text-slate-500 hover:text-white transition p-1 bg-white/5 rounded-full mr-12">
            {showValues ? <Eye size={18} /> : <EyeOff size={18} />}
          </button>
        </div>

        <div className="flex justify-between items-end mb-8">
          <div className="space-y-1">
             <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">{balanceMode === 'real' ? 'Saldo Consolidado' : 'Projeção de Caixa'}</p>
             <h2 className="text-4xl font-black tracking-tight tabular-nums">{showValues ? formatCurrency(balanceMode === 'real' ? summary.realBalance : summary.projectedBalance) : 'R$ •••••••'}</h2>
          </div>

          {balanceMode === 'projected' && (
            <div className="flex flex-col items-end animate-fade-in group/date">
              <label className="text-[9px] font-black text-indigo-400 uppercase tracking-widest mb-1 flex items-center">
                <CalendarDays size={10} className="mr-1" /> Até
              </label>
              <input 
                type="date" 
                value={projectionDate}
                onChange={(e) => setProjectionDate(e.target.value)}
                className="bg-white/10 border border-white/10 rounded-lg px-2 py-1 text-[10px] font-bold text-white outline-none focus:bg-white/20 transition-all cursor-pointer hover:border-indigo-500/50"
              />
            </div>
          )}
        </div>

        {balanceMode === 'real' && accounts.length > 0 && (
          <div className="mb-6 animate-fade-in">
             <div className="flex gap-3 overflow-x-auto no-scrollbar pb-2">
                {accounts.map(acc => {
                  const balance = getAccountBalance(acc.id);
                  const Icon = acc.type === 'wallet' ? Wallet : acc.type === 'investment' ? TrendingUp : Landmark;
                  return (
                    <div key={acc.id} className="bg-white/5 border border-white/10 p-3 rounded-2xl min-w-[130px] shrink-0 backdrop-blur-sm hover:bg-white/10 transition-colors cursor-pointer" onClick={() => navigate('/settings')}>
                       <div className="flex items-center space-x-2 mb-2">
                          <div className="w-2 h-2 rounded-full" style={{ backgroundColor: acc.color }}></div>
                          <span className="text-[10px] text-slate-300 font-bold uppercase truncate">{acc.name}</span>
                       </div>
                       <span className="text-sm font-bold text-white block">
                         {showValues ? formatCurrency(balance) : '••••'}
                       </span>
                    </div>
                  );
                })}
             </div>
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
           <div className="bg-white/5 rounded-[1.5rem] p-4 border border-white/5">
              <p className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1">Ganhos (Mês)</p>
              <p className="text-base font-bold">{showValues ? formatCurrency(totalIncome) : '••••'}</p>
           </div>
           <div className="bg-white/5 rounded-[1.5rem] p-4 border border-white/5">
              <p className="text-[10px] font-black text-rose-400 uppercase tracking-widest mb-1">Gastos (Mês)</p>
              <p className="text-base font-bold">{showValues ? formatCurrency(totalExpense) : '••••'}</p>
           </div>
        </div>
      </div>
    </div>
  );

  const renderShortcuts = () => (
    <div key="shortcuts" className="px-1 overflow-x-auto no-scrollbar flex space-x-5 pb-2">
       <ShortcutButton icon={CreditCard} label="Dívidas" color="orange" onClick={() => navigate('/debts')} />
       <ShortcutButton icon={Sparkles} label="Análise IA" color="purple" onClick={() => navigate('/insights')} />
       <ShortcutButton icon={PieChart} label="Resumo" color="emerald" onClick={() => navigate('/summary')} />
       <ShortcutButton icon={Zap} label="Ajustes" color="blue" onClick={() => navigate('/settings')} />
    </div>
  );

  const renderStatus = () => (
    <div key="status" className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800">
       <div className="flex justify-between items-end mb-6">
          <div>
             <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">Status Mensal</h3>
             <p className="text-xl font-black text-slate-800 dark:text-white">
                {budgetUsedPct.toFixed(0)}% <span className="text-sm font-medium text-slate-400">gasto</span>
             </p>
          </div>
          <div className={`flex items-center space-x-1 px-3 py-1.5 rounded-2xl text-[10px] font-black uppercase tracking-widest ${flowBalance >= 0 ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
             {flowBalance >= 0 ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
             <span>{showValues ? formatCurrency(Math.abs(flowBalance)) : '••••'}</span>
          </div>
       </div>
       <div className="relative h-4 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
          <div className={`h-full transition-all duration-1000 ${budgetUsedPct > 90 ? 'bg-rose-500' : 'bg-indigo-500'}`} style={{ width: `${budgetUsedPct}%` }}></div>
       </div>
    </div>
  );

  const renderRecent = () => (
    <div key="recent" className="px-1">
      <div className="flex justify-between items-center mb-4 px-1">
         <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">Últimas Movimentações</h3>
         <Link to="/transactions" className="text-[10px] font-black text-indigo-500 uppercase tracking-widest hover:text-indigo-600 flex items-center">
            Ver Extrato <ChevronRight size={12} className="ml-0.5"/>
         </Link>
      </div>

      <div className="relative">
         <div className="space-y-4">
            {recentTransactions.map((t) => {
               const category = categories.find(c => c.id === t.categoryId);
               const Icon = category ? getIcon(category.icon) : ArrowDownCircle;
               const isExpense = t.type === 'expense';
               const isPending = t.status === 'pending';

               return (
                  <div key={t.id} onClick={() => navigate('/transactions')} className="relative z-10 flex items-center group cursor-pointer">
                     <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mr-4 shrink-0 shadow-sm border border-white dark:border-slate-800 transition-all group-hover:scale-105 group-active:scale-95 z-10 ${isPending ? 'bg-amber-50 dark:bg-amber-900/20' : 'bg-white dark:bg-slate-900'}`}>
                        {isPending ? <Clock size={20} className="text-amber-500" /> : <Icon size={20} style={{ color: category?.color || '#64748b' }} />}
                     </div>

                     <div className="flex-1 bg-white dark:bg-slate-900 p-3 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-800 flex items-center justify-between group-active:bg-slate-50 dark:group-active:bg-slate-800 transition-colors">
                        <div className="min-w-0 pr-2">
                           <h4 className={`text-sm font-bold truncate ${isPending ? 'text-slate-500 dark:text-slate-400' : 'text-slate-800 dark:text-white'}`}>
                              {t.description}
                           </h4>
                           <div className="flex items-center space-x-2 mt-0.5">
                              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wide">{category?.name || 'Geral'}</span>
                           </div>
                        </div>

                        <div className="flex items-center space-x-3">
                           <span className={`text-sm font-black tabular-nums ${isPending ? 'text-slate-400' : isExpense ? 'text-slate-800 dark:text-white' : 'text-emerald-500'}`}>
                              {isExpense ? '- ' : '+ '}{showValues ? formatCurrency(t.amount) : '••••'}
                           </span>
                           {isPending && (
                              <button onClick={(e) => handleQuickPay(e, t)} className="w-8 h-8 rounded-full bg-emerald-50 dark:bg-emerald-900/20 text-emerald-500 flex items-center justify-center hover:bg-emerald-500 hover:text-white transition-all shadow-sm">
                                 <Check size={14} strokeWidth={3} />
                              </button>
                           )}
                        </div>
                     </div>
                  </div>
               );
            })}
         </div>
      </div>
    </div>
  );

  const renderDebts = () => activeDebts.length > 0 && (
    <div key="debts" className="px-1">
       <div className="flex justify-between items-center mb-4">
          <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">Dívidas Ativas</h3>
          <Link to="/debts" className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">Ver Todas</Link>
       </div>
       <div className="grid grid-cols-1 gap-3">
          {activeDebts.map(debt => {
            const { remaining, progress } = getDebtProgress(debt.id);
            return (
              <div key={debt.id} onClick={() => navigate('/debts')} className="bg-white dark:bg-slate-900 p-4 rounded-3xl shadow-sm border border-slate-100 dark:border-slate-800 flex items-center justify-between cursor-pointer active:scale-95 transition-all">
                <div className="flex-1 min-w-0 pr-4">
                   <h4 className="text-sm font-bold text-slate-800 dark:text-white truncate mb-1">{debt.name}</h4>
                   <div className="w-full bg-slate-50 dark:bg-slate-800 h-1.5 rounded-full overflow-hidden">
                      <div className="bg-orange-500 h-full rounded-full" style={{ width: `${progress}%` }}></div>
                   </div>
                </div>
                <div className="text-right shrink-0">
                   <p className="text-xs font-black text-orange-600">{showValues ? formatCurrency(remaining) : '••••'}</p>
                   <p className="text-[9px] font-bold text-slate-400 uppercase">Restante</p>
                </div>
              </div>
            );
          })}
       </div>
    </div>
  );

  const widgetMap: Record<string, () => React.ReactNode> = {
    balance: renderBalance,
    shortcuts: renderShortcuts,
    status: renderStatus,
    recent: renderRecent,
    debts: renderDebts
  };

  return (
    <div className={`space-y-6 pb-24 transition-opacity duration-500 ${isLoaded ? 'opacity-100' : 'opacity-0'} text-slate-900 dark:text-slate-100`}>
      <div className="flex justify-between items-center px-1 pt-2">
        <div className="flex flex-col">
          <span className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em] mb-0.5">{getGreeting()}</span>
          <h1 className="text-xl font-black text-slate-800 dark:text-white tracking-tight">{settings.userName || 'Financeiro'}</h1>
        </div>
        <div className="flex items-center space-x-2">
           <Link to="/alerts" className="relative p-2.5 bg-white dark:bg-slate-900 rounded-2xl text-slate-400 border border-slate-100 dark:border-slate-800 hover:text-indigo-500 transition-colors">
             <Bell size={20} />
             {alerts.length > 0 && <span className="absolute top-2 right-2 w-2.5 h-2.5 bg-rose-500 rounded-full border-2 border-white dark:border-slate-900 animate-pulse"></span>}
          </Link>
          <Link to="/settings" className="p-2.5 bg-white dark:bg-slate-900 rounded-2xl text-slate-400 border border-slate-100 dark:border-slate-800 hover:text-indigo-500 transition-colors">
             <SettingsIcon size={20} />
          </Link>
        </div>
      </div>
      {settings.dashboardLayout.map(widget => widget.visible && widgetMap[widget.id] ? widgetMap[widget.id]() : null)}
    </div>
  );
};

const getGreeting = () => {
  const h = new Date().getHours();
  if (h < 12) return 'Bom dia';
  if (h < 18) return 'Boa tarde';
  return 'Boa noite';
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { Transaction, Category, BalanceSummary, AppSettings, Debt, Account, Budget, Goal, SystemAlert, DashboardWidgetConfig } from '../types';
import { StorageService } from '../services/storageService';
import { DEFAULT_CATEGORIES } from '../constants';

interface FinanceContextType {
  transactions: Transaction[];
  categories: Category[];
  debts: Debt[];
  accounts: Account[];
  budgets: Budget[];
  goals: Goal[];
  settings: AppSettings;
  user: any;
  loading: boolean;
  cloudSyncStatus: 'synced' | 'syncing' | 'error' | 'local';

  addTransaction: (t: Omit<Transaction, 'id' | 'createdAt'>) => Promise<void>;
  updateTransaction: (t: Transaction) => Promise<void>;
  deleteTransaction: (id: string) => Promise<void>;
  addAccount: (acc: Omit<Account, 'id'>) => Promise<void>;
  updateAccount: (acc: Account) => Promise<void>;
  deleteAccount: (id: string) => Promise<void>;
  reconcileBalance: (accountId: string, actualBalance: number) => Promise<void>;
  addDebt: (debt: Omit<Debt, 'id'>, config: any) => Promise<void>;
  updateDebt: (id: string, name: string, installments: number) => Promise<void>;
  deleteDebt: (id: string) => Promise<void>;
  addCategory: (c: Omit<Category, 'id'>) => Promise<void>;
  updateCategory: (c: Category) => Promise<void>;
  deleteCategory: (id: string) => Promise<void>;
  updateSettings: (s: Partial<AppSettings>) => Promise<void>;
  getBalanceSummary: (month: string, projectionDate: string) => BalanceSummary;
  getDebtProgress: (debtId: string) => any;
  getAccountBalance: (accountId: string) => number;
  getSystemAlerts: () => SystemAlert[];
  logout: () => void;
  saveBudget: (budget: Budget) => Promise<void>;
  deleteBudget: (categoryId: string) => Promise<void>;
  addGoal: (goal: Omit<Goal, 'id'>) => Promise<void>;
  updateGoal: (goal: Goal) => Promise<void>;
  deleteGoal: (id: string) => Promise<void>;
  refreshData: () => void;
  recalculateDebtSeries: (transactionId: string, newAmount: number) => Promise<void>;
  restoreAutoBackup: () => boolean;
  getBackupInfo: () => any;
  // Added confirmMigration to support MigrationModal component
  confirmMigration: (sync: boolean) => Promise<void>;
}

const FinanceContext = createContext<FinanceContextType | undefined>(undefined);

const DEFAULT_LAYOUT: DashboardWidgetConfig[] = [
  { id: 'balance', visible: true, label: 'Saldo' },
  { id: 'shortcuts', visible: true, label: 'Atalhos' },
  { id: 'status', visible: true, label: 'Status' },
  { id: 'recent', visible: true, label: 'Recentes' },
  { id: 'debts', visible: true, label: 'Dívidas' }
];

export const FinanceProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<any>({ uid: 'local-user', displayName: 'Usuário Local' });
  const [loading, setLoading] = useState(true);
  const [cloudSyncStatus] = useState<'local'>('local');

  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [categories, setCategories] = useState<Category[]>(DEFAULT_CATEGORIES);
  const [debts, setDebts] = useState<Debt[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [budgets, setBudgets] = useState<Budget[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<AppSettings>({ 
    theme: 'light', 
    dashboardLayout: DEFAULT_LAYOUT,
    userName: 'Usuário Local'
  } as any);

  // Load initial data from StorageService
  useEffect(() => {
    const loadData = () => {
      setTransactions(StorageService.getTransactions());
      setCategories(StorageService.getCategories());
      setDebts(StorageService.getDebts());
      setAccounts(StorageService.getAccounts());
      setBudgets(StorageService.getBudgets());
      setGoals(StorageService.getGoals());

      const savedSettings = StorageService.getSettings();
      if (savedSettings) {
        setSettings({
          ...settings,
          ...savedSettings,
          dashboardLayout: savedSettings.dashboardLayout || DEFAULT_LAYOUT
        });
      }
      setLoading(false);
    };

    loadData();
  }, []);

  // Save data to StorageService whenever state changes
  useEffect(() => { if (!loading) StorageService.saveTransactions(transactions); }, [transactions, loading]);
  useEffect(() => { if (!loading) StorageService.saveCategories(categories); }, [categories, loading]);
  useEffect(() => { if (!loading) StorageService.saveDebts(debts); }, [debts, loading]);
  useEffect(() => { if (!loading) StorageService.saveAccounts(accounts); }, [accounts, loading]);
  useEffect(() => { if (!loading) StorageService.saveBudgets(budgets); }, [budgets, loading]);
  useEffect(() => { if (!loading) StorageService.saveGoals(goals); }, [goals, loading]);
  useEffect(() => { if (!loading) StorageService.saveSettings(settings); }, [settings, loading]);

  const addTransaction = async (t: any) => {
    const newTx = { ...t, id: crypto.randomUUID(), createdAt: Date.now() };
    setTransactions(prev => [newTx, ...prev]);
  };

  const updateTransaction = async (t: Transaction) => {
    setTransactions(prev => prev.map(tx => tx.id === t.id ? t : tx));
  };

  const deleteTransaction = async (id: string) => {
    setTransactions(prev => prev.filter(tx => tx.id !== id));
  };

  const addAccount = async (acc: Omit<Account, 'id'>) => {
    const newAcc = { ...acc, id: crypto.randomUUID() };
    setAccounts(prev => [...prev, newAcc]);
  };

  const updateAccount = async (acc: Account) => {
    setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a));
  };

  const deleteAccount = async (id: string) => {
    setAccounts(prev => prev.filter(a => a.id !== id));
  };

  const reconcileBalance = async (accId: string, actualBalance: number) => {
    const account = accounts.find(a => a.id === accId);
    if (!account) return;
    const current = getAccountBalance(accId);
    const diff = actualBalance - current;
    await updateAccount({ ...account, initialBalance: account.initialBalance + diff });
  };

  const getAccountBalance = (accountId: string): number => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;
    let balance = Number(account.initialBalance || 0);
    transactions.forEach(t => {
      if (t.status === 'pending') return;
      if (t.accountId === accountId) {
        if (t.type === 'income') balance += t.amount;
        else if (t.type === 'expense') balance -= t.amount;
      }
      if (t.type === 'transfer' && t.destinationAccountId === accountId) {
        balance += t.amount;
      }
    });
    return parseFloat(balance.toFixed(2));
  };

  const getBalanceSummary = (month: string, projectionDate: string): BalanceSummary => {
    const limit = new Date(projectionDate + 'T23:59:59').getTime();
    const realBalance = accounts.reduce((s, acc) => s + getAccountBalance(acc.id), 0);
    let projectedBalance = realBalance;
    let monthlyIncome = 0, monthlyExpense = 0, pendingIncome = 0, pendingExpense = 0;

    transactions.forEach(t => {
      const isPaid = t.status === 'paid';
      const isInc = t.type === 'income';
      const tTime = new Date(t.date + 'T12:00:00').getTime();

      if (!isPaid && tTime <= limit) {
        if (isInc) projectedBalance += t.amount;
        else if (t.type === 'expense') projectedBalance -= t.amount;
      }

      if (t.date.startsWith(month) && t.type !== 'transfer') {
        if (isInc) { 
          if (isPaid) monthlyIncome += t.amount; 
          else pendingIncome += t.amount; 
        } else { 
          if (isPaid) monthlyExpense += t.amount; 
          else pendingExpense += t.amount; 
        }
      }
    });

    return { realBalance, projectedBalance, monthlyIncome, monthlyExpense, pendingIncome, pendingExpense };
  };

  const getSystemAlerts = (): SystemAlert[] => {
    const alerts: SystemAlert[] = [];
    const today = new Date().toISOString().slice(0, 10);
    const next7 = new Date(); next7.setDate(next7.getDate() + 7);
    const next7Str = next7.toISOString().slice(0, 10);

    transactions.filter(t => t.status === 'pending' && t.date <= next7Str).forEach(t => {
      alerts.push({
        id: `alert_${t.id}`,
        title: t.description,
        amount: t.amount,
        date: t.date,
        type: t.date < today ? 'overdue' : t.date === today ? 'today' : 'week',
        isCovered: getAccountBalance(t.accountId) >= t.amount,
        transactionId: t.id
      });
    });
    return alerts;
  };

  const addDebt = async (debt: Omit<Debt, 'id'>, config: any) => {
    const debtId = crypto.randomUUID();
    const newTxs: Transaction[] = [];
    for(let i=0; i<config.installments; i++){
      const tid = crypto.randomUUID();
      const d = new Date(config.firstDate + 'T12:00:00'); d.setMonth(d.getMonth() + i);
      const tx: Transaction = {
        id: tid, debtId,
        description: `${debt.name} (${i+1}/${config.installments})`,
        amount: config.fixedInstallmentValue,
        date: d.toISOString().slice(0, 10),
        type: 'expense', 
        categoryId: config.categoryId, 
        accountId: config.accountId,
        status: config.autoPayPast && d < new Date() ? 'paid' : 'pending',
        installmentNumber: i+1, 
        installmentTotal: config.installments, 
        createdAt: Date.now()
      };
      newTxs.push(tx);
    }
    setTransactions(prev => [...newTxs, ...prev]);
    setDebts(prev => [...prev, { ...debt, id: debtId }]);
  };

  const recalculateDebtSeries = async (transactionId: string, newAmount: number) => {
    const sourceTx = transactions.find(t => t.id === transactionId);
    if (!sourceTx || !sourceTx.debtId) return;

    const diff = newAmount - sourceTx.amount;
    const relatedTxs = transactions.filter(t => t.debtId === sourceTx.debtId && t.status === 'pending' && t.id !== transactionId);

    if (relatedTxs.length === 0) {
      // Just update this one if no more pending
      setTransactions(prev => prev.map(t => t.id === transactionId ? { ...t, amount: newAmount } : t));
      return;
    }

    // Amortization logic: distribute the difference across future pending installments
    const adjustmentPerInstallment = diff / relatedTxs.length;

    setTransactions(prev => prev.map(t => {
      if (t.id === transactionId) return { ...t, amount: newAmount };
      if (t.debtId === sourceTx.debtId && t.status === 'pending') {
        return { ...t, amount: Math.max(0, t.amount - adjustmentPerInstallment) };
      }
      return t;
    }));
  };

  // Added confirmMigration to support MigrationModal component
  const confirmMigration = async (sync: boolean) => {
    if (!sync) {
      StorageService.clearData();
      setTransactions([]);
      setCategories(DEFAULT_CATEGORIES);
      setDebts([]);
      setAccounts([]);
      setBudgets([]);
      setGoals([]);
      setSettings({ 
        theme: 'light', 
        dashboardLayout: DEFAULT_LAYOUT,
        userName: 'Usuário Local'
      } as any);
    }
    // If sync is true, we keep existing local data as it's already in the app's state
    // and correctly managed by StorageService effects.
  };

  return (
    <FinanceContext.Provider value={{
      transactions, categories, debts, accounts, budgets, goals, settings, user, loading, cloudSyncStatus: 'local',
      addTransaction, updateTransaction, deleteTransaction, 
      addAccount, updateAccount, deleteAccount, reconcileBalance,
      addDebt,
      updateDebt: async (id, name) => setDebts(prev => prev.map(d => d.id === id ? { ...d, name } : d)),
      deleteDebt: async (id) => {
        setDebts(prev => prev.filter(d => d.id !== id));
        setTransactions(prev => prev.filter(t => t.debtId !== id));
      },
      addCategory: async (c) => setCategories(prev => [...prev, { ...c, id: `cat_${Date.now()}` }]),
      updateCategory: async (c) => setCategories(prev => prev.map(cat => cat.id === c.id ? c : cat)),
      deleteCategory: async (id) => setCategories(prev => prev.filter(c => c.id !== id)),
      updateSettings: async (s) => setSettings(prev => ({ ...prev, ...s })),
      getBalanceSummary, 
      getDebtProgress: (id) => {
        const d = debts.find(x => x.id === id);
        if(!d) return { paid: 0, remaining: 0, progress: 0, status: 'paid', totalReal: 0 };
        const txs = transactions.filter(t => t.debtId === id);
        const p = txs.filter(t => t.status === 'paid').reduce((s,t) => s+t.amount, 0);
        const tr = txs.reduce((s,t) => s+t.amount, 0);
        return { paid: p, remaining: Math.max(0, tr - p), progress: tr > 0 ? (p/tr)*100 : 0, status: (tr-p) <= 0.01 ? 'paid' : 'active', totalReal: tr };
      },
      getAccountBalance, getSystemAlerts, logout: () => {
        // For local storage, logout just clears the mock user or doesn't do much
        StorageService.clearData();
        window.location.reload();
      },
      saveBudget: async (b) => setBudgets(prev => [...prev.filter(x => x.categoryId !== b.categoryId), b]),
      deleteBudget: async (id) => setBudgets(prev => prev.filter(b => b.categoryId !== id)),
      addGoal: async (g) => setGoals(prev => [...prev, { ...g, id: crypto.randomUUID() }]),
      updateGoal: async (g) => setGoals(prev => prev.map(x => x.id === g.id ? g : x)),
      deleteGoal: async (id) => setGoals(prev => prev.filter(x => x.id !== id)),
      refreshData: () => window.location.reload(),
      recalculateDebtSeries,
      restoreAutoBackup: () => StorageService.restoreAutoBackup(),
      getBackupInfo: () => StorageService.getAutoBackupInfo(),
      confirmMigration
    }}>
      {children}
    </FinanceContext.Provider>
  );
};

export const useFinance = () => {
  const context = useContext(FinanceContext);
  if (!context) throw new Error("useFinance deve ser usado dentro de FinanceProvider");
  return context;
};

