  user: any;
  loading: boolean;
  cloudSyncStatus: 'synced' | 'syncing' | 'error' | 'local';

  addTransaction: (t: Omit<Transaction, 'id' | 'createdAt'>) => Promise<void>;
  updateTransaction: (t: Transaction) => Promise<void>;
  deleteTransaction: (id: string) => Promise<void>;
  addAccount: (acc: Omit<Account, 'id'>) => Promise<void>;
  updateAccount: (acc: Account) => Promise<void>;
  deleteAccount: (id: string) => Promise<void>;
  reconcileBalance: (accountId: string, actualBalance: number) => Promise<void>;
  addDebt: (debt: Omit<Debt, 'id'>, config: any) => Promise<void>;
  updateDebt: (id: string, name: string, installments: number) => Promise<void>;
  deleteDebt: (id: string) => Promise<void>;
