  updateGoal: (goal: Goal) => Promise<void>;
  deleteGoal: (id: string) => Promise<void>;
  refreshData: () => void;
  recalculateDebtSeries: (transactionId: string, newAmount: number) => Promise<void>;
  restoreAutoBackup: () => boolean;
  getBackupInfo: () => any;
  confirmMigration: (sync: boolean) => Promise<void>;
}

