        return { paid: p, remaining: Math.max(0, tr - p), progress: tr > 0 ? (p/tr)*100 : 0, status: (tr-p) <= 0.01 ? 'paid' : 'active', totalReal: tr };
      },
      getAccountBalance, getSystemAlerts, logout: () => {
        StorageService.clearData();
        window.location.reload();
      },
      saveBudget: async (b) => setBudgets(prev => [...prev.filter(x => x.categoryId !== b.categoryId), b]),
      deleteBudget: async (id) => setBudgets(prev => prev.filter(b => b.categoryId !== id)),
      addGoal: async (g) => setGoals(prev => [...prev, { ...g, id: generateUUID() }]),
      updateGoal: async (g) => setGoals(prev => prev.map(x => x.id === g.id ? g : x)),
      deleteGoal: async (id) => setGoals(prev => prev.filter(x => x.id !== id)),
      refreshData: () => window.location.reload(),
      recalculateDebtSeries,
      restoreAutoBackup: () => StorageService.restoreAutoBackup(),
      getBackupInfo: () => StorageService.getAutoBackupInfo(),
      confirmMigration
    }}>
      {children}
    </FinanceContext.Provider>
  );
};

