  recalculateDebtSeries: (transactionId: string, newAmount: number) => Promise<void>;
  restoreAutoBackup: () => boolean;
  getBackupInfo: () => any;
}

const FinanceContext = createContext<FinanceContextType | undefined>(undefined);

const DEFAULT_LAYOUT: DashboardWidgetConfig[] = [
  { id: 'balance', visible: true, label: 'Saldo' },
  { id: 'shortcuts', visible: true, label: 'Atalhos' },
  { id: 'status', visible: true, label: 'Status' },
  { id: 'recent', visible: true, label: 'Recentes' },
  { id: 'debts', visible: true, label: 'Dívidas' }
];

export const FinanceProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user] = useState<any>({ uid: 'local-user', displayName: 'Usuário' });
  const [loading, setLoading] = useState(true);

  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [categories, setCategories] = useState<Category[]>(DEFAULT_CATEGORIES);
  const [debts, setDebts] = useState<Debt[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [budgets, setBudgets] = useState<Budget[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<AppSettings>({ 
    theme: 'light', 
    dashboardLayout: DEFAULT_LAYOUT,
    userName: 'Usuário'
  } as any);

  useEffect(() => {
    const loadData = () => {
      try {
        const t = StorageService.getTransactions();
        const c = StorageService.getCategories();
        const d = StorageService.getDebts();
        const a = StorageService.getAccounts();
        const b = StorageService.getBudgets();
        const g = StorageService.getGoals();
        const s = StorageService.getSettings();

        if (t) setTransactions(t);
        if (c && c.length > 0) setCategories(c);
        if (d) setDebts(d);
        if (a) setAccounts(a);
        if (b) setBudgets(b);
        if (g) setGoals(g);
        if (s) setSettings(prev => ({ ...prev, ...s, dashboardLayout: s.dashboardLayout || DEFAULT_LAYOUT }));
      } catch (e) {
        console.error("Erro ao carregar do LocalStorage:", e);
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, []);

  // Sync back to local storage on changes
  useEffect(() => { if (!loading) StorageService.saveTransactions(transactions); }, [transactions, loading]);
  useEffect(() => { if (!loading) StorageService.saveCategories(categories); }, [categories, loading]);
  useEffect(() => { if (!loading) StorageService.saveDebts(debts); }, [debts, loading]);
  useEffect(() => { if (!loading) StorageService.saveAccounts(accounts); }, [accounts, loading]);
  useEffect(() => { if (!loading) StorageService.saveBudgets(budgets); }, [budgets, loading]);
  useEffect(() => { if (!loading) StorageService.saveGoals(goals); }, [goals, loading]);
  useEffect(() => { if (!loading) StorageService.saveSettings(settings); }, [settings, loading]);

  const addTransaction = async (t: any) => {
    const newTx = { ...t, id: generateUUID(), createdAt: Date.now() };
    setTransactions(prev => [newTx, ...prev]);
  };

  const updateTransaction = async (t: Transaction) => {
    setTransactions(prev => prev.map(tx => tx.id === t.id ? t : tx));
  };

  const deleteTransaction = async (id: string) => {
    setTransactions(prev => prev.filter(tx => tx.id !== id));
  };

  const addAccount = async (acc: Omit<Account, 'id'>) => {
    const newAcc = { ...acc, id: generateUUID() };
    setAccounts(prev => [...prev, newAcc]);
  };

  const updateAccount = async (acc: Account) => {
    setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a));
  };

  const deleteAccount = async (id: string) => {
    setAccounts(prev => prev.filter(a => a.id !== id));
  };

  const reconcileBalance = async (accId: string, actualBalance: number) => {
    const account = accounts.find(a => a.id === accId);
    if (!account) return;
    const current = getAccountBalance(accId);
    const diff = actualBalance - current;
    await updateAccount({ ...account, initialBalance: account.initialBalance + diff });
  };

  const getAccountBalance = (accountId: string): number => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;
    let balance = Number(account.initialBalance || 0);
    transactions.forEach(t => {
      if (t.status === 'pending') return;
      if (t.accountId === accountId) {
        if (t.type === 'income') balance += t.amount;
        else if (t.type === 'expense') balance -= t.amount;
      }
      if (t.type === 'transfer' && t.destinationAccountId === accountId) {
        balance += t.amount;
      }
    });
    return parseFloat(balance.toFixed(2));
  };

  const getBalanceSummary = (month: string, projectionDate: string): BalanceSummary => {
    const limit = new Date(projectionDate + 'T23:59:59').getTime();
    const realBalance = accounts.reduce((s, acc) => s + getAccountBalance(acc.id), 0);
    let projectedBalance = realBalance;
    let monthlyIncome = 0, monthlyExpense = 0, pendingIncome = 0, pendingExpense = 0;

    transactions.forEach(t => {
      const isPaid = t.status === 'paid';
      const isInc = t.type === 'income';
      const tTime = new Date(t.date + 'T12:00:00').getTime();

      if (!isPaid && tTime <= limit) {
        if (isInc) projectedBalance += t.amount;
        else if (t.type === 'expense') projectedBalance -= t.amount;
      }

      if (t.date.startsWith(month) && t.type !== 'transfer') {
        if (isInc) { 
          if (isPaid) monthlyIncome += t.amount; 
          else pendingIncome += t.amount; 
        } else { 
          if (isPaid) monthlyExpense += t.amount; 
          else pendingExpense += t.amount; 
        }
      }
    });

    return { realBalance, projectedBalance, monthlyIncome, monthlyExpense, pendingIncome, pendingExpense };
  };

  const getSystemAlerts = (): SystemAlert[] => {
    const alerts: SystemAlert[] = [];
    const today = new Date().toISOString().slice(0, 10);
    const next7 = new Date(); next7.setDate(next7.getDate() + 7);
    const next7Str = next7.toISOString().slice(0, 10);

    transactions.filter(t => t.status === 'pending' && t.date <= next7Str).forEach(t => {
      alerts.push({
        id: `alert_${t.id}`,
        title: t.description,
        amount: t.amount,
        date: t.date,
        type: t.date < today ? 'overdue' : t.date === today ? 'today' : 'week',
        isCovered: getAccountBalance(t.accountId) >= t.amount,
        transactionId: t.id
      });
    });
    return alerts;
  };

  const addDebt = async (debt: Omit<Debt, 'id'>, config: any) => {
    const debtId = generateUUID();
    const newTxs: Transaction[] = [];
    for(let i=0; i<config.installments; i++){
      const tid = generateUUID();
      const d = new Date(config.firstDate + 'T12:00:00'); d.setMonth(d.getMonth() + i);
      const tx: Transaction = {
        id: tid, debtId,
        description: `${debt.name} (${i+1}/${config.installments})`,
        amount: config.fixedInstallmentValue,
        date: d.toISOString().slice(0, 10),
        type: 'expense', 
        categoryId: config.categoryId, 
        accountId: config.accountId,
        status: config.autoPayPast && d < new Date() ? 'paid' : 'pending',
        installmentNumber: i+1, 
        installmentTotal: config.installments, 
        createdAt: Date.now()
      };
      newTxs.push(tx);
    }
    setTransactions(prev => [...newTxs, ...prev]);
    setDebts(prev => [...prev, { ...debt, id: debtId }]);
  };

  const recalculateDebtSeries = async (transactionId: string, newAmount: number) => {
    const sourceTx = transactions.find(t => t.id === transactionId);
    if (!sourceTx || !sourceTx.debtId) return;

    const diff = newAmount - sourceTx.amount;
    const relatedTxs = transactions.filter(t => t.debtId === sourceTx.debtId && t.status === 'pending' && t.id !== transactionId);

    if (relatedTxs.length === 0) {
      setTransactions(prev => prev.map(t => t.id === transactionId ? { ...t, amount: newAmount } : t));
      return;
    }

    const adjustmentPerInstallment = diff / relatedTxs.length;

    setTransactions(prev => prev.map(t => {
      if (t.id === transactionId) return { ...t, amount: newAmount };
      if (t.debtId === sourceTx.debtId && t.status === 'pending') {
        return { ...t, amount: Math.max(0, t.amount - adjustmentPerInstallment) };
      }
      return t;
    }));
  };

  return (
    <FinanceContext.Provider value={{
      transactions, categories, debts, accounts, budgets, goals, settings, user, loading, cloudSyncStatus: 'local',
      addTransaction, updateTransaction, deleteTransaction, 
      addAccount, updateAccount, deleteAccount, reconcileBalance,
      addDebt,
      updateDebt: async (id, name) => setDebts(prev => prev.map(d => d.id === id ? { ...d, name } : d)),
      deleteDebt: async (id) => {
        setDebts(prev => prev.filter(d => d.id !== id));
        setTransactions(prev => prev.filter(t => t.debtId !== id));
      },
      addCategory: async (c) => setCategories(prev => [...prev, { ...c, id: `cat_${Date.now()}` }]),
      updateCategory: async (c) => setCategories(prev => prev.map(cat => cat.id === c.id ? c : cat)),
      deleteCategory: async (id) => setCategories(prev => prev.filter(c => c.id !== id)),
      updateSettings: async (s) => setSettings(prev => ({ ...prev, ...s })),
      getBalanceSummary, 
      getDebtProgress: (id) => {
        const d = debts.find(x => x.id === id);
        if(!d) return { paid: 0, remaining: 0, progress: 0, status: 'paid', totalReal: 0 };
        const txs = transactions.filter(t => t.debtId === id);
        const p = txs.filter(t => t.status === 'paid').reduce((s,t) => s+t.amount, 0);
        const tr = txs.reduce((s,t) => s+t.amount, 0);
        return { paid: p, remaining: Math.max(0, tr - p), progress: tr > 0 ? (p/tr)*100 : 0, status: (tr-p) <= 0.01 ? 'paid' : 'active', totalReal: tr };
      },
      getAccountBalance, getSystemAlerts, logout: () => {
        StorageService.clearData();
        window.location.reload();
      },
      saveBudget: async (b) => setBudgets(prev => [...prev.filter(x => x.categoryId !== b.categoryId), b]),
      deleteBudget: async (id) => setBudgets(prev => prev.filter(b => b.categoryId !== id)),
      addGoal: async (g) => setGoals(prev => [...prev, { ...g, id: generateUUID() }]),
      updateGoal: async (g) => setGoals(prev => prev.map(x => x.id === g.id ? g : x)),
      deleteGoal: async (id) => setGoals(prev => prev.filter(x => x.id !== id)),
      refreshData: () => window.location.reload(),
      recalculateDebtSeries,
      restoreAutoBackup: () => StorageService.restoreAutoBackup(),
      getBackupInfo: () => StorageService.getAutoBackupInfo()
    }}>
      {children}
    </FinanceContext.Provider>
  );
};

export const useFinance = () => {
  const context = useContext(FinanceContext);
  if (!context) throw new Error("useFinance deve ser usado dentro de FinanceProvider");
  return context;
};

