         <div className="absolute bottom-0 left-0 -ml-10 -mb-10 w-40 h-40 bg-emerald-500 rounded-full blur-[60px] opacity-10"></div>

         <div className="relative z-10">
            <div className="flex justify-between items-start mb-10">
