         >
           {/* Added Clock icon to fix error */}
           <Clock size={14} />
           <span>Ativas ({stats.active.length})</span>
         </button>
         <button 
           onClick={() => setActiveTab('paid')}
           className={`flex-1 py-3.5 rounded-xl text-[10px] font-black uppercase tracking-[0.15em] transition-all flex items-center justify-center space-x-2 ${activeTab === 'paid' ? 'bg-emerald-600 text-white shadow-lg scale-[1.02]' : 'text-slate-400'}`}
         >
           <CheckCircle2 size={14} />
           <span>Quitadas ({stats.paid.length})</span>
         </button>
      </div>

      {/* Debt List Rendering */}
      <div className="space-y-5">
        {displayList.length === 0 ? (
           <div className="text-center py-24 opacity-30 flex flex-col items-center">
