} from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';

const ShortcutButton = ({ icon: Icon, label, color, onClick }: { icon: any, label: string, color: string, onClick: () => void }) => {
  const colorMap: Record<string, string> = {
    blue: 'bg-blue-500/10 text-blue-600 dark:text-blue-400',
    emerald: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400',
    orange: 'bg-orange-500/10 text-orange-600 dark:text-orange-400',
    purple: 'bg-purple-500/10 text-purple-600 dark:text-purple-400',
    rose: 'bg-rose-500/10 text-rose-600 dark:text-rose-400',
    indigo: 'bg-indigo-500/10 text-indigo-600 dark:text-indigo-400'
  };

  return (
    <button 
      onClick={onClick}
      className="flex flex-col items-center space-y-2 group"
    >
      <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all group-active:scale-90 shadow-sm border border-slate-100/50 dark:border-slate-800 ${colorMap[color] || colorMap.blue}`}>
        <Icon size={26} strokeWidth={1.5} />
      </div>
      <span className="text-[10px] font-black text-slate-600 dark:text-slate-400 uppercase tracking-tighter text-center max-w-[64px] leading-tight">{label}</span>
    </button>
  );
};

export const Dashboard = () => {
  const { 
    getBalanceSummary, transactions, categories, getSystemAlerts, 
    accounts, settings, getDebtProgress, debts, getAccountBalance, updateTransaction 
  } = useFinance();

  const navigate = useNavigate();
  const [showValues, setShowValues] = useState(true);
  const [balanceMode, setBalanceMode] = useState<'real' | 'projected'>('real');

  const [isLoaded, setIsLoaded] = useState(false);
  useEffect(() => { setIsLoaded(true); }, []);

  const currentMonth = new Date().toISOString().slice(0, 7);
  const projectionDate = useMemo(() => {
    const now = new Date();
    const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    return endOfMonth.toISOString().slice(0, 10);
  }, []);

  const summary = useMemo(() => 
    getBalanceSummary(currentMonth, projectionDate), 
  [transactions, currentMonth, projectionDate]);

  const alerts = useMemo(() => getSystemAlerts(), [transactions]);

  const totalIncome = summary.monthlyIncome + summary.pendingIncome;
  const totalExpense = summary.monthlyExpense + summary.pendingExpense;
  const flowBalance = totalIncome - totalExpense;
  const budgetUsedPct = totalIncome > 0 ? Math.min(100, (totalExpense / totalIncome) * 100) : 0;

  const recentTransactions = useMemo(() => {
    return [...transactions]
      .sort((a, b) => {
        const dateA = new Date(a.date).getTime();
        const dateB = new Date(b.date).getTime();
        if (dateB !== dateA) return dateB - dateA;
        return (b.createdAt || 0) - (a.createdAt || 0);
      })
      .slice(0, 5);
  }, [transactions]);

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

