       <ShortcutButton icon={Sparkles} label="Insights" color="purple" onClick={() => navigate('/insights')} />
       <ShortcutButton icon={PieChart} label="Resumo" color="indigo" onClick={() => navigate('/summary')} />
       <ShortcutButton icon={Layers} label="Contas" color="rose" onClick={() => navigate('/settings')} />
       <ShortcutButton icon={CalendarDays} label="Agenda" color="blue" onClick={() => navigate('/calendar')} />
    </div>
  );

  const renderAccountCards = () => (
    <div key="accounts-cards" className="px-1 space-y-4">
       <div className="flex justify-between items-center px-1">
          <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">Minhas Contas</h3>
          <Link to="/settings" className="text-[10px] font-black text-indigo-500 uppercase flex items-center">
            Gerenciar <ChevronRight size={14} className="ml-0.5" />
          </Link>
       </div>
       <div className="flex gap-4 overflow-x-auto no-scrollbar pb-2">
          {accounts.length === 0 ? (
            <div onClick={() => navigate('/settings')} className="bg-slate-100 dark:bg-slate-900 border-2 border-dashed border-slate-200 dark:border-slate-800 p-6 rounded-[2.2rem] min-w-[200px] flex flex-col items-center justify-center text-slate-400 cursor-pointer">
               <Plus size={24} className="mb-2" />
               <span className="text-[10px] font-black uppercase">Adicionar Conta</span>
            </div>
          ) : accounts.map(acc => {
            const balance = getAccountBalance(acc.id);
            const isNegative = balance < 0;
            return (
              <div 
                key={acc.id} 
                className="bg-white dark:bg-slate-900 p-6 rounded-[2.2rem] min-w-[210px] shadow-sm border border-slate-100 dark:border-slate-800 flex flex-col justify-between hover:border-indigo-500/30 transition-all cursor-pointer group active:scale-95"
                onClick={() => navigate('/settings')}
              >
                 <div className="flex justify-between items-start mb-6">
                    <div className="w-11 h-11 rounded-xl flex items-center justify-center text-white shadow-sm transition-transform group-hover:scale-110" style={{ backgroundColor: acc.color }}>
                       <Landmark size={22} strokeWidth={1.5} />
                    </div>
                    <div className={`px-2 py-0.5 rounded-lg text-[8px] font-black uppercase ${isNegative ? 'bg-rose-50 text-rose-500' : 'bg-emerald-50 text-emerald-500'}`}>
                       {isNegative ? 'Ajustar' : 'Saldo OK'}
                    </div>
                 </div>
                 <div>
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 truncate">{acc.name}</h4>
                    <p className="text-xl font-black text-slate-800 dark:text-white tabular-nums">
                       {showValues ? formatCurrency(balance) : '••••'}
                    </p>
                 </div>
              </div>
            );
          })}
       </div>
    </div>
  );

  const renderStatus = () => (
    <div key="status" className="bg-white dark:bg-slate-900 p-8 rounded-[2.8rem] shadow-sm border border-slate-100 dark:border-slate-800 relative overflow-hidden group">
       <div className="absolute -right-10 -bottom-10 w-40 h-40 bg-indigo-500/5 rounded-full blur-3xl pointer-events-none"></div>
       <div className="flex justify-between items-end mb-8 relative z-10">
          <div>
             <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2">Desempenho do Mês</h3>
             <p className="text-3xl font-black text-slate-800 dark:text-white leading-none">
                {budgetUsedPct.toFixed(0)}% <span className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">consumo</span>
             </p>
          </div>
          <div className={`flex flex-col items-end`}>
             <div className={`flex items-center space-x-1 px-3 py-1.5 rounded-2xl text-[10px] font-black uppercase tracking-widest ${flowBalance >= 0 ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                {flowBalance >= 0 ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
                <span>{showValues ? formatCurrency(Math.abs(flowBalance)) : '••••'}</span>
             </div>
             <span className="text-[8px] font-black text-slate-300 dark:text-slate-600 uppercase mt-1 tracking-widest">Resultado</span>
          </div>
       </div>
       <div className="relative h-4 bg-slate-100 dark:bg-slate-800/50 rounded-full overflow-hidden p-1 shadow-inner">
          <div 
            className={`h-full rounded-full transition-all duration-1000 ease-out shadow-sm ${budgetUsedPct > 90 ? 'bg-rose-500' : 'bg-gradient-to-r from-indigo-600 to-indigo-400'}`} 
            style={{ width: `${budgetUsedPct}%` }}
          ></div>
       </div>
    </div>
  );

  const renderRecent = () => (
    <div key="recent" className="px-1 space-y-5">
      <div className="flex justify-between items-center px-1">
         <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">Últimas Movimentações</h3>
         <Link to="/transactions" className="text-[10px] font-black text-indigo-500 uppercase tracking-widest hover:text-indigo-600 flex items-center">
            Ver Extrato <ArrowUpRight size={14} className="ml-0.5"/>
         </Link>
      </div>

      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-2 shadow-sm border border-slate-100 dark:border-slate-800 overflow-hidden">
        {recentTransactions.length === 0 ? (
           <div className="text-center py-10 opacity-30">
              <p className="text-xs font-black uppercase tracking-widest text-slate-400">Sem atividade recente</p>
           </div>
        ) : (
          <div className="divide-y divide-slate-50 dark:divide-slate-800">
            {recentTransactions.map((t) => {
               const category = categories.find(c => c.id === t.categoryId);
               const Icon = category ? getIcon(category.icon) : ArrowDownCircle;
               const isExpense = t.type === 'expense';
               const isPending = t.status === 'pending';

               return (
                  <div key={t.id} onClick={() => navigate('/transactions')} className="flex items-center justify-between p-5 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer group">
                     <div className="flex items-center space-x-4 min-w-0">
                        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 shadow-sm border border-slate-50 dark:border-slate-800 z-10 transition-transform group-hover:scale-110 ${isPending ? 'bg-amber-500/10 text-amber-500' : 'bg-slate-50 dark:bg-slate-800'}`}>
                           {isPending ? (
                              <Clock size={22} strokeWidth={2} />
                           ) : (
                              <Icon size={22} strokeWidth={1.5} style={{ color: category?.color || '#64748b' }} />
                           )}
                        </div>
                        <div className="min-w-0">
                           <h4 className="text-sm font-black text-slate-800 dark:text-white truncate leading-tight mb-0.5 group-hover:text-indigo-600 transition-colors">
                              {t.description}
                           </h4>
                           <div className="flex items-center space-x-2">
                              <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{category?.name || 'Geral'}</span>
                              {isPending && <span className="w-1 h-1 bg-amber-500 rounded-full animate-pulse"></span>}
                           </div>
                        </div>
                     </div>

                     <div className="text-right shrink-0 ml-4">
                        <p className={`text-sm font-black tabular-nums ${isPending ? 'text-slate-400' : isExpense ? 'text-slate-800 dark:text-white' : 'text-emerald-500'}`}>
                           {isExpense ? '-' : '+'} {formatCurrency(t.amount)}
                        </p>
                        <p className="text-[8px] font-black text-slate-300 dark:text-slate-600 uppercase tracking-tighter mt-0.5">
                          {new Date(t.date + 'T12:00:00').toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' })}
                        </p>
                     </div>
                  </div>
               );
            })}
          </div>
        )}
      </div>
    </div>
  );

  const widgetMap: Record<string, () => React.ReactNode> = {
    balance: renderBalance,
    shortcuts: renderShortcuts,
    status: renderStatus,
    recent: renderRecent,
    debts: renderAccountCards
  };

  return (
    <div className={`space-y-10 pb-32 transition-opacity duration-700 ${isLoaded ? 'opacity-100' : 'opacity-0'} text-slate-900 dark:text-slate-100`}>

      {/* --- Top Navbar --- */}
      <div className="flex justify-between items-center px-1 pt-4">
        <div className="flex items-center space-x-4">
           <div className="w-12 h-12 rounded-2xl bg-indigo-600 flex items-center justify-center text-white font-black text-xl shadow-lg shadow-indigo-200 dark:shadow-none transition-transform hover:rotate-6 active:scale-90">
             {settings.userName?.charAt(0).toUpperCase() || 'F'}
           </div>
           <div className="flex flex-col">
             <span className="text-[10px] text-slate-400 font-black uppercase tracking-[0.25em] mb-0.5">Olá,</span>
             <h1 className="text-xl font-black text-slate-800 dark:text-white tracking-tight leading-none">{settings.userName || 'Investidor'}</h1>
           </div>
        </div>
        <div className="flex items-center space-x-3">
           <Link to="/alerts" className="relative p-3 bg-white dark:bg-slate-900 rounded-2xl text-slate-400 border border-slate-100 dark:border-slate-800 hover:text-indigo-500 transition-all hover:shadow-md active:scale-90">
             <Bell size={22} />
             {alerts.length > 0 && <span className="absolute top-2.5 right-2.5 w-3 h-3 bg-rose-500 rounded-full border-[3px] border-white dark:border-slate-900 animate-pulse"></span>}
          </Link>
          <Link to="/settings" className="p-3 bg-white dark:bg-slate-900 rounded-2xl text-slate-400 border border-slate-100 dark:border-slate-800 hover:text-indigo-500 transition-all hover:shadow-md active:scale-90">
             <SettingsIcon size={22} />
          </Link>
        </div>
      </div>

      {/* --- Renderização Dinâmica dos Widgets --- */}
      {settings.dashboardLayout.map(widget => {
        if (!widget.visible) return null;
        const renderer = widgetMap[widget.id];
        return renderer ? renderer() : null;
      })}

      {/* Banner de IA */}
      <div className="px-1">
         <div className="bg-gradient-to-br from-indigo-600 to-violet-700 rounded-[2.5rem] p-6 text-white shadow-xl relative overflow-hidden group cursor-pointer active:scale-[0.98] transition-all" onClick={() => navigate('/insights')}>
            <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full blur-3xl -mr-10 -mt-10 pointer-events-none"></div>
            <div className="flex justify-between items-center relative z-10">
               <div className="space-y-1">
                  <div className="flex items-center space-x-2">
                     <Sparkles size={16} className="text-yellow-300" />
                     <span className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-100">Inteligência Artificial</span>
                  </div>
                  <h3 className="text-lg font-black tracking-tight">Onde você pode economizar?</h3>
                  <p className="text-[10px] text-indigo-100 font-bold opacity-80 uppercase tracking-widest">Nossa IA analisou seu perfil</p>
               </div>
               <button className="w-12 h-12 rounded-full bg-white text-indigo-600 flex items-center justify-center shadow-lg group-hover:translate-x-1 transition-transform shrink-0">
                  <ChevronRight size={24} />
               </button>
            </div>
         </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { useFinance } from '../context/FinanceContext';
import { Transaction, TransactionType, TransactionStatus } from '../types';
import { X, Check, Trash2, Bell, BellRing, Repeat, Copy, Layers, Sparkles, Loader2, TrendingUp, ArrowRightLeft, Calculator, AlertTriangle, RefreshCw, Lock, AlertCircle } from 'lucide-react';
import { getIcon } from '../constants';
import { GeminiService } from '../services/geminiService';

interface Props {
  onClose: () => void;
  initialType?: TransactionType;
  transaction?: Transaction | null;
}

export const TransactionForm: React.FC<Props> = ({ onClose, initialType = 'expense', transaction }) => {
  const { addTransaction, updateTransactionSeries, updateDebtTransaction, deleteTransaction, categories, transactions, accounts } = useFinance();

  const [type, setType] = useState<TransactionType>(initialType);
  const [amount, setAmount] = useState('');
  const [description, setDescription] = useState('');
  const [categoryId, setCategoryId] = useState('');
  const [accountId, setAccountId] = useState(''); // Conta de origem
  const [destinationAccountId, setDestinationAccountId] = useState(''); // Conta destino (transferência)
  const [date, setDate] = useState(new Date().toISOString().slice(0, 10));
  const [status, setStatus] = useState<TransactionStatus>('paid');

  // Reminder State
  const [hasReminder, setHasReminder] = useState(false);
  const [reminderDate, setReminderDate] = useState('');

  // Fixed/Recurring State
  const [isFixed, setIsFixed] = useState(false);
  const [showRecurringEditModal, setShowRecurringEditModal] = useState(false);

  // AI State
  const [isPredicting, setIsPredicting] = useState(false);

  // Debt Logic State
  const [baseAmount, setBaseAmount] = useState<number>(0);

  // Modal de confirmação state
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  useEffect(() => {
    // Default Account if none selected
    if (!accountId && accounts.length > 0) {
      setAccountId(accounts[0].id);
    }
  }, [accounts]);

  useEffect(() => {
    if (transaction) {
      setType(transaction.type);
      setAmount(transaction.amount.toString());

      if (transaction.debtId) {
          const originalBase = transaction.amount - (transaction.interest || 0);
          setBaseAmount(originalBase);
      }

      setDescription(transaction.description);
      setCategoryId(transaction.categoryId);
      setAccountId(transaction.accountId || accounts[0]?.id);
      setDestinationAccountId(transaction.destinationAccountId || '');
      setDate(transaction.date);
      setStatus(transaction.status);
      if (transaction.reminderDate) {
        setHasReminder(true);
        setReminderDate(transaction.reminderDate);
      }
      if (transaction.isFixed) {
        setIsFixed(true);
      }
    }
  }, [transaction]);

  const diffAmount = useMemo(() => {
    if (!transaction?.debtId) return 0;
    const currentVal = parseFloat(amount);
    if (isNaN(currentVal)) return 0;
    return currentVal - baseAmount;
  }, [amount, baseAmount, transaction]);

  const isAmountInvalid = transaction?.debtId && diffAmount < -0.01;

  const handleSmartFill = async () => {
    if (!description || description.length < 3) return;
    setIsPredicting(true);
    const prediction = await GeminiService.predictTransaction(description, transactions, categories);
    setIsPredicting(false);
    if (prediction) {
      if (prediction.categoryId) setCategoryId(prediction.categoryId);
      if (prediction.type) setType(prediction.type as TransactionType);
      if (prediction.amount && prediction.amount > 0) setAmount(prediction.amount.toString());
    }
  };

  const handleReminderToggle = () => {
    setHasReminder(!hasReminder);
    if (!hasReminder && !reminderDate) {
       const now = new Date();
       now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
       setReminderDate(now.toISOString().slice(0, 16));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const val = parseFloat(amount);

    if (!val || val <= 0 || !description || !accountId) {
        alert("Preencha todos os campos obrigatórios.");
        return;
    }

    if (isAmountInvalid) {
        alert("Para pagamentos de dívida, o valor não pode ser menor que a parcela original. Para renegociar ou recalcular, vá até a tela de Dívidas.");
        return;
    }

    if (type !== 'transfer' && !categoryId) {
       alert("Selecione uma categoria.");
       return;
    }

    if (type === 'transfer') {
       if (!destinationAccountId) {
         alert("Selecione a conta de destino para a transferência.");
         return;
       }
       if (accountId === destinationAccountId) {
         alert("A conta de origem e destino não podem ser as mesmas.");
         return;
       }
    }

    const data: any = {
      type,
      amount: val,
      description,
      categoryId: type === 'transfer' ? '' : categoryId,
      accountId,
      destinationAccountId: type === 'transfer' ? destinationAccountId : undefined,
      date,
      status,
      reminderDate: (status === 'pending' && hasReminder) ? reminderDate : undefined,
      reminderSent: (status === 'pending' && hasReminder && transaction?.reminderDate === reminderDate) ? transaction.reminderSent : false,
      isFixed,
      interest: (transaction?.debtId && diffAmount > 0.01) ? diffAmount : 0
    };

    if (transaction) {
      if (transaction.debtId) {
         updateDebtTransaction({ ...transaction, ...data }, false);
         onClose();
      } else if (transaction.fixedGroupId) {
         setShowRecurringEditModal(true);
      } else {
         updateTransactionSeries({ ...transaction, ...data }, false);
         onClose();
      }
    } else {
      addTransaction(data);
      onClose();
    }
  };

  const handleConfirmRecurringUpdate = (updateFuture: boolean) => {
    if (!transaction) return;
    const val = parseFloat(amount);
    const data: any = {
      type, amount: val, description, categoryId: type === 'transfer' ? '' : categoryId,
      accountId, destinationAccountId: type === 'transfer' ? destinationAccountId : undefined,
      date, status,
      reminderDate: (status === 'pending' && hasReminder) ? reminderDate : undefined,
      reminderSent: (status === 'pending' && hasReminder && transaction?.reminderDate === reminderDate) ? transaction.reminderSent : false,
      isFixed
    };
    updateTransactionSeries({ ...transaction, ...data }, updateFuture);
    onClose();
  };

  const handleDelete = () => {
    if (transaction) {
      setShowDeleteConfirm(true);
    }
  };

  const confirmDelete = () => {
    if (transaction) {
      deleteTransaction(transaction.id);
      onClose();
    }
  };

  const filteredCategories = categories.filter(c => c.type === type);

  return (
    <>
      <div className="fixed inset-0 bg-black/50 z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4 backdrop-blur-sm animate-fade-in">
        <div className="bg-white dark:bg-slate-900 w-full max-w-md rounded-t-[2rem] sm:rounded-2xl p-6 shadow-xl animate-slide-up max-h-[90dvh] overflow-y-auto no-scrollbar border border-slate-100 dark:border-slate-800 flex flex-col relative">
          <div className="flex justify-between items-center mb-6 shrink-0">
            <h2 className="text-xl font-bold text-slate-800 dark:text-white">
              {transaction ? 'Editar Lançamento' : 'Novo Lançamento'}
            </h2>
            <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition">
              <X size={20} className="text-slate-500 dark:text-slate-400" />
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4 pb-[env(safe-area-inset-bottom)] sm:pb-0">
            {/* Type Toggle */}
            {!transaction?.debtId && (
                <div className="flex p-1 bg-slate-100 dark:bg-slate-800 rounded-lg">
                <button
                    type="button"
                    className={`flex-1 py-2 text-sm font-medium rounded-md transition ${type === 'expense' ? 'bg-white dark:bg-slate-700 text-rose-600 dark:text-rose-400 shadow-sm' : 'text-slate-500 dark:text-slate-400'}`}
                    onClick={() => { setType('expense'); setCategoryId(''); }}
                >
                    Despesa
                </button>
                <button
                    type="button"
                    className={`flex-1 py-2 text-sm font-medium rounded-md transition ${type === 'income' ? 'bg-white dark:bg-slate-700 text-emerald-600 dark:text-emerald-400 shadow-sm' : 'text-slate-500 dark:text-slate-400'}`}
                    onClick={() => { setType('income'); setCategoryId(''); }}
                >
                    Receita
                </button>
                <button
                    type="button"
                    className={`flex-1 py-2 text-sm font-medium rounded-md transition ${type === 'transfer' ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm' : 'text-slate-500 dark:text-slate-400'}`}
                    onClick={() => { setType('transfer'); setCategoryId(''); setDescription('Transferência'); }}
                >
                    Transf.
                </button>
                </div>
            )}

            {/* Description */}
            {type !== 'transfer' && (
              <div>
                <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Descrição</label>
                <div className="relative">
                  <input
                    type="text"
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    className="w-full pl-4 pr-12 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none dark:text-white"
                    placeholder="Ex: Uber, Netflix..."
                    required
                  />
                  {!transaction && (
                    <button type="button" onClick={handleSmartFill} disabled={isPredicting} className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-indigo-100 dark:bg-indigo-900/50 text-indigo-600 dark:text-indigo-400 rounded-lg hover:bg-indigo-200 transition-colors disabled:opacity-50">
                      {isPredicting ? <Loader2 size={18} className="animate-spin" /> : <Sparkles size={18} />}
                    </button>
                  )}
                </div>
              </div>
            )}

            {/* Amount */}
            <div>
              <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Valor</label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-medium">R$</span>
                <input
                  type="number"
                  step="0.01"
                  min={transaction?.debtId ? baseAmount : 0.01}
                  value={amount}
                  onChange={(e) => setAmount(e.target.value)}
                  className={`w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border rounded-xl focus:ring-2 outline-none text-lg font-bold transition-colors ${
                     isAmountInvalid 
                        ? 'border-rose-500 text-rose-500 focus:ring-rose-200' 
                        : 'border-slate-200 dark:border-slate-700 focus:ring-indigo-500 text-slate-800 dark:text-white'
                  }`}
                  placeholder="0,00"
                  required
                />
              </div>

              {/* Intelligent Debt Feedback */}
              {transaction?.debtId && (
                 <>
                   {diffAmount > 0.01 && (
                     <div className="mt-2 p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-100 dark:border-amber-900/50 rounded-xl flex items-center space-x-2 animate-fade-in">
                         <TrendingUp size={16} className="text-amber-500 shrink-0" />
                         <div>
                            <span className="text-xs font-bold text-amber-700 dark:text-amber-400 block">
                               Excedente de R$ {diffAmount.toFixed(2)} identificado como Juros.
                            </span>
                            <span className="text-[10px] text-amber-600 dark:text-amber-500">
                               Este valor não abaterá o saldo devedor principal.
                            </span>
                         </div>
                     </div>
                   )}
                   {isAmountInvalid && (
                     <div className="mt-2 p-3 bg-rose-50 dark:bg-rose-900/20 border border-rose-100 dark:border-rose-900/50 rounded-xl flex items-center space-x-2 animate-shake">
                         <Lock size={16} className="text-rose-500 shrink-0" />
                         <span className="text-xs font-bold text-rose-700 dark:text-rose-400">
                            Não é possível diminuir o valor aqui. Use a tela de Dívidas para recalcular.
                         </span>
                     </div>
                   )}
                 </>
              )}
            </div>

            {/* Accounts Selection */}
            {type === 'transfer' ? (
               <div className="bg-slate-50 dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700 flex flex-col space-y-4 relative">
                  <div>
                    <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">De (Origem)</label>
                    <select
                      value={accountId}
                      onChange={(e) => setAccountId(e.target.value)}
                      className="w-full p-2 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg text-sm dark:text-white"
                    >
                      {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                    </select>
                  </div>

                  <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white dark:bg-slate-600 rounded-full p-1 border border-slate-200 dark:border-slate-500 shadow-sm z-10">
                     <ArrowRightLeft size={16} className="text-slate-400 dark:text-slate-200" />
                  </div>

                  <div>
                    <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Para (Destino)</label>
                    <select
                      value={destinationAccountId}
                      onChange={(e) => setDestinationAccountId(e.target.value)}
                      className="w-full p-2 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg text-sm dark:text-white"
                    >
                      <option value="">Selecione...</option>
                      {accounts.filter(a => a.id !== accountId).map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                    </select>
                  </div>
               </div>
            ) : (
               <div>
                  <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Conta / Carteira</label>
                  <select
                    value={accountId}
                    onChange={(e) => setAccountId(e.target.value)}
                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm dark:text-white"
                  >
                    {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                  </select>
               </div>
            )}

            {/* Date & Status */}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Data</label>
                <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none text-sm dark:text-white" required />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Status</label>
                <select value={status} onChange={(e) => setStatus(e.target.value as TransactionStatus)} className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none text-sm dark:text-white">
                  <option value="paid">{type === 'expense' ? 'Pago' : type === 'transfer' ? 'Realizado' : 'Recebido'}</option>
                  <option value="pending">Pendente</option>
                </select>
              </div>
            </div>

            {/* Recurring Toggle */}
            {!transaction && !transaction?.debtId && type !== 'transfer' && (
              <div className="bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 p-4 rounded-xl flex items-center justify-between">
                 <div className="flex items-center space-x-2">
                    <Repeat className="text-slate-500 dark:text-slate-400" size={18} />
                    <span className="text-sm font-semibold text-slate-700 dark:text-slate-200">Transação Fixa (Mensal)</span>
                 </div>
                 <button type="button" onClick={() => setIsFixed(!isFixed)} className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${isFixed ? 'bg-indigo-600' : 'bg-slate-300 dark:bg-slate-600'}`}>
                   <span className={`inline-block h-3 w-3 transform rounded-full bg-white transition-transform ${isFixed ? 'translate-x-5' : 'translate-x-1'}`} />
                 </button>
              </div>
            )}

            {/* Reminder Section */}
            {status === 'pending' && (
              <div className="bg-indigo-50 dark:bg-indigo-900/20 p-4 rounded-xl border border-indigo-100 dark:border-indigo-900/50 transition-all">
                <div className="flex justify-between items-center mb-2">
                  <div className="flex items-center space-x-2 text-indigo-700 dark:text-indigo-300 font-semibold text-sm">
                    {hasReminder ? <BellRing size={16} /> : <Bell size={16} />}
                    <span>Definir Lembrete</span>
                  </div>
                  <button type="button" onClick={handleReminderToggle} className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${hasReminder ? 'bg-indigo-600' : 'bg-slate-300 dark:bg-slate-700'}`}>
                    <span className={`inline-block h-3 w-3 transform rounded-full bg-white transition-transform ${hasReminder ? 'translate-x-5' : 'translate-x-1'}`} />
                  </button>
                </div>
                {hasReminder && (
                   <input type="datetime-local" value={reminderDate} onChange={(e) => setReminderDate(e.target.value)} className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-indigo-200 dark:border-indigo-800 rounded-lg text-sm text-slate-700 dark:text-slate-200 outline-none" />
                )}
              </div>
            )}

            {/* Category Selection */}
            {type !== 'transfer' && (
              <div>
                <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-2">Categoria</label>
                <div className="grid grid-cols-3 sm:grid-cols-4 gap-2 max-h-52 overflow-y-auto no-scrollbar p-1">
                    {filteredCategories.map(cat => {
                      const Icon = getIcon(cat.icon);
                      const isSelected = categoryId === cat.id;
                      return (
                        <button
                          key={cat.id}
                          type="button"
                          onClick={() => setCategoryId(cat.id)}
                          className={`flex flex-col items-center justify-center p-2 rounded-xl border transition min-h-[80px] h-full ${
                            isSelected 
                              ? `bg-indigo-50 dark:bg-indigo-900/30 border-indigo-500 text-indigo-700 dark:text-indigo-400 shadow-sm` 
                              : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                          }`}
                        >
                          <Icon size={20} className="mb-1.5 shrink-0" />
                          <span className="text-[10px] leading-tight text-center break-words w-full line-clamp-2">{cat.name}</span>
                        </button>
                      );
                    })}
                </div>
              </div>
            )}

            <div className="flex space-x-3 pt-4 pb-4 sm:pb-0">
              {transaction && (
                <button type="button" onClick={handleDelete} className="flex-none w-14 flex items-center justify-center bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-xl hover:bg-red-100 dark:hover:bg-red-900/40 transition">
                  <Trash2 size={20} />
                </button>
              )}
              <button 
                type="submit" 
                disabled={isAmountInvalid}
                className="flex-1 py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg hover:shadow-xl transition-all flex items-center justify-center space-x-2 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <Check size={20} />
                <span>{transaction ? 'Salvar Alterações' : 'Salvar Transação'}</span>
              </button>
            </div>
          </form>

          {/* CONFIRMATION OVERLAY - replaces window.confirm */}
          {showDeleteConfirm && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm rounded-t-[2rem] sm:rounded-2xl">
                <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-2xl w-3/4 text-center border border-slate-100 dark:border-slate-800 animate-scale-in">
                    <div className="w-12 h-12 bg-rose-100 dark:bg-rose-900/30 text-rose-600 dark:text-rose-400 rounded-full flex items-center justify-center mx-auto mb-4">
                        <Trash2 size={24} />
                    </div>
                    <h3 className="text-lg font-black text-slate-800 dark:text-white mb-2">Excluir?</h3>
                    <p className="text-xs text-slate-500 dark:text-slate-400 mb-6 font-medium">Esta ação é irreversível.</p>
                    <div className="flex space-x-3">
                        <button onClick={() => setShowDeleteConfirm(false)} className="flex-1 py-3 text-slate-500 font-bold bg-slate-100 dark:bg-slate-800 rounded-xl text-xs uppercase tracking-wider">Cancelar</button>
                        <button onClick={confirmDelete} className="flex-1 py-3 text-white font-bold bg-rose-500 rounded-xl shadow-lg shadow-rose-200 dark:shadow-none text-xs uppercase tracking-wider">Excluir</button>
                    </div>
                </div>
            </div>
          )}
        </div>
      </div>

      {showRecurringEditModal && (
        <div className="fixed inset-0 bg-black/60 z-[120] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
           <div className="bg-white dark:bg-slate-900 rounded-2xl p-6 w-full max-w-sm shadow-2xl border border-slate-200 dark:border-slate-800 animate-scale-in">
              <div className="flex justify-center mb-4 text-indigo-600 dark:text-indigo-400">
                 <Layers size={48} />
              </div>
              <h3 className="text-lg font-bold text-center text-slate-800 dark:text-white mb-2">Editar Transação Fixa</h3>
              <p className="text-center text-sm text-slate-500 dark:text-slate-400 mb-6">
                Você está editando uma transação recorrente. Como deseja aplicar as alterações?
              </p>

              <div className="space-y-3">
                 <button onClick={() => handleConfirmRecurringUpdate(false)} className="w-full py-3 px-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700 rounded-xl flex items-center transition">
                    <div className="bg-slate-100 dark:bg-slate-700 p-2 rounded-lg mr-3">
                       <Copy size={20} className="text-slate-500 dark:text-slate-300"/>
                    </div>
                    <div className="text-left">
                       <span className="block text-sm font-bold text-slate-700 dark:text-slate-200">Apenas esta</span>
                       <span className="block text-[10px] text-slate-400">Alterar somente o lançamento atual</span>
                    </div>
                 </button>
                 <button onClick={() => handleConfirmRecurringUpdate(true)} className="w-full py-3 px-4 bg-indigo-50 dark:bg-indigo-900/20 border border-indigo-100 dark:border-indigo-800/50 hover:bg-indigo-100 dark:hover:bg-indigo-900/30 rounded-xl flex items-center transition">
                    <div className="bg-indigo-100 dark:bg-indigo-800 p-2 rounded-lg mr-3">
                       <Layers size={20} className="text-indigo-600 dark:text-indigo-300"/>
                    </div>
                    <div className="text-left">
                       <span className="block text-sm font-bold text-indigo-700 dark:text-indigo-300">Esta e futuras</span>
                       <span className="block text-[10px] text-indigo-400/80">Aplicar em todos os lançamentos seguintes</span>
                    </div>
                 </button>
                 <button onClick={() => setShowRecurringEditModal(false)} className="w-full py-3 text-sm font-bold text-slate-400 hover:text-slate-600 dark:hover:text-slate-300">Cancelar</button>
              </div>
           </div>
        </div>
      )}
    </>
  );
};

import React, { useState, useRef } from 'react';
import { Link } from 'react-router-dom';
import { 
  ChevronRight, Layers, Trash2, Moon, Sun, Download, 
  Upload, Palette, Plus, X, Wallet, CheckCircle2, 
  TrendingUp, FileSpreadsheet, RefreshCw,
  ShieldCheck, Landmark, History, User, Bell, Clock,
  ChevronLeft, LayoutGrid, Database, AppWindow,
  GripVertical, Eye, EyeOff, ArrowUp, ArrowDown, AlertTriangle
} from 'lucide-react';
import { StorageService } from '../services/storageService';
import { useFinance } from '../context/FinanceContext';
import { Account, DashboardWidgetConfig } from '../types';

export const Settings = () => {
  const { 
    refreshData, settings, updateSettings, transactions, categories, 
    debts, accounts, budgets, goals, 
    addAccount, updateAccount, deleteAccount, reconcileBalance, getAccountBalance, 
    restoreAutoBackup, getBackupInfo 
  } = useFinance();

  const [isAccountModalOpen, setIsAccountModalOpen] = useState(false);
  const [isReconcileModalOpen, setIsReconcileModalOpen] = useState(false);
  const [isLayoutModalOpen, setIsLayoutModalOpen] = useState(false);

  // Custom Confirmation Modal State
  const [confirmation, setConfirmation] = useState<{ title: string; message: string; onConfirm?: () => void; isAlert?: boolean } | null>(null);

  // Account Form State
  const [editingAccount, setEditingAccount] = useState<Account | null>(null);
  const [accName, setAccName] = useState('');
  const [accType, setAccType] = useState<'wallet'|'bank'|'investment'>('bank');
  const [accColor, setAccColor] = useState('#6366f1');

  // Reconcile State
  const [reconcileAccountId, setReconcileAccountId] = useState('');
  const [actualBalance, setActualBalance] = useState('');

  const backupInputRef = useRef<HTMLInputElement>(null);
  const backupInfo = getBackupInfo();

  const handleClearData = () => {
    setConfirmation({
        title: 'Apagar Tudo',
        message: 'Tem certeza que deseja apagar todos os dados? Esta ação não pode ser desfeita.',
        onConfirm: () => {
            StorageService.clearData();
            refreshData();
            setConfirmation({ title: 'Sucesso', message: 'Dados apagados com sucesso.', isAlert: true });
            setTimeout(() => window.location.reload(), 1500);
        }
    });
  };

  const openAccountModal = (acc?: Account) => {
    if (acc) {
      setEditingAccount(acc);
      setAccName(acc.name);
      setAccType(acc.type as any);
      setAccColor(acc.color);
    } else {
      setEditingAccount(null);
      setAccName('');
      setAccType('bank');
      setAccColor('#6366f1');
    }
    setIsAccountModalOpen(true);
  };

  const handleSaveAccount = () => {
    if (!accName) return;
    const accountData = {
      name: accName,
      type: accType,
      color: accColor,
      initialBalance: editingAccount ? editingAccount.initialBalance : 0,
      enabled: true
    };

    if (editingAccount) {
      updateAccount({ ...editingAccount, ...accountData });
    } else {
      addAccount(accountData);
    }
    setIsAccountModalOpen(false);
  };

  const handleDeleteAccount = (acc: Account) => {
      setConfirmation({
          title: 'Excluir Conta',
          message: 'Deseja excluir esta conta e desvincular todas as transações associadas?',
          onConfirm: () => {
              deleteAccount(acc.id);
              setIsAccountModalOpen(false);
          }
      });
  };

  const openReconcileModal = (acc: Account) => {
    setReconcileAccountId(acc.id);
    setActualBalance(getAccountBalance(acc.id).toString());
    setIsReconcileModalOpen(true);
  };

  const handleReconcile = () => {
    if (!reconcileAccountId || isNaN(parseFloat(actualBalance))) return;
    reconcileBalance(reconcileAccountId, parseFloat(actualBalance));
    setIsReconcileModalOpen(false);
  };

  const handleAutoRestore = () => {
    if (!backupInfo) return;
    setConfirmation({
        title: 'Restaurar Backup',
        message: `Deseja restaurar o backup automático de ${backupInfo.date.toLocaleString()}? Os dados atuais serão substituídos.`,
        onConfirm: () => {
            const success = restoreAutoBackup();
            if (success) {
                setConfirmation({ title: 'Sucesso', message: 'Backup restaurado com sucesso!', isAlert: true });
                setTimeout(() => window.location.reload(), 1500);
            } else {
                setConfirmation({ title: 'Erro', message: 'Falha ao restaurar.', isAlert: true });
            }
        }
    });
  };

  const toggleWidget = (id: string) => {
    const newLayout = settings.dashboardLayout.map(w => 
      w.id === id ? { ...w, visible: !w.visible } : w
    );
    updateSettings({ dashboardLayout: newLayout });
  };

  const moveWidget = (index: number, direction: 'up' | 'down') => {
    const newLayout = [...settings.dashboardLayout];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newLayout.length) return;

    [newLayout[index], newLayout[targetIndex]] = [newLayout[targetIndex], newLayout[index]];
    updateSettings({ dashboardLayout: newLayout });
  };

  const colors = [
    { key: 'indigo', label: 'Índigo', hex: '#6366f1' },
    { key: 'blue', label: 'Azul', hex: '#3b82f6' },
    { key: 'emerald', label: 'Esmeralda', hex: '#10b981' },
    { key: 'violet', label: 'Violeta', hex: '#8b5cf6' },
    { key: 'rose', label: 'Rosa', hex: '#f43f5e' },
    { key: 'orange', label: 'Laranja', hex: '#f97316' },
  ];

  const handleExport = () => {
      const data = { 
        version: '1.1', 
        timestamp: new Date().toISOString(), 
        transactions, categories, settings, debts, accounts, budgets, goals 
      };

      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a'); 
      a.href = url; 
      const dateStr = new Date().toISOString().slice(0,10);
      a.download = `financas_pro_backup_${dateStr}.json`;
      document.body.appendChild(a); 
      a.click(); 
      document.body.removeChild(a); 
      URL.revokeObjectURL(url);
  };

  const handleRestoreClick = () => { 
      if (backupInputRef.current) {
          backupInputRef.current.value = '';
          backupInputRef.current.click();
      }
  };

  const processRestoreFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      setConfirmation({
          title: 'Importar Backup',
          message: 'ATENÇÃO: Restaurar um backup substituirá TODOS os dados atuais do aplicativo. Deseja continuar?',
          onConfirm: async () => {
              try {
                  const text = await file.text(); 
                  const data = JSON.parse(text);

                  if (!Array.isArray(data.transactions) && !Array.isArray(data.categories)) {
                      throw new Error("Arquivo de backup inválido ou corrompido.");
                  }

                  StorageService.saveTransactions(data.transactions || []); 
                  StorageService.saveCategories(data.categories || []);
                  StorageService.saveSettings(data.settings || {}); 
                  StorageService.saveDebts(data.debts || []); 
                  StorageService.saveAccounts(data.accounts || []);
                  StorageService.saveBudgets(data.budgets || []);
                  StorageService.saveGoals(data.goals || []);

                  const txCount = (data.transactions || []).length;
                  setConfirmation({ 
                      title: 'Sucesso', 
                      message: `Backup restaurado!\nRecuperados: ${txCount} Transações.`, 
                      isAlert: true 
                  });
                  setTimeout(() => window.location.reload(), 2000);

              } catch (err) { 
                  setConfirmation({ title: 'Erro', message: 'Arquivo inválido.', isAlert: true });
                  console.error(err);
              }
          }
      });
      if (backupInputRef.current) backupInputRef.current.value = '';
  };

  const getAccountIcon = (type: string) => {
      switch(type) {
          case 'wallet': return Wallet;
          case 'investment': return TrendingUp;
          case 'bank': default: return Landmark;
      }
  }

  return (
    <div className="pb-32 animate-fade-in text-slate-900 dark:text-slate-100 max-w-md mx-auto relative">

      {/* --- Sticky App Header --- */}
      <div className="sticky top-0 bg-slate-50/80 dark:bg-slate-950/80 backdrop-blur-lg z-30 pt-4 pb-6 px-1 flex items-center">
        <Link to="/" className="p-2 mr-2 hover:bg-white dark:hover:bg-slate-800 rounded-2xl transition-all active:scale-90">
           <ChevronLeft size={24} />
        </Link>
        <h1 className="text-2xl font-black tracking-tight text-slate-800 dark:text-white">Ajustes</h1>
      </div>

      <div className="space-y-8 px-1">

        {/* --- Section: Profile --- */}
        <section className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800 relative overflow-hidden">
           <div className="absolute top-0 right-0 w-24 h-24 bg-indigo-500/5 rounded-full -mr-8 -mt-8"></div>
           <div className="flex items-center space-x-4 relative z-10">
              <div className="w-16 h-16 bg-gradient-to-tr from-indigo-600 to-indigo-400 rounded-3xl flex items-center justify-center text-white shadow-xl shadow-indigo-200 dark:shadow-none">
                 <User size={32} strokeWidth={1.5} />
              </div>
              <div className="flex-1">
                 <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest block mb-1">Seu Perfil</span>
                 <input 
                   value={settings.userName || ''} 
                   onChange={(e) => updateSettings({ userName: e.target.value })} 
                   placeholder="Como quer ser chamado?"
                   className="w-full bg-transparent text-xl font-bold text-slate-800 dark:text-white outline-none placeholder:text-slate-300 dark:placeholder:text-slate-700"
                 />
              </div>
           </div>
        </section>

        {/* --- Section: Dashboard Customization --- */}
        <section className="px-2">
           <button 
             onClick={() => setIsLayoutModalOpen(true)}
             className="w-full bg-white dark:bg-slate-900 rounded-3xl p-5 shadow-sm border border-slate-100 dark:border-slate-800 flex items-center justify-between group active:scale-[0.98] transition-all"
           >
              <div className="flex items-center space-x-3">
                 <div className="p-2.5 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400 rounded-2xl">
                    <LayoutGrid size={22} />
                 </div>
                 <div className="text-left">
                    <span className="text-sm font-bold text-slate-800 dark:text-white block">Organizar Início</span>
                    <span className="text-[10px] text-slate-400">Personalize seus widgets</span>
                 </div>
              </div>
              <ChevronRight size={18} className="text-slate-300 group-hover:translate-x-1 transition" />
           </button>
        </section>

        {/* --- Section: Accounts --- */}
        <section>
           <div className="flex justify-between items-center mb-4 px-2">
              <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center">
                 <Wallet size={14} className="mr-2" /> Patrimônio & Contas
              </h2>
              <button 
                onClick={() => openAccountModal()}
                className="text-[10px] font-bold bg-indigo-600 text-white px-3 py-1.5 rounded-full shadow-lg shadow-indigo-100 dark:shadow-none hover:bg-indigo-700 transition-all flex items-center"
              >
                 <Plus size={12} className="mr-1" /> Nova
              </button>
           </div>

           <div className="grid gap-3">
              {accounts.map(acc => {
                const Icon = getAccountIcon(acc.type);
                const balance = getAccountBalance(acc.id);
                return (
                  <div key={acc.id} className="group bg-white dark:bg-slate-900 rounded-[2rem] p-4 shadow-sm border border-slate-100 dark:border-slate-800 hover:border-indigo-200 dark:hover:border-indigo-800 transition-all flex items-center justify-between">
                     <div className="flex items-center space-x-3 cursor-pointer flex-1" onClick={() => openAccountModal(acc)}>
                        <div className="w-12 h-12 rounded-2xl flex items-center justify-center text-white shadow-sm" style={{ backgroundColor: acc.color }}>
                           <Icon size={24} strokeWidth={1.5} />
                        </div>
                        <div>
                           <h3 className="font-bold text-slate-800 dark:text-white text-sm">{acc.name}</h3>
                           <span className="text-[10px] font-medium text-slate-400">{acc.type === 'wallet' ? 'Dinheiro' : acc.type === 'bank' ? 'Bancário' : 'Investimento'}</span>
                        </div>
                     </div>
                     <div className="text-right">
                        <p className={`font-black text-sm ${balance >= 0 ? 'text-slate-800 dark:text-white' : 'text-rose-500'}`}>
                          R$ {balance.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </p>
                        <button 
                          onClick={(e) => { e.stopPropagation(); openReconcileModal(acc); }}
                          className="text-[9px] font-black text-indigo-500 uppercase tracking-tighter bg-indigo-50 dark:bg-indigo-900/20 px-2 py-1 rounded-lg mt-1 inline-flex items-center hover:bg-indigo-100 transition"
                        >
                           <RefreshCw size={10} className="mr-1" /> Reajustar
                        </button>
