                            </span>
                         </div>
                       ) : (
                         <button 
                           onClick={() => handleDeleteClick(editingId)}
                           className="flex-none w-14 h-14 flex items-center justify-center rounded-2xl bg-red-50 dark:bg-red-900/20 text-red-500 hover:bg-red-100 transition"
                         >
                            <Trash2 size={24} />
                         </button>
                       )
                    )}
                    <button 
                      onClick={handleSave}
                      className="flex-1 h-14 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-bold shadow-lg shadow-indigo-200 dark:shadow-indigo-900/50 text-lg transition-transform active:scale-95 flex items-center justify-center"
                    >
                       {editingId ? 'Salvar Alterações' : 'Criar Categoria'}
                    </button>
                 </div>
              </div>

           </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {deleteConfirmationId && (
        <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-6 backdrop-blur-sm animate-fade-in">
           <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 w-full max-w-sm shadow-2xl border border-slate-100 dark:border-slate-800 animate-scale-in text-center">
              <div className="w-16 h-16 bg-rose-100 dark:bg-rose-900/30 text-rose-600 dark:text-rose-400 rounded-full flex items-center justify-center mx-auto mb-4">
                 <Trash2 size={32} />
              </div>
              <h3 className="text-xl font-black text-slate-800 dark:text-white mb-2">Excluir Categoria?</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-8 font-medium">
                 Você tem certeza que deseja excluir esta categoria permanentemente?
              </p>

              <div className="flex space-x-3">
                 <button 
                   onClick={() => setDeleteConfirmationId(null)}
                   className="flex-1 py-4 text-slate-500 font-bold bg-slate-100 dark:bg-slate-800 rounded-2xl text-xs uppercase tracking-wider"
                 >
                    Cancelar
                 </button>
                 <button 
                   onClick={confirmDelete}
                   className="flex-1 py-4 text-white font-bold bg-rose-600 rounded-2xl text-xs uppercase tracking-wider shadow-lg shadow-rose-200 dark:shadow-none"
                 >
                    Excluir
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { useFinance } from '../context/FinanceContext';
import { getIcon } from '../constants';
import { 
  Eye, EyeOff, TrendingUp, TrendingDown, Calendar, Wallet, 
  ChevronRight, ArrowDownCircle, ArrowRightLeft, Bell, 
  Settings as SettingsIcon, CreditCard, Sparkles, PieChart, 
  Layers, ArrowUpRight, ArrowDownLeft, Clock, CheckCircle2,
  AlertCircle, Zap, Target, CalendarDays, Landmark, Check,
  PlusCircle, ArrowUpCircle, Smartphone, CalendarRange, 
  ChevronDown, Plus, X
} from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';

const ShortcutButton = ({ icon: Icon, label, color, onClick }: { icon: any, label: string, color: string, onClick: () => void }) => {
  const colorMap: Record<string, string> = {
    blue: 'bg-blue-500/10 text-blue-600 dark:text-blue-400',
    emerald: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400',
    orange: 'bg-orange-500/10 text-orange-600 dark:text-orange-400',
    purple: 'bg-purple-500/10 text-purple-600 dark:text-purple-400',
    rose: 'bg-rose-500/10 text-rose-600 dark:text-rose-400',
    indigo: 'bg-indigo-500/10 text-indigo-600 dark:text-indigo-400'
  };

  return (
    <button 
      onClick={onClick}
      className="flex flex-col items-center space-y-2 group shrink-0"
    >
      <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all group-active:scale-90 shadow-sm border border-slate-100/50 dark:border-slate-800 ${colorMap[color] || colorMap.blue}`}>
        <Icon size={26} strokeWidth={1.5} />
      </div>
      <span className="text-[10px] font-black text-slate-600 dark:text-slate-400 uppercase tracking-tighter text-center max-w-[64px] leading-tight">{label}</span>
    </button>
  );
};

export const Dashboard = () => {
  const { 
    getBalanceSummary, transactions, categories, getSystemAlerts, 
    accounts, settings, getAccountBalance, updateTransaction 
  } = useFinance();

  const navigate = useNavigate();
  const [showValues, setShowValues] = useState(true);
  const [balanceMode, setBalanceMode] = useState<'real' | 'projected'>('real');
  const [isDateModalOpen, setIsDateModalOpen] = useState(false);

  // Estado da data de projeção com formato ISO compatível com input[type=date]
  const [projectionDate, setProjectionDate] = useState(() => {
    const now = new Date();
    const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    return endOfMonth.toISOString().slice(0, 10);
  });

  const [isLoaded, setIsLoaded] = useState(false);
  useEffect(() => { setIsLoaded(true); }, []);

  const currentMonth = new Date().toISOString().slice(0, 7);

  // Memoização do resumo para performance
  const summary = useMemo(() => 
    getBalanceSummary(currentMonth, projectionDate), 
  [transactions, currentMonth, projectionDate, accounts]);

  const alerts = useMemo(() => getSystemAlerts(), [transactions]);

  const totalIncome = (summary.monthlyIncome || 0) + (summary.pendingIncome || 0);
  const totalExpense = (summary.monthlyExpense || 0) + (summary.pendingExpense || 0);
  const flowBalance = totalIncome - totalExpense;
  const budgetUsedPct = totalIncome > 0 ? Math.min(100, (totalExpense / totalIncome) * 100) : 0;

  const recentTransactions = useMemo(() => {
    return [...transactions]
      .sort((a, b) => {
        const dateA = new Date(a.date).getTime();
        const dateB = new Date(b.date).getTime();
        if (dateB !== dateA) return dateB - dateA;
        return (b.createdAt || 0) - (a.createdAt || 0);
      })
      .slice(0, 5);
  }, [transactions]);

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const applyPreset = (days: number | 'endMonth' | 'endYear' | 'nextMonth') => {
    const now = new Date();
    let newDate = new Date();

    if (days === 'endMonth') {
        newDate = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    } else if (days === 'nextMonth') {
        newDate = new Date(now.getFullYear(), now.getMonth() + 2, 0);
    } else if (days === 'endYear') {
        newDate = new Date(now.getFullYear(), 11, 31);
    } else if (typeof days === 'number') {
        newDate.setDate(now.getDate() + days);
    }

    setProjectionDate(newDate.toISOString().slice(0, 10));
    setIsDateModalOpen(false);
  };

  // Renderizadores

  const renderBalance = () => (
    <div key="balance" className="relative bg-slate-900 dark:bg-black rounded-[2.8rem] p-8 text-white shadow-2xl shadow-indigo-200/20 dark:shadow-none overflow-hidden group">
      <div className="absolute top-0 right-0 -mr-20 -mt-20 w-80 h-80 bg-indigo-600 rounded-full blur-[110px] opacity-40 group-hover:opacity-60 transition-opacity pointer-events-none"></div>
      <div className="absolute bottom-0 left-0 -ml-10 -mb-10 w-40 h-40 bg-emerald-500 rounded-full blur-[80px] opacity-10 pointer-events-none"></div>

      <div className="relative z-10">
        <div className="flex justify-between items-center mb-10">
          <div className="flex bg-white/5 backdrop-blur-xl rounded-2xl p-1 border border-white/10 shadow-inner">
             <button 
               onClick={() => setBalanceMode('real')} 
               className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${balanceMode === 'real' ? 'bg-indigo-500 text-white shadow-lg' : 'text-slate-400 hover:text-slate-200'}`}
             >
               Agora
             </button>
             <button 
               onClick={() => setBalanceMode('projected')} 
               className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${balanceMode === 'projected' ? 'bg-indigo-500 text-white shadow-lg' : 'text-slate-400 hover:text-slate-200'}`}
             >
               Previsto
             </button>
          </div>
          <button onClick={() => setShowValues(!showValues)} className="text-slate-400 hover:text-white transition-all p-2 bg-white/5 rounded-2xl border border-white/5">
            {showValues ? <Eye size={20} /> : <EyeOff size={20} />}
          </button>
        </div>

        <div className="mb-8">
           <div className="flex items-center justify-between mb-2 ml-1">
              <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.25em] opacity-70">
