             <div className="mt-4 flex items-center space-x-2 animate-fade-in">
               <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-pulse"></div>
               <p className="text-[9px] text-slate-500 font-black uppercase tracking-[0.15em]">
                 Projeção baseada em lançamentos pendentes
