             </div>
           )}
        </div>

        <div className="flex gap-3 mt-4">
           <button onClick={() => navigate('/transactions')} className="flex-1 bg-white/10 hover:bg-white/15 backdrop-blur-md py-4 rounded-3xl border border-white/10 transition-all active:scale-95 flex items-center justify-center space-x-2">
              <PlusCircle size={18} className="text-emerald-400" />
              <span className="text-[11px] font-black uppercase tracking-widest">Lançar</span>
           </button>
           <button onClick={() => navigate('/transactions')} className="flex-1 bg-white/10 hover:bg-white/15 backdrop-blur-md py-4 rounded-3xl border border-white/10 transition-all active:scale-95 flex items-center justify-center space-x-2">
              <ArrowUpCircle size={18} className="text-indigo-400" />
              <span className="text-[11px] font-black uppercase tracking-widest">Transferir</span>
           </button>
        </div>
      </div>
    </div>
  );

  const renderShortcuts = () => (
    <div key="shortcuts" className="px-1 overflow-x-auto no-scrollbar flex space-x-8 pb-4 pt-2">
       <ShortcutButton icon={CreditCard} label="Dívidas" color="orange" onClick={() => navigate('/debts')} />
       <ShortcutButton icon={Sparkles} label="Insights" color="purple" onClick={() => navigate('/insights')} />
       <ShortcutButton icon={PieChart} label="Resumo" color="indigo" onClick={() => navigate('/summary')} />
       <ShortcutButton icon={Layers} label="Contas" color="rose" onClick={() => navigate('/settings')} />
       <ShortcutButton icon={CalendarDays} label="Agenda" color="blue" onClick={() => navigate('/calendar')} />
    </div>
  );

  const renderAccountCards = () => (
    <div key="accounts-cards" className="px-1 space-y-4">
       <div className="flex justify-between items-center px-1">
          <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">Minhas Contas</h3>
          <Link to="/settings" className="text-[10px] font-black text-indigo-500 uppercase flex items-center">
            Gerenciar <ChevronRight size={14} className="ml-0.5" />
