       </div>
       <div className="flex gap-4 overflow-x-auto no-scrollbar pb-2">
          {accounts.length === 0 ? (
            <div onClick={() => navigate('/settings')} className="bg-slate-100 dark:bg-slate-900 border-2 border-dashed border-slate-200 dark:border-slate-800 p-6 rounded-[2.2rem] min-w-[200px] flex flex-col items-center justify-center text-slate-400 cursor-pointer">
               <Plus size={24} className="mb-2" />
               <span className="text-[10px] font-black uppercase">Adicionar Conta</span>
            </div>
          ) : accounts.map(acc => {
            const balance = getAccountBalance(acc.id);
            const isNegative = balance < 0;
            return (
              <div 
