                className="bg-white dark:bg-slate-900 p-6 rounded-[2.2rem] min-w-[210px] shadow-sm border border-slate-100 dark:border-slate-800 flex flex-col justify-between hover:border-indigo-500/30 transition-all cursor-pointer group active:scale-95"
                onClick={() => navigate('/settings')}
              >
                 <div className="flex justify-between items-start mb-6">
                    <div className="w-11 h-11 rounded-xl flex items-center justify-center text-white shadow-sm transition-transform group-hover:scale-110" style={{ backgroundColor: acc.color }}>
                       <Landmark size={22} strokeWidth={1.5} />
                    </div>
                    <div className={`px-2 py-0.5 rounded-lg text-[8px] font-black uppercase ${isNegative ? 'bg-rose-50 text-rose-500' : 'bg-emerald-50 text-emerald-500'}`}>
                       {isNegative ? 'Ajustar' : 'Saldo OK'}
