                 </div>
              </div>
            );
          })}
       </div>
    </div>
  );

  const renderStatus = () => (
    <div key="status" className="bg-white dark:bg-slate-900 p-8 rounded-[2.8rem] shadow-sm border border-slate-100 dark:border-slate-800 relative overflow-hidden group">
       <div className="absolute -right-10 -bottom-10 w-40 h-40 bg-indigo-500/5 rounded-full blur-3xl pointer-events-none"></div>
       <div className="flex justify-between items-end mb-8 relative z-10">
          <div>
             <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2">Desempenho do Mês</h3>
             <p className="text-3xl font-black text-slate-800 dark:text-white leading-none">
                {budgetUsedPct.toFixed(0)}% <span className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">consumo</span>
             </p>
          </div>
