const HubButton = ({ icon: Icon, label, color, onClick, sublabel }: { icon: any, label: string, color: string, onClick: () => void, sublabel?: string }) => {
  const colorMap: Record<string, string> = {
    blue: 'bg-blue-500/10 text-blue-600 dark:text-blue-400 border-blue-500/20',
    emerald: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/20',
    orange: 'bg-orange-500/10 text-orange-600 dark:text-orange-400 border-orange-500/20',
    purple: 'bg-purple-500/10 text-purple-600 dark:text-purple-400 border-purple-500/20',
    rose: 'bg-rose-500/10 text-rose-600 dark:text-rose-400 border-rose-500/20',
    indigo: 'bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 border-indigo-500/20',
    amber: 'bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/20',
    slate: 'bg-slate-500/10 text-slate-600 dark:text-slate-400 border-slate-500/20'
  };

  return (
    <button 
      onClick={onClick}
      className="flex flex-col items-center justify-center p-4 bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm active:scale-95 transition-all group"
    >
      <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-3 transition-all group-hover:scale-110 shadow-sm ${colorMap[color] || colorMap.blue}`}>
        <Icon size={28} strokeWidth={1.5} />
      </div>
      <span className="text-[11px] font-black text-slate-800 dark:text-slate-200 uppercase tracking-tighter text-center leading-tight">{label}</span>
      {sublabel && <span className="text-[8px] font-bold text-slate-400 uppercase mt-1 tracking-widest">{sublabel}</span>}
    </button>
  );
};

