import React, { useState, useMemo, useEffect } from 'react';
import { ChevronLeft, ChevronRight, X, Calendar as CalendarIcon, Check } from 'lucide-react';

interface CalendarModalProps {
  isOpen: boolean;
  onClose: () => void;
  selectedDate: string; // YYYY-MM-DD
  onSelect: (date: string) => void;
  title?: string;
}

export const CalendarModal: React.FC<CalendarModalProps> = ({ isOpen, onClose, selectedDate, onSelect, title = 'Selecionar Data' }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  useEffect(() => {
    if (isOpen && selectedDate) {
      // Evita problemas de fuso horário definindo meio-dia
      setCurrentDate(new Date(selectedDate + 'T12:00:00'));
    }
  }, [isOpen, selectedDate]);

  const daysInMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1).getDay();

  const handlePrevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const handleNextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const handleDayClick = (day: number) => {
    const year = currentDate.getFullYear();
    const month = String(currentDate.getMonth() + 1).padStart(2, '0');
    const dayStr = String(day).padStart(2, '0');
    onSelect(`${year}-${month}-${dayStr}`);
    onClose();
  };

  const handleToday = () => {
    const today = new Date();
    const year = today.getFullYear();
    const month = String(today.getMonth() + 1).padStart(2, '0');
    const dayStr = String(today.getDate()).padStart(2, '0');
    onSelect(`${year}-${month}-${dayStr}`);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-slate-950/70 z-[150] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
      <div className="bg-white dark:bg-slate-900 w-full max-w-sm rounded-[2.5rem] p-6 shadow-2xl animate-scale-in border border-slate-100 dark:border-slate-800">

        {/* Header */}
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-lg font-black text-slate-800 dark:text-white tracking-tight">{title}</h3>
          <button onClick={onClose} className="p-2 bg-slate-50 dark:bg-slate-800 rounded-full hover:bg-slate-100 dark:hover:bg-slate-700 transition">
            <X size={20} className="text-slate-500 dark:text-slate-400" />
          </button>
        </div>

        {/* Month Nav */}
        <div className="flex items-center justify-between mb-6 bg-slate-50 dark:bg-slate-800/50 p-2 rounded-2xl">
          <button onClick={handlePrevMonth} className="p-2 hover:bg-white dark:hover:bg-slate-700 rounded-xl transition text-slate-500 dark:text-slate-400">
            <ChevronLeft size={20} />
          </button>
          <span className="text-sm font-black text-slate-700 dark:text-slate-200 uppercase tracking-widest">
            {currentDate.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' })}
          </span>
          <button onClick={handleNextMonth} className="p-2 hover:bg-white dark:hover:bg-slate-700 rounded-xl transition text-slate-500 dark:text-slate-400">
            <ChevronRight size={20} />
          </button>
        </div>

        {/* Grid */}
        <div className="mb-2">
          <div className="grid grid-cols-7 mb-2">
            {['D', 'S', 'T', 'Q', 'Q', 'S', 'S'].map((d, i) => (
              <div key={i} className="text-center text-[10px] font-black text-slate-400 uppercase">{d}</div>
            ))}
          </div>
          <div className="grid grid-cols-7 gap-1">
            {Array.from({ length: firstDayOfMonth }).map((_, i) => (
              <div key={`empty-${i}`} />
            ))}
            {Array.from({ length: daysInMonth }).map((_, i) => {
              const day = i + 1;
              const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
              const isSelected = selectedDate === dateStr;
              const isToday = new Date().toDateString() === new Date(currentDate.getFullYear(), currentDate.getMonth(), day).toDateString();

              return (
                <button
                  key={day}
                  onClick={() => handleDayClick(day)}
                  className={`
                    h-10 w-full rounded-xl flex items-center justify-center text-sm font-bold transition-all
                    ${isSelected 
                      ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200 dark:shadow-none' 
                      : isToday 
                        ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 border border-indigo-200 dark:border-indigo-800'
                        : 'text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800'
                    }
                  `}
                >
                  {day}
                </button>
              );
            })}
          </div>
        </div>

        {/* Footer */}
        <div className="mt-6 pt-4 border-t border-slate-100 dark:border-slate-800">
           <button 
             onClick={handleToday}
             className="w-full py-3.5 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl active:scale-95 transition-all"
           >
             Hoje
           </button>
        </div>

      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { useFinance } from '../context/FinanceContext';
import { Transaction, TransactionType, TransactionStatus } from '../types';
import { X, Check, Trash2, Bell, BellRing, Repeat, Copy, Layers, Sparkles, Loader2, TrendingUp, ArrowRightLeft, Calculator, AlertTriangle, RefreshCw, Lock, AlertCircle, Calendar as CalendarIcon } from 'lucide-react';
import { getIcon } from '../constants';
import { GeminiService } from '../services/geminiService';
import { CalendarModal } from './CalendarModal';

interface Props {
  onClose: () => void;
  initialType?: TransactionType;
  transaction?: Transaction | null;
}

export const TransactionForm: React.FC<Props> = ({ onClose, initialType = 'expense', transaction }) => {
  const { addTransaction, updateTransactionSeries, updateDebtTransaction, deleteTransaction, categories, transactions, accounts } = useFinance();

  const [type, setType] = useState<TransactionType>(initialType);
  const [amount, setAmount] = useState('');
  const [description, setDescription] = useState('');
  const [categoryId, setCategoryId] = useState('');
  const [accountId, setAccountId] = useState('');
  const [destinationAccountId, setDestinationAccountId] = useState('');
  const [date, setDate] = useState(new Date().toISOString().slice(0, 10));
  const [status, setStatus] = useState<TransactionStatus>('paid');
  const [hasReminder, setHasReminder] = useState(false);
  const [reminderDate, setReminderDate] = useState('');
  const [isFixed, setIsFixed] = useState(false);
  const [showRecurringEditModal, setShowRecurringEditModal] = useState(false);
  const [isPredicting, setIsPredicting] = useState(false);
  const [baseAmount, setBaseAmount] = useState<number>(0);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // Calendar Modal State
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);

  useEffect(() => {
    if (!accountId && accounts.length > 0) {
      setAccountId(accounts[0].id);
    }
  }, [accounts]);

  useEffect(() => {
    if (transaction) {
      setType(transaction.type);
      setAmount(transaction.amount.toString());
      if (transaction.debtId) {
          const originalBase = transaction.amount - (transaction.interest || 0);
          setBaseAmount(originalBase);
      }
      setDescription(transaction.description);
      setCategoryId(transaction.categoryId);
      setAccountId(transaction.accountId || accounts[0]?.id);
      setDestinationAccountId(transaction.destinationAccountId || '');
      setDate(transaction.date);
      setStatus(transaction.status);
      if (transaction.reminderDate) {
        setHasReminder(true);
        setReminderDate(transaction.reminderDate);
      }
      if (transaction.isFixed) {
        setIsFixed(true);
      }
    }
  }, [transaction]);

  const diffAmount = useMemo(() => {
    if (!transaction?.debtId) return 0;
    const currentVal = parseFloat(amount);
    if (isNaN(currentVal)) return 0;
    return currentVal - baseAmount;
  }, [amount, baseAmount, transaction]);

  const isAmountInvalid = transaction?.debtId && diffAmount < -0.01;

  const handleSmartFill = async () => {
    if (!description || description.length < 3) return;
    setIsPredicting(true);
    const prediction = await GeminiService.predictTransaction(description, transactions, categories);
    setIsPredicting(false);
    if (prediction) {
      if (prediction.categoryId) setCategoryId(prediction.categoryId);
      if (prediction.type) setType(prediction.type as TransactionType);
      if (prediction.amount && prediction.amount > 0) setAmount(prediction.amount.toString());
    }
  };

  const handleReminderToggle = () => {
    setHasReminder(!hasReminder);
    if (!hasReminder && !reminderDate) {
       const now = new Date();
       now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
       setReminderDate(now.toISOString().slice(0, 16));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const val = parseFloat(amount);

    if (!val || val <= 0 || !description || !accountId) {
        alert("Preencha todos os campos obrigatórios.");
        return;
    }

    if (isAmountInvalid) {
        alert("Valor inválido para dívida.");
        return;
    }

    if (type !== 'transfer' && !categoryId) {
       alert("Selecione uma categoria.");
       return;
    }

    if (type === 'transfer') {
       if (!destinationAccountId) {
         alert("Selecione a conta de destino.");
         return;
       }
       if (accountId === destinationAccountId) {
         alert("Contas iguais.");
         return;
       }
    }

    const data: any = {
      type, amount: val, description, categoryId: type === 'transfer' ? '' : categoryId,
      accountId, destinationAccountId: type === 'transfer' ? destinationAccountId : undefined,
      date, status,
      reminderDate: (status === 'pending' && hasReminder) ? reminderDate : undefined,
      reminderSent: (status === 'pending' && hasReminder && transaction?.reminderDate === reminderDate) ? transaction.reminderSent : false,
      isFixed,
      interest: (transaction?.debtId && diffAmount > 0.01) ? diffAmount : 0
    };

    if (transaction) {
      if (transaction.debtId) {
         updateDebtTransaction({ ...transaction, ...data }, false);
         onClose();
      } else if (transaction.fixedGroupId) {
         setShowRecurringEditModal(true);
      } else {
         updateTransactionSeries({ ...transaction, ...data }, false);
         onClose();
      }
    } else {
      addTransaction(data);
      onClose();
    }
  };

  const handleConfirmRecurringUpdate = (updateFuture: boolean) => {
    if (!transaction) return;
    const val = parseFloat(amount);
    const data: any = {
      type, amount: val, description, categoryId: type === 'transfer' ? '' : categoryId,
      accountId, destinationAccountId: type === 'transfer' ? destinationAccountId : undefined,
      date, status,
      reminderDate: (status === 'pending' && hasReminder) ? reminderDate : undefined,
      reminderSent: (status === 'pending' && hasReminder && transaction?.reminderDate === reminderDate) ? transaction.reminderSent : false,
      isFixed
    };
    updateTransactionSeries({ ...transaction, ...data }, updateFuture);
    onClose();
  };

  const handleDelete = () => { if (transaction) setShowDeleteConfirm(true); };
  const confirmDelete = () => { if (transaction) { deleteTransaction(transaction.id); onClose(); } };
  const filteredCategories = categories.filter(c => c.type === type);

  return (
    <>
      <div className="fixed inset-0 bg-black/50 z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4 backdrop-blur-sm animate-fade-in">
        <div className="bg-white dark:bg-slate-900 w-full max-w-md rounded-t-[2rem] sm:rounded-2xl p-6 shadow-xl animate-slide-up max-h-[90dvh] overflow-y-auto no-scrollbar border border-slate-100 dark:border-slate-800 flex flex-col relative">
          <div className="flex justify-between items-center mb-6 shrink-0">
            <h2 className="text-xl font-bold text-slate-800 dark:text-white">
              {transaction ? 'Editar Lançamento' : 'Novo Lançamento'}
            </h2>
            <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition">
              <X size={20} className="text-slate-500 dark:text-slate-400" />
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4 pb-[env(safe-area-inset-bottom)] sm:pb-0">
            {!transaction?.debtId && (
                <div className="flex p-1 bg-slate-100 dark:bg-slate-800 rounded-lg">
                <button type="button" className={`flex-1 py-2 text-sm font-medium rounded-md transition ${type === 'expense' ? 'bg-white dark:bg-slate-700 text-rose-600 dark:text-rose-400 shadow-sm' : 'text-slate-500 dark:text-slate-400'}`} onClick={() => { setType('expense'); setCategoryId(''); }}>Despesa</button>
                <button type="button" className={`flex-1 py-2 text-sm font-medium rounded-md transition ${type === 'income' ? 'bg-white dark:bg-slate-700 text-emerald-600 dark:text-emerald-400 shadow-sm' : 'text-slate-500 dark:text-slate-400'}`} onClick={() => { setType('income'); setCategoryId(''); }}>Receita</button>
                <button type="button" className={`flex-1 py-2 text-sm font-medium rounded-md transition ${type === 'transfer' ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm' : 'text-slate-500 dark:text-slate-400'}`} onClick={() => { setType('transfer'); setCategoryId(''); setDescription('Transferência'); }}>Transf.</button>
                </div>
            )}

            {type !== 'transfer' && (
              <div>
                <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Descrição</label>
                <div className="relative">
                  <input type="text" value={description} onChange={(e) => setDescription(e.target.value)} className="w-full pl-4 pr-12 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none dark:text-white" placeholder="Ex: Uber, Netflix..." required />
                  {!transaction && (
                    <button type="button" onClick={handleSmartFill} disabled={isPredicting} className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-indigo-100 dark:bg-indigo-900/50 text-indigo-600 dark:text-indigo-400 rounded-lg hover:bg-indigo-200 transition-colors disabled:opacity-50">
                      {isPredicting ? <Loader2 size={18} className="animate-spin" /> : <Sparkles size={18} />}
                    </button>
                  )}
                </div>
              </div>
            )}

            <div>
              <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Valor</label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-medium">R$</span>
                <input type="number" step="0.01" min={transaction?.debtId ? baseAmount : 0.01} value={amount} onChange={(e) => setAmount(e.target.value)} className={`w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border rounded-xl focus:ring-2 outline-none text-lg font-bold transition-colors ${isAmountInvalid ? 'border-rose-500 text-rose-500 focus:ring-rose-200' : 'border-slate-200 dark:border-slate-700 focus:ring-indigo-500 text-slate-800 dark:text-white'}`} placeholder="0,00" required />
              </div>
              {transaction?.debtId && diffAmount > 0.01 && (
                 <div className="mt-2 p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-100 dark:border-amber-900/50 rounded-xl flex items-center space-x-2 animate-fade-in"><TrendingUp size={16} className="text-amber-500 shrink-0" /><span className="text-xs font-bold text-amber-700 dark:text-amber-400">Excedente de R$ {diffAmount.toFixed(2)} identificado como Juros.</span></div>
              )}
            </div>

            {type === 'transfer' ? (
               <div className="bg-slate-50 dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700 flex flex-col space-y-4 relative">
                  <div>
                    <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">De (Origem)</label>
                    <select value={accountId} onChange={(e) => setAccountId(e.target.value)} className="w-full p-2 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg text-sm dark:text-white">
                      {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                    </select>
                  </div>
                  <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white dark:bg-slate-600 rounded-full p-1 border border-slate-200 dark:border-slate-500 shadow-sm z-10"><ArrowRightLeft size={16} className="text-slate-400 dark:text-slate-200" /></div>
                  <div>
                    <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Para (Destino)</label>
                    <select value={destinationAccountId} onChange={(e) => setDestinationAccountId(e.target.value)} className="w-full p-2 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg text-sm dark:text-white">
                      <option value="">Selecione...</option>
                      {accounts.filter(a => a.id !== accountId).map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                    </select>
                  </div>
               </div>
            ) : (
               <div>
                  <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Conta / Carteira</label>
                  <select value={accountId} onChange={(e) => setAccountId(e.target.value)} className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm dark:text-white">
                    {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                  </select>
               </div>
            )}

            <div className="grid grid-cols-2 gap-4">
              {/* Date Input with Calendar Modal */}
              <div>
                <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Data</label>
                <div 
                  onClick={() => setIsCalendarOpen(true)}
                  className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl flex items-center justify-between cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700/50 transition-colors"
                >
                   <span className="text-sm dark:text-white font-medium">{new Date(date + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                   <CalendarIcon size={18} className="text-slate-400" />
                </div>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Status</label>
                <select value={status} onChange={(e) => setStatus(e.target.value as TransactionStatus)} className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none text-sm dark:text-white">
                  <option value="paid">{type === 'expense' ? 'Pago' : type === 'transfer' ? 'Realizado' : 'Recebido'}</option>
                  <option value="pending">Pendente</option>
                </select>
              </div>
            </div>

            {!transaction && !transaction?.debtId && type !== 'transfer' && (
              <div className="bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 p-4 rounded-xl flex items-center justify-between">
                 <div className="flex items-center space-x-2">
                    <Repeat className="text-slate-500 dark:text-slate-400" size={18} />
                    <span className="text-sm font-semibold text-slate-700 dark:text-slate-200">Transação Fixa (Mensal)</span>
                 </div>
                 <button type="button" onClick={() => setIsFixed(!isFixed)} className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${isFixed ? 'bg-indigo-600' : 'bg-slate-300 dark:bg-slate-600'}`}>
                   <span className={`inline-block h-3 w-3 transform rounded-full bg-white transition-transform ${isFixed ? 'translate-x-5' : 'translate-x-1'}`} />
                 </button>
              </div>
            )}

            {status === 'pending' && (
              <div className="bg-indigo-50 dark:bg-indigo-900/20 p-4 rounded-xl border border-indigo-100 dark:border-indigo-900/50 transition-all">
                <div className="flex justify-between items-center mb-2">
                  <div className="flex items-center space-x-2 text-indigo-700 dark:text-indigo-300 font-semibold text-sm">
                    {hasReminder ? <BellRing size={16} /> : <Bell size={16} />}
                    <span>Definir Lembrete</span>
                  </div>
                  <button type="button" onClick={handleReminderToggle} className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${hasReminder ? 'bg-indigo-600' : 'bg-slate-300 dark:bg-slate-700'}`}>
                    <span className={`inline-block h-3 w-3 transform rounded-full bg-white transition-transform ${hasReminder ? 'translate-x-5' : 'translate-x-1'}`} />
                  </button>
                </div>
                {hasReminder && (
                   <input type="datetime-local" value={reminderDate} onChange={(e) => setReminderDate(e.target.value)} className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-indigo-200 dark:border-indigo-800 rounded-lg text-sm text-slate-700 dark:text-slate-200 outline-none" />
                )}
              </div>
            )}

            {type !== 'transfer' && (
              <div>
                <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-2">Categoria</label>
                <div className="grid grid-cols-3 sm:grid-cols-4 gap-2 max-h-52 overflow-y-auto no-scrollbar p-1">
                    {filteredCategories.map(cat => {
                      const Icon = getIcon(cat.icon);
                      const isSelected = categoryId === cat.id;
                      return (
                        <button key={cat.id} type="button" onClick={() => setCategoryId(cat.id)} className={`flex flex-col items-center justify-center p-2 rounded-xl border transition min-h-[80px] h-full ${isSelected ? `bg-indigo-50 dark:bg-indigo-900/30 border-indigo-500 text-indigo-700 dark:text-indigo-400 shadow-sm` : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'}`}>
                          <Icon size={20} className="mb-1.5 shrink-0" />
                          <span className="text-[10px] leading-tight text-center break-words w-full line-clamp-2">{cat.name}</span>
                        </button>
                      );
                    })}
                </div>
              </div>
            )}

            <div className="flex space-x-3 pt-4 pb-4 sm:pb-0">
              {transaction && (
                <button type="button" onClick={handleDelete} className="flex-none w-14 flex items-center justify-center bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-xl hover:bg-red-100 dark:hover:bg-red-900/40 transition">
                  <Trash2 size={20} />
                </button>
              )}
              <button type="submit" disabled={isAmountInvalid} className="flex-1 py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg hover:shadow-xl transition-all flex items-center justify-center space-x-2 disabled:opacity-50 disabled:cursor-not-allowed">
                <Check size={20} />
                <span>{transaction ? 'Salvar Alterações' : 'Salvar Transação'}</span>
              </button>
            </div>
          </form>

          {showDeleteConfirm && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm rounded-t-[2rem] sm:rounded-2xl">
                <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-2xl w-3/4 text-center border border-slate-100 dark:border-slate-800 animate-scale-in">
                    <div className="w-12 h-12 bg-rose-100 dark:bg-rose-900/30 text-rose-600 dark:text-rose-400 rounded-full flex items-center justify-center mx-auto mb-4"><Trash2 size={24} /></div>
                    <h3 className="text-lg font-black text-slate-800 dark:text-white mb-2">Excluir?</h3>
                    <p className="text-xs text-slate-500 dark:text-slate-400 mb-6 font-medium">Esta ação é irreversível.</p>
                    <div className="flex space-x-3">
                        <button onClick={() => setShowDeleteConfirm(false)} className="flex-1 py-3 text-slate-500 font-bold bg-slate-100 dark:bg-slate-800 rounded-xl text-xs uppercase tracking-wider">Cancelar</button>
                        <button onClick={confirmDelete} className="flex-1 py-3 text-white font-bold bg-rose-500 rounded-xl shadow-lg shadow-rose-200 dark:shadow-none text-xs uppercase tracking-wider">Excluir</button>
                    </div>
                </div>
            </div>
          )}
        </div>
      </div>

      <CalendarModal 
         isOpen={isCalendarOpen} 
         onClose={() => setIsCalendarOpen(false)} 
         selectedDate={date} 
         onSelect={(d) => setDate(d)} 
      />

      {showRecurringEditModal && (
        <div className="fixed inset-0 bg-black/60 z-[120] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
           <div className="bg-white dark:bg-slate-900 rounded-2xl p-6 w-full max-w-sm shadow-2xl border border-slate-200 dark:border-slate-800 animate-scale-in">
              <div className="flex justify-center mb-4 text-indigo-600 dark:text-indigo-400"><Layers size={48} /></div>
              <h3 className="text-lg font-bold text-center text-slate-800 dark:text-white mb-2">Editar Transação Fixa</h3>
              <p className="text-center text-sm text-slate-500 dark:text-slate-400 mb-6">Você está editando uma transação recorrente. Como deseja aplicar as alterações?</p>
              <div className="space-y-3">
                 <button onClick={() => handleConfirmRecurringUpdate(false)} className="w-full py-3 px-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700 rounded-xl flex items-center transition"><div className="bg-slate-100 dark:bg-slate-700 p-2 rounded-lg mr-3"><Copy size={20} className="text-slate-500 dark:text-slate-300"/></div><div className="text-left"><span className="block text-sm font-bold text-slate-700 dark:text-slate-200">Apenas esta</span><span className="block text-[10px] text-slate-400">Alterar somente o lançamento atual</span></div></button>
                 <button onClick={() => handleConfirmRecurringUpdate(true)} className="w-full py-3 px-4 bg-indigo-50 dark:bg-indigo-900/20 border border-indigo-100 dark:border-indigo-800/50 hover:bg-indigo-100 dark:hover:bg-indigo-900/30 rounded-xl flex items-center transition"><div className="bg-indigo-100 dark:bg-indigo-800 p-2 rounded-lg mr-3"><Layers size={20} className="text-indigo-600 dark:text-indigo-300"/></div><div className="text-left"><span className="block text-sm font-bold text-indigo-700 dark:text-indigo-300">Esta e futuras</span><span className="block text-[10px] text-indigo-400/80">Aplicar em todos os lançamentos seguintes</span></div></button>
                 <button onClick={() => setShowRecurringEditModal(false)} className="w-full py-3 text-sm font-bold text-slate-400 hover:text-slate-600 dark:hover:text-slate-300">Cancelar</button>
              </div>
           </div>
        </div>
      )}
    </>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { useFinance } from '../context/FinanceContext';
import { getIcon } from '../constants';
import { 
  Eye, EyeOff, TrendingUp, TrendingDown, Bell, 
  Settings as SettingsIcon, CreditCard, Sparkles, 
  PieChart, Clock, Target, CalendarDays, PlusCircle, 
  ArrowUpCircle, ChevronRight, Receipt, BarChart3,
  AlertCircle, Wallet, X, CalendarRange, Check
} from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import { TransactionForm } from './TransactionForm';
import { TransactionType } from '../types';
import { CalendarModal } from './CalendarModal';

const HubButton = ({ icon: Icon, label, color, onClick }: { icon: any, label: string, color: string, onClick: () => void }) => {
  const colorMap: Record<string, string> = {
    blue: 'bg-blue-500/10 text-blue-600 dark:text-blue-400 border-blue-500/20',
    emerald: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/20',
    orange: 'bg-orange-500/10 text-orange-600 dark:text-orange-400 border-orange-500/20',
    purple: 'bg-purple-500/10 text-purple-600 dark:text-purple-400 border-purple-500/20',
    rose: 'bg-rose-500/10 text-rose-600 dark:text-rose-400 border-rose-500/20',
    indigo: 'bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 border-indigo-500/20',
    amber: 'bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/20',
  };

  return (
    <button 
      onClick={onClick}
      className="flex flex-col items-center justify-center p-4 bg-white dark:bg-slate-900 rounded-[2.2rem] border border-slate-100 dark:border-slate-800 shadow-sm active:scale-95 transition-all group"
    >
      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mb-2.5 transition-all group-hover:scale-110 ${colorMap[color] || colorMap.blue}`}>
        <Icon size={24} strokeWidth={2} />
      </div>
      <span className="text-[10px] font-black text-slate-800 dark:text-slate-200 uppercase tracking-tight text-center">{label}</span>
    </button>
  );
};

export const Dashboard = () => {
  const { 
    getBalanceSummary, transactions, categories, getSystemAlerts, 
    accounts, settings, getAccountBalance 
  } = useFinance();

  const navigate = useNavigate();
  const [showValues, setShowValues] = useState(true);
  const [balanceMode, setBalanceMode] = useState<'real' | 'projected'>('real');
  const [isDateModalOpen, setIsDateModalOpen] = useState(false);
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);

  // State for Transaction Modal Actions
  const [isTransactionModalOpen, setIsTransactionModalOpen] = useState(false);
  const [transactionType, setTransactionType] = useState<TransactionType>('expense');

  const [projectionDate, setProjectionDate] = useState(() => {
    const now = new Date();
    // Default to last day of current month
    return new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().slice(0, 10);
  });

  const [isLoaded, setIsLoaded] = useState(false);
  useEffect(() => { setIsLoaded(true); }, []);

  const currentMonth = new Date().toISOString().slice(0, 7);
  const alerts = useMemo(() => getSystemAlerts(), [transactions]);
  const summary = useMemo(() => getBalanceSummary(currentMonth, projectionDate), [transactions, currentMonth, projectionDate, accounts]);

  const recentTransactions = useMemo(() => {
    return [...transactions]
      .sort((a, b) => {
        const dateA = new Date(a.date).getTime();
        const dateB = new Date(b.date).getTime();
        if (dateB !== dateA) return dateB - dateA;
        return (b.createdAt || 0) - (a.createdAt || 0);
      })
      .slice(0, 4);
  }, [transactions]);

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const getGreeting = () => {
    const hour = new Date().getHours();
    if (hour < 12) return "Bom dia";
    if (hour < 18) return "Boa tarde";
    return "Boa noite";
  };

  const applyPreset = (type: 'endMonth' | 'plus30') => {
    const now = new Date();
    if (type === 'endMonth') {
      setProjectionDate(new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().slice(0, 10));
    } else {
      const future = new Date();
      future.setDate(now.getDate() + 30);
      setProjectionDate(future.toISOString().slice(0, 10));
    }
    setIsDateModalOpen(false);
  };

  const openTransactionModal = (type: TransactionType) => {
    setTransactionType(type);
    setIsTransactionModalOpen(true);
  };

  const openCalendar = () => {
    // setIsDateModalOpen(false); // keep it open or close it? Better UX to close the presets modal if opening calendar, or keep it as parent.
    // Let's close the presets modal and open calendar.
    setIsCalendarOpen(true);
  };

  const handleDateSelect = (d: string) => {
    setProjectionDate(d);
    setIsDateModalOpen(false);
  };

  return (
    <div className={`space-y-8 pb-32 transition-opacity duration-700 ${isLoaded ? 'opacity-100' : 'opacity-0'} text-slate-900 dark:text-slate-100`}>

      {/* Header Contextual */}
      <div className="flex justify-between items-center px-1 pt-4">
        <div className="flex items-center space-x-3">
           <div className="w-12 h-12 rounded-2xl bg-indigo-600 flex items-center justify-center text-white font-black text-xl shadow-lg shadow-indigo-200 dark:shadow-none transition-transform hover:rotate-6">
             {settings.userName?.charAt(0).toUpperCase() || 'F'}
           </div>
           <div className="flex flex-col">
             <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest leading-none mb-1">{getGreeting()},</span>
             <h1 className="text-xl font-black text-slate-800 dark:text-white leading-none tracking-tight">{settings.userName || 'Investidor'}</h1>
           </div>
        </div>
        <div className="flex items-center space-x-2">
           <Link to="/alerts" className="relative p-3 bg-white dark:bg-slate-900 rounded-2xl text-slate-400 border border-slate-100 dark:border-slate-800 transition-all active:scale-90 shadow-sm">
             <Bell size={22} />
             {alerts.length > 0 && <span className="absolute top-2.5 right-2.5 w-3 h-3 bg-rose-500 rounded-full border-[3px] border-white dark:border-slate-950 animate-pulse"></span>}
          </Link>
          <Link to="/settings" className="p-3 bg-white dark:bg-slate-900 rounded-2xl text-slate-400 border border-slate-100 dark:border-slate-800 transition-all active:scale-90 shadow-sm">
             <SettingsIcon size={22} />
          </Link>
        </div>
      </div>

      {/* Hero Card */}
      <div className="relative bg-slate-900 dark:bg-black rounded-[2.8rem] p-8 text-white shadow-2xl overflow-hidden group">
        <div className="absolute top-0 right-0 -mr-20 -mt-20 w-80 h-80 bg-indigo-600 rounded-full blur-[100px] opacity-40 transition-opacity group-hover:opacity-50"></div>
        <div className="absolute bottom-0 left-0 -ml-10 -mb-10 w-40 h-40 bg-emerald-500 rounded-full blur-[80px] opacity-10"></div>

        <div className="relative z-10">
          <div className="flex justify-between items-center mb-8">
            <div className="flex bg-white/5 backdrop-blur-xl rounded-2xl p-1 border border-white/10 shadow-inner">
               <button 
                onClick={() => setBalanceMode('real')} 
                className={`px-4 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${balanceMode === 'real' ? 'bg-indigo-500 text-white shadow-lg' : 'text-slate-400 hover:text-slate-200'}`}
               >
                 Saldo Real
               </button>
               <button 
                onClick={() => setBalanceMode('projected')} 
                className={`px-4 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${balanceMode === 'projected' ? 'bg-indigo-500 text-white shadow-lg' : 'text-slate-400 hover:text-slate-200'}`}
               >
                 Previsto
               </button>
            </div>
            <button onClick={() => setShowValues(!showValues)} className="text-slate-400 hover:text-white transition-all p-2 bg-white/5 rounded-2xl border border-white/5">
              {showValues ? <Eye size={20} /> : <EyeOff size={20} />}
            </button>
          </div>

          <div className="mb-6">
             <div className="flex items-center justify-between mb-2 ml-1">
                <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.25em] opacity-70">
                  {balanceMode === 'real' ? 'Patrimônio Consolidado' : 'Horizonte de Caixa'}
                </p>
                {balanceMode === 'projected' && (
                  <button 
                    onClick={() => setIsDateModalOpen(true)}
                    className="flex items-center space-x-1.5 bg-indigo-500/20 border border-indigo-500/30 px-2.5 py-1 rounded-lg text-[9px] font-black uppercase text-indigo-100 hover:bg-indigo-500/30 transition-all active:scale-95"
                  >
                    <CalendarRange size={12} className="text-indigo-400" />
                    <span>{new Date(projectionDate + 'T12:00:00').toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' })}</span>
                    <ChevronRight size={10} className="text-indigo-500" />
                  </button>
                )}
             </div>

             <h2 className="text-5xl font-black tracking-tighter tabular-nums leading-none flex items-baseline">
              {showValues ? (
                <>
                  <span className="text-2xl font-bold text-slate-500 mr-2">R$</span>
                  <span className="truncate">
                    {(balanceMode === 'real' ? summary.realBalance : summary.projectedBalance).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                  </span>
                </>
              ) : (
                <span className="text-4xl tracking-widest">••••••••</span>
              )}
             </h2>

             {/* Carrossel de Contas */}
             <div className="mt-8 -mx-1 overflow-x-auto no-scrollbar flex items-center space-x-3 px-1">
                {accounts.length === 0 ? (
                  <div className="py-2 px-4 bg-white/5 rounded-2xl border border-white/5 text-[9px] font-black uppercase text-slate-500">Nenhuma conta ativa</div>
                ) : (
                  accounts.map(acc => (
                    <div key={acc.id} className="flex flex-col shrink-0 bg-white/5 backdrop-blur-md border border-white/10 rounded-2xl px-4 py-2.5 min-w-[120px] transition-transform active:scale-95">
                      <div className="flex items-center space-x-2 mb-1">
                         <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: acc.color }}></div>
                         <span className="text-[8px] font-black text-slate-300 uppercase tracking-widest truncate max-w-[80px]">{acc.name}</span>
                      </div>
                      <span className="text-xs font-bold tabular-nums">
                         {showValues ? formatCurrency(getAccountBalance(acc.id)) : '••••'}
                      </span>
                    </div>
                  ))
                )}
             </div>
          </div>
        </div>
      </div>

      {/* Hub de Navegação Rápida */}
      <div className="px-1 space-y-4">
         <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-1 flex items-center">
            <Sparkles size={12} className="mr-2 text-indigo-500" /> Centro de Comando
         </h3>
         <div className="grid grid-cols-3 gap-3">
            <HubButton icon={Receipt} label="Extrato" color="indigo" onClick={() => navigate('/transactions')} />
            <HubButton icon={CalendarDays} label="Agenda" color="blue" onClick={() => navigate('/calendar')} />
            <HubButton icon={CreditCard} label="Dívidas" color="rose" onClick={() => navigate('/debts')} />
            <HubButton icon={BarChart3} label="Análise" color="purple" onClick={() => navigate('/insights')} />
            <HubButton icon={PieChart} label="Resumo" color="emerald" onClick={() => navigate('/summary')} />
            <HubButton icon={AlertCircle} label="Alertas" color="amber" onClick={() => navigate('/alerts')} />
         </div>
      </div>

      {/* Ações de Lançamento Direto (Funcionais) */}
      <div className="flex space-x-3 px-1">
         <button 
           onClick={() => openTransactionModal('expense')}
           className="flex-1 bg-slate-900 dark:bg-white text-white dark:text-black py-4 rounded-[1.8rem] font-black text-[11px] uppercase tracking-[0.2em] shadow-xl flex items-center justify-center space-x-2 active:scale-95 transition-all"
         >
            <PlusCircle size={18} />
            <span>Lançar</span>
         </button>
         <button 
           onClick={() => openTransactionModal('transfer')}
           className="flex-1 bg-white dark:bg-slate-900 text-slate-800 dark:text-white py-4 rounded-[1.8rem] border border-slate-200 dark:border-slate-800 font-black text-[11px] uppercase tracking-[0.2em] flex items-center justify-center space-x-2 active:scale-95 transition-all shadow-sm"
         >
            <ArrowUpCircle size={18} className="text-indigo-500" />
            <span>Transferir</span>
         </button>
      </div>

      {/* Últimas Atividades */}
      <div className="px-1 space-y-4">
         <div className="flex justify-between items-center px-1">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Últimas Atividades</h3>
            <Link to="/transactions" className="text-[10px] font-black text-indigo-500 uppercase flex items-center hover:text-indigo-600 transition-colors">
               Ver Tudo <ChevronRight size={14} className="ml-0.5" />
            </Link>
         </div>
         <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 overflow-hidden shadow-sm">
            {recentTransactions.length === 0 ? (
               <div className="text-center py-12 opacity-30">
                  <Clock size={32} className="mx-auto mb-3 text-slate-300" />
                  <p className="text-xs font-black uppercase text-slate-400">Sem registros recentes</p>
               </div>
            ) : (
               <div className="divide-y divide-slate-50 dark:divide-slate-800">
                  {recentTransactions.map(t => {
                     const cat = categories.find(c => c.id === t.categoryId);
                     const Icon = cat ? getIcon(cat.icon) : Clock;
                     return (
                        <div key={t.id} onClick={() => navigate('/transactions')} className="flex items-center justify-between p-5 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer group">
                           <div className="flex items-center space-x-4 min-w-0">
                              <div className="w-10 h-10 rounded-xl flex items-center justify-center bg-slate-50 dark:bg-slate-800 text-slate-400 group-hover:bg-indigo-50 dark:group-hover:bg-indigo-900/30 transition-all">
                                 <Icon size={20} style={{ color: cat?.color }} />
                              </div>
                              <div className="min-w-0">
                                 <p className="text-sm font-black text-slate-800 dark:text-white truncate group-hover:text-indigo-600 transition-colors">{t.description}</p>
                                 <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">{cat?.name || 'Geral'}</p>
                              </div>
                           </div>
                           <div className="text-right ml-4">
                              <p className={`text-sm font-black tabular-nums ${t.type === 'expense' ? 'text-slate-800 dark:text-white' : 'text-emerald-500'}`}>
                                 {t.type === 'expense' ? '-' : '+'} {formatCurrency(t.amount)}
                              </p>
                              <p className="text-[8px] font-black text-slate-300 dark:text-slate-600 uppercase mt-0.5">
                                 {new Date(t.date + 'T12:00:00').toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' })}
                              </p>
                           </div>
                        </div>
                     );
                  })}
               </div>
            )}
         </div>
      </div>

      {/* Modal de Horizonte de Caixa */}
      {isDateModalOpen && (
        <div className="fixed inset-0 bg-slate-950/70 z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4 backdrop-blur-md animate-fade-in">
           <div className="bg-white dark:bg-slate-900 w-full max-w-sm rounded-t-[3rem] sm:rounded-[3rem] p-8 shadow-2xl animate-slide-up border-t border-white/10">
              <div className="flex justify-between items-center mb-8">
                 <h2 className="text-xl font-black text-slate-800 dark:text-white tracking-tight uppercase tracking-widest">Horizonte</h2>
                 <button onClick={() => setIsDateModalOpen(false)} className="p-2.5 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-400 hover:text-rose-500 transition-colors">
                    <X size={20} />
                 </button>
              </div>

              <div className="space-y-6">
                 <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => applyPreset('endMonth')} className="p-5 bg-slate-50 dark:bg-slate-800/50 rounded-3xl border-2 border-transparent hover:border-indigo-500 transition-all text-left">
                       <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">Mês Atual</span>
                       <span className="text-sm font-bold dark:text-white">Até o Fim</span>
                    </button>
                    <button onClick={() => applyPreset('plus30')} className="p-5 bg-slate-50 dark:bg-slate-800/50 rounded-3xl border-2 border-transparent hover:border-indigo-500 transition-all text-left">
                       <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">Próximos</span>
                       <span className="text-sm font-bold dark:text-white">30 Dias</span>
                    </button>
                 </div>

                 <div className="pt-6 border-t border-slate-100 dark:border-slate-800">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 block px-1">Data Personalizada</label>
                    <button 
                      onClick={openCalendar}
                      className="w-full p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl flex items-center justify-between text-slate-800 dark:text-white font-black hover:bg-slate-100 dark:hover:bg-slate-700 transition"
                    >
                      <span>{new Date(projectionDate + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                      <CalendarRange size={20} className="text-indigo-500" />
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Calendar Modal Component */}
      <CalendarModal 
         isOpen={isCalendarOpen} 
         onClose={() => setIsCalendarOpen(false)} 
         selectedDate={projectionDate} 
         onSelect={handleDateSelect} 
         title="Horizonte de Caixa"
      />

      {/* Modal de Transação Rápida */}
      {isTransactionModalOpen && (
        <TransactionForm 
          onClose={() => setIsTransactionModalOpen(false)}
          initialType={transactionType}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useFinance } from '../context/FinanceContext';
import { DebtType } from '../types';
import { 
  X, Check, CreditCard, Building, User, 
  Calendar, DollarSign, PieChart, CheckCircle2, 
  CarFront, ChevronRight, ArrowLeft, Info,
  Calculator, Landmark, ShieldCheck, RefreshCw, AlertTriangle
} from 'lucide-react';
import { CalendarModal } from './CalendarModal';

interface Props {
  onClose: () => void;
}

export const DebtForm: React.FC<Props> = ({ onClose }) => {
  const { addDebt, categories, accounts } = useFinance();
  const [step, setStep] = useState(0);

  // Form State
  const [name, setName] = useState('');
  const [type, setType] = useState<DebtType>('card_installment');
  const [totalAmount, setTotalAmount] = useState('');
  const [categoryId, setCategoryId] = useState('');
  const [accountId, setAccountId] = useState('');

  const [downPayment, setDownPayment] = useState('');
  const [installments, setInstallments] = useState('12');
  const [firstDate, setFirstDate] = useState(new Date().toISOString().slice(0, 10));

  const [installmentValue, setInstallmentValue] = useState('');
  const [isManualInstallment, setIsManualInstallment] = useState(false);

  const [autoPayPast, setAutoPayPast] = useState(true);
  const [isRetroactive, setIsRetroactive] = useState(false);
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);

  useEffect(() => {
    if (accounts.length > 0 && !accountId) {
      setAccountId(accounts[0].id);
    }
  }, [accounts]);

  useEffect(() => {
    const today = new Date().toISOString().slice(0, 10);
    setIsRetroactive(firstDate < today);
  }, [firstDate]);

  useEffect(() => {
    if (!isManualInstallment && step === 1) {
       const total = parseFloat(totalAmount) || 0;
       const entry = parseFloat(downPayment) || 0;
       const qty = parseInt(installments) || 1;
       const calc = Math.max(0, (total - entry) / qty);
       setInstallmentValue(calc.toFixed(2));
    }
  }, [totalAmount, downPayment, installments, step, isManualInstallment]);

  const handleInstallmentChange = (val: string) => {
    setInstallmentValue(val);
    setIsManualInstallment(true);
    const instVal = parseFloat(val) || 0;
    const entry = parseFloat(downPayment) || 0;
    const qty = parseInt(installments) || 1;
    const newTotal = entry + (instVal * qty);
    setTotalAmount(newTotal.toFixed(2));
  };

  const isEntryInvalid = parseFloat(downPayment) >= parseFloat(totalAmount);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const total = parseFloat(totalAmount);
    if (!name || isNaN(total) || total <= 0 || !categoryId || !accountId || isEntryInvalid) return;

    addDebt({ name, type, totalAmount: total, startDate: firstDate, installmentCount: parseInt(installments) || 1 }, {
      downPayment: parseFloat(downPayment) || 0,
      installments: parseInt(installments) || 1,
      firstDate, categoryId, autoPayPast, accountId,
      fixedInstallmentValue: parseFloat(installmentValue)
    });
    onClose();
  };

  return (
    <>
      <div className="fixed inset-0 bg-slate-900/60 z-[120] flex items-end sm:items-center justify-center p-0 sm:p-4 backdrop-blur-md animate-fade-in">
        <div className="bg-white dark:bg-slate-950 w-full max-w-md rounded-t-[3rem] sm:rounded-[3rem] p-8 shadow-2xl animate-slide-up max-h-[95vh] overflow-y-auto no-scrollbar border-t border-white/10">

          <div className="flex justify-between items-start mb-10">
            <div className="flex-1">
               <div className="flex items-center space-x-2 mb-4">
                  <div className={`h-1.5 rounded-full transition-all duration-500 ${step === 0 ? 'bg-indigo-600 w-12' : 'bg-emerald-500 w-12'}`}></div>
                  <div className={`h-1.5 rounded-full transition-all duration-500 ${step === 1 ? 'bg-indigo-600 w-12' : 'bg-slate-100 dark:bg-slate-800 w-6'}`}></div>
               </div>
               <h2 className="text-3xl font-black text-slate-800 dark:text-white tracking-tighter">
                 {step === 0 ? 'Nova Dívida' : 'Simulação'}
               </h2>
               <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-1">
                 {step === 0 ? 'Passo 1: O que é?' : 'Passo 2: O plano de quitação'}
               </p>
            </div>
            <button onClick={onClose} className="p-2.5 bg-slate-50 dark:bg-slate-900 rounded-2xl text-slate-400 transition-colors hover:text-rose-500">
              <X size={24} />
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-8">
            {step === 0 && (
              <div className="space-y-8 animate-fade-in">
                {/* ... (Type selection & Name input same as before) ... */}
                 <div className="grid grid-cols-2 gap-4">
                  {[
                    { id: 'card_installment', label: 'Parcelado', icon: CreditCard },
                    { id: 'bank', label: 'Empréstimo', icon: Landmark },
                    { id: 'car_financing', label: 'Veículo', icon: CarFront },
                    { id: 'person', label: 'Pessoal', icon: User },
                  ].map(opt => {
                    const Icon = opt.icon;
                    const isSelected = type === opt.id;
                    return (
                      <button key={opt.id} type="button" onClick={() => setType(opt.id as DebtType)} className={`p-5 rounded-[1.8rem] border-2 flex flex-col items-center justify-center transition-all ${isSelected ? 'bg-indigo-50 dark:bg-indigo-900/20 border-indigo-500 text-indigo-600 dark:text-indigo-400 shadow-xl shadow-indigo-100 dark:shadow-none' : 'bg-slate-50 dark:bg-slate-900 border-transparent text-slate-400'}`}>
                        <Icon size={32} strokeWidth={1.5} className="mb-3" />
                        <span className="text-[11px] font-black uppercase tracking-wider">{opt.label}</span>
                      </button>
                    );
                  })}
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Título</label>
                  <input type="text" value={name} onChange={(e) => setName(e.target.value)} className="w-full px-6 py-5 bg-slate-50 dark:bg-slate-900 border-2 border-transparent focus:border-indigo-500 rounded-[1.5rem] outline-none font-bold text-xl dark:text-white transition shadow-inner" placeholder="Ex: iPhone 15..." autoFocus />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Valor Total</label>
                  <div className="relative">
                    <span className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 font-black text-2xl">R$</span>
                    <input type="number" step="0.01" value={totalAmount} onChange={(e) => { setTotalAmount(e.target.value); setIsManualInstallment(false); }} className="w-full pl-16 pr-6 py-6 bg-slate-50 dark:bg-slate-900 border-2 border-transparent focus:border-indigo-500 rounded-[1.5rem] outline-none font-black text-3xl text-slate-800 dark:text-white shadow-inner tabular-nums" placeholder="0,00" />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                   <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Categoria</label>
                      <select value={categoryId} onChange={(e) => setCategoryId(e.target.value)} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-900 border-2 border-transparent focus:border-indigo-500 rounded-2xl outline-none font-black text-xs dark:text-white appearance-none cursor-pointer">
                        <option value="">Escolher...</option>
                        {categories.filter(c => c.type === 'expense').map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                      </select>
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Conta Débito</label>
                      <select value={accountId} onChange={(e) => setAccountId(e.target.value)} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-900 border-2 border-transparent focus:border-indigo-500 rounded-2xl outline-none font-black text-xs dark:text-white appearance-none cursor-pointer">
                        {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                      </select>
                   </div>
                </div>
                <button type="button" onClick={() => setStep(1)} disabled={!name || !totalAmount || !categoryId || !accountId} className="w-full py-5 bg-indigo-600 disabled:bg-slate-200 disabled:dark:bg-slate-800 text-white font-black text-xs uppercase tracking-[0.3em] rounded-[1.8rem] shadow-2xl shadow-indigo-200 dark:shadow-none transition-all active:scale-95 flex items-center justify-center group">
