                    <span className="font-medium text-emerald-600 dark:text-emerald-400">{formatCurrency(summary.monthlyIncome)}</span>
                 </div>
                 <div className="flex justify-between text-xs">
                    <span className="text-slate-500 dark:text-slate-400 flex items-center"><Clock size={10} className="mr-1 text-amber-500"/> Pendente</span>
                    <span className="font-medium text-slate-400 dark:text-slate-500">{formatCurrency(summary.pendingIncome)}</span>
                 </div>
              </div>
           </div>

           {/* Expense Breakdown */}
