import React, { createContext, useContext, useState, useEffect, ReactNode, useCallback } from 'react';
import { Transaction, Category, BalanceSummary, AppSettings, Debt, DebtStatus, SystemAlert, Account, TransactionType, Budget, Goal, DashboardWidgetConfig } from '../types';
import { StorageService } from '../services/storageService';
import { NotificationService } from '../services/notificationService';
import { APP_THEMES, DEFAULT_CATEGORIES } from '../constants';

interface ExtendedSummary extends BalanceSummary {
  dailyBurnRate: number;
  safetyMargin: number;
  savingsRate: number;
  comparisonToLastMonth: number; // Porcentagem
}

interface FinanceContextType {
  transactions: Transaction[];
  categories: Category[];
  debts: Debt[];
  accounts: Account[];
  budgets: Budget[];
  goals: Goal[];
  settings: AppSettings;

  // Methods
  addTransaction: (t: Omit<Transaction, 'id' | 'createdAt'>) => void;
  updateTransaction: (t: Transaction) => void;
  updateTransactionSeries: (t: Transaction, updateFuture: boolean) => void;
  updateDebtTransaction: (t: Transaction, redistribute: boolean) => void;
  recalculateDebtSeries: (transactionId: string, newAmount: number) => void;
  deleteTransaction: (id: string) => void;

  addCategory: (c: Omit<Category, 'id'>) => void;
  updateCategory: (c: Category) => void;
  deleteCategory: (id: string) => void;

  addAccount: (a: Omit<Account, 'id'>) => void;
  updateAccount: (a: Account) => void;
  deleteAccount: (id: string) => void;
  reconcileBalance: (accountId: string, realBalance: number) => void;
  getAccountBalance: (accountId: string) => number;

  addDebt: (debtData: Omit<Debt, 'id'>, installmentsData: any) => void;
  updateDebt: (id: string, name: string, installmentCount: number) => void;
  deleteDebt: (id: string) => void;
  getDebtProgress: (debtId: string) => { paid: number; remaining: number; status: DebtStatus; progress: number; totalReal: number };

  saveBudget: (b: Budget) => void;
  deleteBudget: (categoryId: string) => void;
  addGoal: (g: Omit<Goal, 'id'>) => void;
  updateGoal: (g: Goal) => void;
  deleteGoal: (id: string) => void;

  getSystemAlerts: () => SystemAlert[];
  updateSettings: (s: Partial<AppSettings>) => void;
  getBalanceSummary: (month: string, projectionDate: string) => ExtendedSummary;
  refreshData: () => void;
  restoreAutoBackup: () => boolean;
  getBackupInfo: () => { timestamp: number; date: Date } | null;
  requestNotificationPermission: () => Promise<boolean>;
}

const DEFAULT_DASHBOARD_LAYOUT: DashboardWidgetConfig[] = [
  { id: 'balance', visible: true, label: 'Saldo e Resumo' },
  { id: 'shortcuts', visible: true, label: 'Atalhos Rápidos' },
  { id: 'status', visible: true, label: 'Status Mensal' },
  { id: 'recent', visible: true, label: 'Atividade Recente' },
  { id: 'debts', visible: false, label: 'Resumo de Dívidas' }
];

const FinanceContext = createContext<FinanceContextType | undefined>(undefined);

export const FinanceProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [debts, setDebts] = useState<Debt[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [budgets, setBudgets] = useState<Budget[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<AppSettings>({ 
    theme: 'light', 
    primaryColor: 'lime', 
    notificationInterval: 12,
    dashboardLayout: DEFAULT_DASHBOARD_LAYOUT
  } as AppSettings);

  useEffect(() => { refreshData(); }, []);

  useEffect(() => {
    if (settings.theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [settings.theme]);

  useEffect(() => {
    const colorKey = settings.primaryColor || 'lime';
    const palette = APP_THEMES[colorKey] || APP_THEMES['lime'];
    const root = document.documentElement;
    Object.keys(palette).forEach(shade => {
      root.style.setProperty(`--color-primary-${shade}`, palette[shade]);
    });
  }, [settings.primaryColor]);

  const refreshData = () => {
    const storedTransactions = StorageService.getTransactions();
    const storedCategories = StorageService.getCategories();
    const storedDebts = StorageService.getDebts();
    const storedAccounts = StorageService.getAccounts();
    const storedBudgets = StorageService.getBudgets();
    const storedGoals = StorageService.getGoals();
    const storedSettings = StorageService.getSettings();

    const existingNames = new Set(storedCategories.map(c => c.name.toLowerCase()));
    const missingDefaults = DEFAULT_CATEGORIES.filter(d => !existingNames.has(d.name.toLowerCase()));

    let finalCategories = storedCategories;

    if (missingDefaults.length > 0) {
      const toAdd = missingDefaults.map(cat => ({
         ...cat,
         id: storedCategories.some(sc => sc.id === cat.id) ? crypto.randomUUID() : cat.id
      }));

      finalCategories = [...storedCategories, ...toAdd];
      StorageService.saveCategories(finalCategories);
    }

    setTransactions(storedTransactions);
    setCategories(finalCategories);
    setDebts(storedDebts);
    setAccounts(storedAccounts);
    setBudgets(storedBudgets);
    setGoals(storedGoals);

    const mergedSettings = {
      ...storedSettings,
      dashboardLayout: storedSettings.dashboardLayout || DEFAULT_DASHBOARD_LAYOUT
    };
    setSettings(mergedSettings);
  };

  const saveTransactions = (ts: Transaction[]) => { setTransactions(ts); StorageService.saveTransactions(ts); };
  const saveCategories = (cs: Category[]) => { setCategories(cs); StorageService.saveCategories(cs); };
  const saveDebts = (ds: Debt[]) => { setDebts(ds); StorageService.saveDebts(ds); };
  const saveAccounts = (as: Account[]) => { setAccounts(as); StorageService.saveAccounts(as); };
  const saveBudgetsInternal = (bs: Budget[]) => { setBudgets(bs); StorageService.saveBudgets(bs); };
  const saveGoalsInternal = (gs: Goal[]) => { setGoals(gs); StorageService.saveGoals(gs); };

  const updateSettings = (newSettings: Partial<AppSettings>) => {
    const updated = { ...settings, ...newSettings };
    setSettings(updated);
    StorageService.saveSettings(updated);
  };

  const addAccount = (a: Omit<Account, 'id'>) => saveAccounts([...accounts, { ...a, id: crypto.randomUUID() }]);
  const updateAccount = (a: Account) => saveAccounts(accounts.map(acc => acc.id === a.id ? a : acc));
  const deleteAccount = (id: string) => saveAccounts(accounts.filter(a => a.id !== id));

  const getAccountBalance = (accountId: string): number => {
    const account = accounts.find(a => a.id === accountId);
    if (!account) return 0;
    let balance = Number(account.initialBalance || 0);
    transactions.forEach(t => {
      if (t.status === 'pending') return;
      if (t.accountId === accountId) {
        if (t.type === 'income') balance += Number(t.amount);
        else balance -= Number(t.amount);
      }
      if (t.type === 'transfer' && t.destinationAccountId === accountId) balance += Number(t.amount);
    });
    return parseFloat(balance.toFixed(2));
  };

  const reconcileBalance = (accountId: string, realBalance: number) => {
    const diff = realBalance - getAccountBalance(accountId);
    if (Math.abs(diff) < 0.01) return;
    const type: TransactionType = diff > 0 ? 'income' : 'expense';
    const cat = categories.find(c => c.type === type) || categories[0];
    addTransaction({ amount: Math.abs(diff), type, description: 'Ajuste de Saldo', date: new Date().toISOString().slice(0, 10), status: 'paid', accountId, categoryId: cat.id });
  };

  const addTransaction = (t: Omit<Transaction, 'id' | 'createdAt'>) => {
    const fixedGroupId = t.isFixed ? crypto.randomUUID() : undefined;
    const txs = [...transactions];
    txs.push({ ...t, id: crypto.randomUUID(), createdAt: Date.now(), fixedGroupId });
    if (t.isFixed && fixedGroupId) {
      for (let i = 1; i < 12; i++) {
        const d = new Date(t.date); d.setMonth(d.getMonth() + i);
        txs.push({ ...t, id: crypto.randomUUID(), date: d.toISOString().slice(0, 10), status: 'pending', createdAt: Date.now() + i, fixedGroupId });
      }
    }
    saveTransactions(txs);
  };

  const updateTransaction = (updatedT: Transaction) => saveTransactions(transactions.map(t => t.id === updatedT.id ? updatedT : t));

  const updateTransactionSeries = (updatedT: Transaction, updateFuture: boolean) => {
    if (!updateFuture || !updatedT.fixedGroupId) { updateTransaction(updatedT); return; }
    saveTransactions(transactions.map(t => {
      if (t.id === updatedT.id) return updatedT;
      if (t.fixedGroupId === updatedT.fixedGroupId && new Date(t.date) > new Date(updatedT.date)) {
        return { ...t, amount: updatedT.amount, categoryId: updatedT.categoryId, description: updatedT.description, type: updatedT.type, accountId: updatedT.accountId };
      }
      return t;
    }));
  };

  const updateDebtTransaction = (t: Transaction, redistribute: boolean) => {
    updateTransaction(t);
  };

  const recalculateDebtSeries = (transactionId: string, newAmount: number) => {
    const originalT = transactions.find(t => t.id === transactionId);
    if (!originalT || !originalT.debtId) return;

    const oldAmount = Number(originalT.amount);
    const difference = Number(newAmount) - oldAmount;

    if (Math.abs(difference) < 0.01) {
        updateTransaction({ ...originalT, amount: newAmount });
        return;
    }

    const futureInstallments = transactions
      .filter(t => 
        t.debtId === originalT.debtId && 
        t.status === 'pending' && 
        t.id !== transactionId && 
        new Date(t.date) > new Date(originalT.date)
      )
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    if (futureInstallments.length === 0) {
       updateTransaction({ ...originalT, amount: newAmount });
       return;
    }

    const adjustmentPerInstallment = (difference * -1) / futureInstallments.length;

    const newTransactions = transactions.map(t => {
       if (t.id === transactionId) {
          return { ...t, amount: newAmount };
       }
       if (futureInstallments.some(fi => fi.id === t.id)) {
          const adjustedAmount = Math.max(0, Number(t.amount) + adjustmentPerInstallment);
          return { ...t, amount: parseFloat(adjustedAmount.toFixed(2)) };
       }
       return t;
    });

    saveTransactions(newTransactions);
  };

  const deleteTransaction = (id: string) => saveTransactions(transactions.filter(t => t.id !== id));

  const addDebt = (debtData: Omit<Debt, 'id'>, installmentsData: any) => {
    const debtId = crypto.randomUUID();
    const newDebt = { ...debtData, id: debtId };
    const newDebts = [...debts, newDebt];

    const newTransactions = [...transactions];
    const { downPayment, installments, firstDate, categoryId, accountId, autoPayPast, fixedInstallmentValue } = installmentsData;

    const today = new Date().toISOString().slice(0, 10);
    const createdAtBase = Date.now();

    if (downPayment && Number(downPayment) > 0) {
      newTransactions.push({
        id: crypto.randomUUID(),
        debtId,
        description: `Entrada - ${debtData.name}`,
        amount: Number(downPayment),
        type: 'expense',
        status: 'paid',
        date: today,
        categoryId,
        accountId,
        createdAt: createdAtBase
      });
    }

    const remainingAmount = debtData.totalAmount - (Number(downPayment) || 0);
    let installmentValue: number;

    if (fixedInstallmentValue && fixedInstallmentValue > 0) {
        installmentValue = fixedInstallmentValue;
    } else {
        installmentValue = remainingAmount / installments;
    }

    const [y, m, d] = firstDate.split('-').map(Number);
    const baseDate = new Date(y, m - 1, d, 12, 0, 0);

    for (let i = 0; i < installments; i++) {
       const currentDate = new Date(baseDate);
       currentDate.setMonth(baseDate.getMonth() + i);
       const dateStr = currentDate.toISOString().slice(0, 10);

       let status: 'paid' | 'pending' = 'pending';
       if (autoPayPast && dateStr < today) {
          status = 'paid';
       }

       newTransactions.push({
         id: crypto.randomUUID(),
         debtId,
         description: `${debtData.name} (${i + 1}/${installments})`,
         amount: Number(installmentValue.toFixed(2)),
         type: 'expense',
         status: status,
         date: dateStr,
         categoryId,
         accountId,
         installmentNumber: i + 1,
         installmentTotal: installments,
         createdAt: createdAtBase + i + 1
       });
    }

    saveDebts(newDebts);
    saveTransactions(newTransactions);
    setDebts(newDebts);
    setTransactions(newTransactions);
  };

  const updateDebt = (id: string, name: string, installmentCount: number) => {
    saveDebts(debts.map(d => d.id === id ? { ...d, name, installmentCount } : d));
    saveTransactions(transactions.map(t => t.debtId === id ? { ...t, description: `${name} (${t.installmentNumber}/${installmentCount})`, installmentTotal: installmentCount } : t));
  };

  const deleteDebt = (id: string) => { saveDebts(debts.filter(d => d.id !== id)); saveTransactions(transactions.filter(t => t.debtId !== id)); };

  const getDebtProgress = (debtId: string) => {
    const txs = transactions.filter(t => t.debtId === debtId);
    if (txs.length === 0) return { paid: 0, remaining: 0, status: 'active' as DebtStatus, progress: 0, totalReal: 0 };

    const paidPrincipal = txs.filter(t => t.status === 'paid')
        .reduce((s, t) => s + (Number(t.amount) - (Number(t.interest) || 0)), 0);

    const debt = debts.find(d => d.id === debtId);
    const totalContract = debt ? Number(debt.totalAmount) : 0;

    const remaining = Math.max(0, totalContract - paidPrincipal);

    return { 
      paid: paidPrincipal, 
      remaining, 
      status: remaining <= 0.1 ? 'paid' : 'active' as DebtStatus, 
      progress: totalContract > 0 ? (paidPrincipal / totalContract) * 100 : 0,
      totalReal: totalContract 
    };
  };

  const addCategory = (c: Omit<Category, 'id'>) => saveCategories([...categories, { ...c, id: crypto.randomUUID() }]);
  const updateCategory = (c: Category) => saveCategories(categories.map(cat => cat.id === c.id ? cat : cat));
  const deleteCategory = (id: string) => saveCategories(categories.filter(c => c.id !== id));

  const saveBudget = (b: Budget) => {
    const idx = budgets.findIndex(item => item.categoryId === b.categoryId);
    const newBudgets = [...budgets];
    if (idx >= 0) newBudgets[idx] = b;
    else newBudgets.push(b);
    saveBudgetsInternal(newBudgets);
  };
  const deleteBudget = (categoryId: string) => saveBudgetsInternal(budgets.filter(b => b.categoryId !== categoryId));
  const addGoal = (g: Omit<Goal, 'id'>) => saveGoalsInternal([...goals, { ...g, id: crypto.randomUUID() }]);
  const updateGoal = (g: Goal) => saveGoalsInternal(goals.map(goal => goal.id === g.id ? g : goal));
  const deleteGoal = (id: string) => saveGoalsInternal(goals.filter(g => g.id !== id));

  const getBalanceSummary = (viewMonthStr: string, projectionDateStr: string): ExtendedSummary => {
    const projLimit = new Date(projectionDateStr + 'T23:59:59').getTime();
    const today = new Date();
    const dayOfMonth = today.getDate();

    let realBalance = accounts.reduce((s, acc) => s + getAccountBalance(acc.id), 0);
    let projectedBalance = realBalance;
    let monthlyIncome = 0, monthlyExpense = 0, pendingIncome = 0, pendingExpense = 0;

    transactions.forEach(t => {
      const amount = Number(t.amount) || 0;
      const isPaid = t.status === 'paid';
      const isInc = t.type === 'income';
      const isTrans = t.type === 'transfer';
      const tTime = new Date(t.date + 'T12:00:00').getTime();

      if (!isPaid && tTime <= projLimit) {
        if (isInc) projectedBalance += amount;
        else if (!isTrans) projectedBalance -= amount;
      }

      if (t.date.startsWith(viewMonthStr) && !isTrans) {
        if (isInc) { 
          monthlyIncome += isPaid ? amount : 0; 
          if (!isPaid) pendingIncome += amount; 
        } else { 
          monthlyExpense += isPaid ? amount : 0; 
          if (!isPaid) pendingExpense += amount; 
        }
      }
    });

    // Smart Metrics Calculation
    const dailyBurnRate = monthlyExpense > 0 ? monthlyExpense / dayOfMonth : 0;
    const safetyMargin = realBalance - pendingExpense;
    const savingsRate = monthlyIncome > 0 ? ((monthlyIncome - monthlyExpense) / monthlyIncome) * 100 : 0;

    return { 
      realBalance: Number(realBalance.toFixed(2)), 
      projectedBalance: Number(projectedBalance.toFixed(2)), 
      monthlyIncome, 
      monthlyExpense, 
      pendingIncome, 
      pendingExpense,
      dailyBurnRate,
      safetyMargin,
      savingsRate,
      comparisonToLastMonth: 0 // Simplificado para este MVP
    };
  };

  const getSystemAlerts = useCallback((): SystemAlert[] => {
    const alerts: SystemAlert[] = [];
    const today = new Date(); today.setHours(0,0,0,0);
    const sum = getBalanceSummary(today.toISOString().slice(0,7), today.toISOString().slice(0,10));
    transactions.forEach(t => {
      if (t.status === 'pending' && t.type === 'expense') {
        const d = new Date(t.date + 'T12:00:00'); d.setHours(0,0,0,0);
        const diff = Math.ceil((d.getTime() - today.getTime()) / 86400000);
        if (diff <= 7) {
          alerts.push({ id: t.id, title: t.description, amount: Number(t.amount), date: t.date, type: diff < 0 ? 'overdue' : diff === 0 ? 'today' : 'week', isCovered: sum.projectedBalance >= 0, transactionId: t.id });
        }
      }
    });
    return alerts;
  }, [transactions, accounts]);

  const restoreAutoBackup = () => { if (StorageService.restoreAutoBackup()) { refreshData(); return true; } return false; };
  const getBackupInfo = () => StorageService.getAutoBackupInfo();
  const requestNotificationPermission = () => NotificationService.requestPermission();

  return (
    <FinanceContext.Provider value={{
      transactions, categories, debts, accounts, budgets, goals, settings,
      addTransaction, updateTransaction, updateTransactionSeries, updateDebtTransaction, recalculateDebtSeries, deleteTransaction,
      addCategory, updateCategory, deleteCategory,
      addAccount, updateAccount, deleteAccount, reconcileBalance, getAccountBalance,
      addDebt, updateDebt, deleteDebt, getDebtProgress,
      saveBudget, deleteBudget, addGoal, updateGoal, deleteGoal,
      getSystemAlerts, updateSettings, getBalanceSummary, refreshData,
      restoreAutoBackup, getBackupInfo, requestNotificationPermission
    }}>
      {children}
    </FinanceContext.Provider>
  );
};

export const useFinance = () => {
  const context = useContext(FinanceContext);
  if (!context) throw new Error("useFinance must be used within FinanceProvider");
  return context;
};

import React, { useState, useEffect, useMemo } from 'react';
import { useFinance } from '../context/FinanceContext';
import { Transaction, TransactionType, TransactionStatus } from '../types';
import { X, Check, Trash2, Bell, BellRing, Repeat, Copy, Layers, Sparkles, Loader2, TrendingUp, ArrowRightLeft, Calculator, AlertTriangle, RefreshCw, Lock, AlertCircle, Calendar as CalendarIcon } from 'lucide-react';
import { getIcon } from '../constants';
import { GeminiService } from '../services/geminiService';
import { CalendarModal } from './CalendarModal';

interface Props {
  onClose: () => void;
  initialType?: TransactionType;
  transaction?: Transaction | null;
}

export const TransactionForm: React.FC<Props> = ({ onClose, initialType = 'expense', transaction }) => {
  const { addTransaction, updateTransactionSeries, updateDebtTransaction, deleteTransaction, categories, transactions, accounts } = useFinance();

  const [type, setType] = useState<TransactionType>(initialType);
  const [amount, setAmount] = useState('');
  const [description, setDescription] = useState('');
  const [categoryId, setCategoryId] = useState('');
  const [accountId, setAccountId] = useState('');
  const [destinationAccountId, setDestinationAccountId] = useState('');
  const [date, setDate] = useState(new Date().toISOString().slice(0, 10));
  const [status, setStatus] = useState<TransactionStatus>('paid');
  const [hasReminder, setHasReminder] = useState(false);
  const [reminderDate, setReminderDate] = useState('');
  const [isFixed, setIsFixed] = useState(false);
  const [showRecurringEditModal, setShowRecurringEditModal] = useState(false);
  const [isPredicting, setIsPredicting] = useState(false);
  const [baseAmount, setBaseAmount] = useState<number>(0);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // Calendar Modal State
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);

  useEffect(() => {
    if (!accountId && accounts.length > 0) {
      setAccountId(accounts[0].id);
    }
  }, [accounts]);

  useEffect(() => {
    if (transaction) {
      setType(transaction.type);
      setAmount(transaction.amount.toString());
      if (transaction.debtId) {
          const originalBase = transaction.amount - (transaction.interest || 0);
          setBaseAmount(originalBase);
      }
      setDescription(transaction.description);
      setCategoryId(transaction.categoryId);
      setAccountId(transaction.accountId || accounts[0]?.id);
      setDestinationAccountId(transaction.destinationAccountId || '');
      setDate(transaction.date);
      setStatus(transaction.status);
      if (transaction.reminderDate) {
        setHasReminder(true);
        setReminderDate(transaction.reminderDate);
      }
      if (transaction.isFixed) {
        setIsFixed(true);
      }
    }
  }, [transaction]);

  // Hook to check for future dates on NEW transactions
  const handleDateSelect = (newDate: string) => {
    setDate(newDate);
    // Only auto-change status if creating a new transaction
    if (!transaction) {
      const selected = new Date(newDate + 'T12:00:00');
      const today = new Date();
      today.setHours(0, 0, 0, 0); // Normalize today to midnight

      if (selected > today) {
        setStatus('pending');
      } else {
        // Optional: revert to paid if date is today or past, 
        // but often users might want to log past pending items, so let's stick to future=pending logic mostly.
        // For better UX, let's default to paid if <= today
        setStatus('paid');
      }
    }
  };

  const diffAmount = useMemo(() => {
    if (!transaction?.debtId) return 0;
    const currentVal = parseFloat(amount);
    if (isNaN(currentVal)) return 0;
    return currentVal - baseAmount;
  }, [amount, baseAmount, transaction]);

  const isAmountInvalid = transaction?.debtId && diffAmount < -0.01;

  const handleSmartFill = async () => {
    if (!description || description.length < 3) return;
    setIsPredicting(true);
    const prediction = await GeminiService.predictTransaction(description, transactions, categories);
    setIsPredicting(false);
    if (prediction) {
      if (prediction.categoryId) setCategoryId(prediction.categoryId);
      if (prediction.type) setType(prediction.type as TransactionType);
      if (prediction.amount && prediction.amount > 0) setAmount(prediction.amount.toString());
    }
  };

  const handleReminderToggle = () => {
    setHasReminder(!hasReminder);
    if (!hasReminder && !reminderDate) {
       const now = new Date();
       now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
       setReminderDate(now.toISOString().slice(0, 16));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const val = parseFloat(amount);

    if (!val || val <= 0 || !description || !accountId) {
        alert("Preencha todos os campos obrigatórios.");
        return;
    }

    if (isAmountInvalid) {
        alert("Valor inválido para dívida.");
        return;
    }

    if (type !== 'transfer' && !categoryId) {
       alert("Selecione uma categoria.");
       return;
    }

    if (type === 'transfer') {
       if (!destinationAccountId) {
         alert("Selecione a conta de destino.");
         return;
       }
       if (accountId === destinationAccountId) {
         alert("Contas iguais.");
         return;
       }
    }

    const data: any = {
      type, amount: val, description, categoryId: type === 'transfer' ? '' : categoryId,
      accountId, destinationAccountId: type === 'transfer' ? destinationAccountId : undefined,
      date, status,
      reminderDate: (status === 'pending' && hasReminder) ? reminderDate : undefined,
      reminderSent: (status === 'pending' && hasReminder && transaction?.reminderDate === reminderDate) ? transaction.reminderSent : false,
      isFixed,
      interest: (transaction?.debtId && diffAmount > 0.01) ? diffAmount : 0
    };

    if (transaction) {
      if (transaction.debtId) {
         updateDebtTransaction({ ...transaction, ...data }, false);
         onClose();
      } else if (transaction.fixedGroupId) {
         setShowRecurringEditModal(true);
      } else {
         updateTransactionSeries({ ...transaction, ...data }, false);
         onClose();
      }
    } else {
      addTransaction(data);
      onClose();
    }
  };

  const handleConfirmRecurringUpdate = (updateFuture: boolean) => {
    if (!transaction) return;
    const val = parseFloat(amount);
    const data: any = {
      type, amount: val, description, categoryId: type === 'transfer' ? '' : categoryId,
      accountId, destinationAccountId: type === 'transfer' ? destinationAccountId : undefined,
      date, status,
      reminderDate: (status === 'pending' && hasReminder) ? reminderDate : undefined,
      reminderSent: (status === 'pending' && hasReminder && transaction?.reminderDate === reminderDate) ? transaction.reminderSent : false,
      isFixed
    };
    updateTransactionSeries({ ...transaction, ...data }, updateFuture);
    onClose();
  };

  const handleDelete = () => { if (transaction) setShowDeleteConfirm(true); };
  const confirmDelete = () => { if (transaction) { deleteTransaction(transaction.id); onClose(); } };
  const filteredCategories = categories.filter(c => c.type === type);

  return (
    <>
      <div className="fixed inset-0 bg-black/50 z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4 backdrop-blur-sm animate-fade-in">
        <div className="bg-white dark:bg-slate-900 w-full max-w-md rounded-t-[2rem] sm:rounded-2xl p-6 shadow-xl animate-slide-up max-h-[90dvh] overflow-y-auto no-scrollbar border border-slate-100 dark:border-slate-800 flex flex-col relative">
          <div className="flex justify-between items-center mb-6 shrink-0">
            <h2 className="text-xl font-bold text-slate-800 dark:text-white">
              {transaction ? 'Editar Lançamento' : 'Novo Lançamento'}
            </h2>
            <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition">
              <X size={20} className="text-slate-500 dark:text-slate-400" />
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4 pb-[env(safe-area-inset-bottom)] sm:pb-0">
            {!transaction?.debtId && (
                <div className="flex p-1 bg-slate-100 dark:bg-slate-800 rounded-lg">
                <button type="button" className={`flex-1 py-2 text-sm font-medium rounded-md transition ${type === 'expense' ? 'bg-white dark:bg-slate-700 text-rose-600 dark:text-rose-400 shadow-sm' : 'text-slate-500 dark:text-slate-400'}`} onClick={() => { setType('expense'); setCategoryId(''); }}>Despesa</button>
                <button type="button" className={`flex-1 py-2 text-sm font-medium rounded-md transition ${type === 'income' ? 'bg-white dark:bg-slate-700 text-emerald-600 dark:text-emerald-400 shadow-sm' : 'text-slate-500 dark:text-slate-400'}`} onClick={() => { setType('income'); setCategoryId(''); }}>Receita</button>
                <button type="button" className={`flex-1 py-2 text-sm font-medium rounded-md transition ${type === 'transfer' ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm' : 'text-slate-500 dark:text-slate-400'}`} onClick={() => { setType('transfer'); setCategoryId(''); setDescription('Transferência'); }}>Transf.</button>
                </div>
            )}

            {type !== 'transfer' && (
              <div>
                <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Descrição</label>
                <div className="relative">
                  <input type="text" value={description} onChange={(e) => setDescription(e.target.value)} className="w-full pl-4 pr-12 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none dark:text-white" placeholder="Ex: Uber, Netflix..." required />
                  {!transaction && (
                    <button type="button" onClick={handleSmartFill} disabled={isPredicting} className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-indigo-100 dark:bg-indigo-900/50 text-indigo-600 dark:text-indigo-400 rounded-lg hover:bg-indigo-200 transition-colors disabled:opacity-50">
                      {isPredicting ? <Loader2 size={18} className="animate-spin" /> : <Sparkles size={18} />}
                    </button>
                  )}
                </div>
              </div>
            )}

            <div>
              <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Valor</label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-medium">R$</span>
                <input type="number" step="0.01" min={transaction?.debtId ? baseAmount : 0.01} value={amount} onChange={(e) => setAmount(e.target.value)} className={`w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border rounded-xl focus:ring-2 outline-none text-lg font-bold transition-colors ${isAmountInvalid ? 'border-rose-500 text-rose-500 focus:ring-rose-200' : 'border-slate-200 dark:border-slate-700 focus:ring-indigo-500 text-slate-800 dark:text-white'}`} placeholder="0,00" required />
              </div>
              {transaction?.debtId && diffAmount > 0.01 && (
                 <div className="mt-2 p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-100 dark:border-amber-900/50 rounded-xl flex items-center space-x-2 animate-fade-in"><TrendingUp size={16} className="text-amber-500 shrink-0" /><span className="text-xs font-bold text-amber-700 dark:text-amber-400">Excedente de R$ {diffAmount.toFixed(2)} identificado como Juros.</span></div>
              )}
            </div>

            {type === 'transfer' ? (
               <div className="bg-slate-50 dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700 flex flex-col space-y-4 relative">
                  <div>
                    <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">De (Origem)</label>
                    <select value={accountId} onChange={(e) => setAccountId(e.target.value)} className="w-full p-2 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg text-sm dark:text-white">
                      {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                    </select>
                  </div>
                  <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white dark:bg-slate-600 rounded-full p-1 border border-slate-200 dark:border-slate-500 shadow-sm z-10"><ArrowRightLeft size={16} className="text-slate-400 dark:text-slate-200" /></div>
                  <div>
                    <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Para (Destino)</label>
                    <select value={destinationAccountId} onChange={(e) => setDestinationAccountId(e.target.value)} className="w-full p-2 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg text-sm dark:text-white">
                      <option value="">Selecione...</option>
                      {accounts.filter(a => a.id !== accountId).map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                    </select>
                  </div>
               </div>
            ) : (
               <div>
                  <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Conta / Carteira</label>
                  <select value={accountId} onChange={(e) => setAccountId(e.target.value)} className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm dark:text-white">
                    {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                  </select>
               </div>
            )}

            <div className="grid grid-cols-2 gap-4">
              {/* Date Input with Calendar Modal */}
              <div>
                <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Data</label>
                <div 
                  onClick={() => setIsCalendarOpen(true)}
                  className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl flex items-center justify-between cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700/50 transition-colors"
                >
                   <span className="text-sm dark:text-white font-medium">{new Date(date + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                   <CalendarIcon size={18} className="text-slate-400" />
                </div>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Status</label>
                <select value={status} onChange={(e) => setStatus(e.target.value as TransactionStatus)} className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none text-sm dark:text-white">
                  <option value="paid">{type === 'expense' ? 'Pago' : type === 'transfer' ? 'Realizado' : 'Recebido'}</option>
                  <option value="pending">Pendente</option>
                </select>
              </div>
            </div>

            {!transaction && !transaction?.debtId && type !== 'transfer' && (
              <div className="bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 p-4 rounded-xl flex items-center justify-between">
                 <div className="flex items-center space-x-2">
                    <Repeat className="text-slate-500 dark:text-slate-400" size={18} />
                    <span className="text-sm font-semibold text-slate-700 dark:text-slate-200">Transação Fixa (Mensal)</span>
                 </div>
                 <button type="button" onClick={() => setIsFixed(!isFixed)} className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${isFixed ? 'bg-indigo-600' : 'bg-slate-300 dark:bg-slate-600'}`}>
                   <span className={`inline-block h-3 w-3 transform rounded-full bg-white transition-transform ${isFixed ? 'translate-x-5' : 'translate-x-1'}`} />
                 </button>
              </div>
            )}

            {status === 'pending' && (
              <div className="bg-indigo-50 dark:bg-indigo-900/20 p-4 rounded-xl border border-indigo-100 dark:border-indigo-900/50 transition-all">
                <div className="flex justify-between items-center mb-2">
                  <div className="flex items-center space-x-2 text-indigo-700 dark:text-indigo-300 font-semibold text-sm">
                    {hasReminder ? <BellRing size={16} /> : <Bell size={16} />}
                    <span>Definir Lembrete</span>
                  </div>
                  <button type="button" onClick={handleReminderToggle} className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${hasReminder ? 'bg-indigo-600' : 'bg-slate-300 dark:bg-slate-700'}`}>
                    <span className={`inline-block h-3 w-3 transform rounded-full bg-white transition-transform ${hasReminder ? 'translate-x-5' : 'translate-x-1'}`} />
                  </button>
                </div>
                {hasReminder && (
                   <input type="datetime-local" value={reminderDate} onChange={(e) => setReminderDate(e.target.value)} className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-indigo-200 dark:border-indigo-800 rounded-lg text-sm text-slate-700 dark:text-slate-200 outline-none" />
                )}
              </div>
            )}

            {type !== 'transfer' && (
              <div>
                <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-2">Categoria</label>
                <div className="grid grid-cols-3 sm:grid-cols-4 gap-2 max-h-52 overflow-y-auto no-scrollbar p-1">
                    {filteredCategories.map(cat => {
                      const Icon = getIcon(cat.icon);
                      const isSelected = categoryId === cat.id;
                      return (
                        <button key={cat.id} type="button" onClick={() => setCategoryId(cat.id)} className={`flex flex-col items-center justify-center p-2 rounded-xl border transition min-h-[80px] h-full ${isSelected ? `bg-indigo-50 dark:bg-indigo-900/30 border-indigo-500 text-indigo-700 dark:text-indigo-400 shadow-sm` : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'}`}>
                          <Icon size={20} className="mb-1.5 shrink-0" />
                          <span className="text-[10px] leading-tight text-center break-words w-full line-clamp-2">{cat.name}</span>
                        </button>
                      );
                    })}
                </div>
              </div>
            )}

            <div className="flex space-x-3 pt-4 pb-4 sm:pb-0">
              {transaction && (
                <button type="button" onClick={handleDelete} className="flex-none w-14 flex items-center justify-center bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-xl hover:bg-red-100 dark:hover:bg-red-900/40 transition">
                  <Trash2 size={20} />
                </button>
              )}
              <button type="submit" disabled={isAmountInvalid} className="flex-1 py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg hover:shadow-xl transition-all flex items-center justify-center space-x-2 disabled:opacity-50 disabled:cursor-not-allowed">
                <Check size={20} />
                <span>{transaction ? 'Salvar Alterações' : 'Salvar Transação'}</span>
              </button>
            </div>
          </form>

          {showDeleteConfirm && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm rounded-t-[2rem] sm:rounded-2xl">
                <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-2xl w-3/4 text-center border border-slate-100 dark:border-slate-800 animate-scale-in">
                    <div className="w-12 h-12 bg-rose-100 dark:bg-rose-900/30 text-rose-600 dark:text-rose-400 rounded-full flex items-center justify-center mx-auto mb-4"><Trash2 size={24} /></div>
                    <h3 className="text-lg font-black text-slate-800 dark:text-white mb-2">Excluir?</h3>
                    <p className="text-xs text-slate-500 dark:text-slate-400 mb-6 font-medium">Esta ação é irreversível.</p>
                    <div className="flex space-x-3">
                        <button onClick={() => setShowDeleteConfirm(false)} className="flex-1 py-3 text-slate-500 font-bold bg-slate-100 dark:bg-slate-800 rounded-xl text-xs uppercase tracking-wider">Cancelar</button>
                        <button onClick={confirmDelete} className="flex-1 py-3 text-white font-bold bg-rose-500 rounded-xl shadow-lg shadow-rose-200 dark:shadow-none text-xs uppercase tracking-wider">Excluir</button>
                    </div>
                </div>
            </div>
          )}
        </div>
      </div>

      <CalendarModal 
         isOpen={isCalendarOpen} 
         onClose={() => setIsCalendarOpen(false)} 
         selectedDate={date} 
         onSelect={handleDateSelect} 
      />

      {showRecurringEditModal && (
        <div className="fixed inset-0 bg-black/60 z-[120] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
           <div className="bg-white dark:bg-slate-900 rounded-2xl p-6 w-full max-w-sm shadow-2xl border border-slate-200 dark:border-slate-800 animate-scale-in">
              <div className="flex justify-center mb-4 text-indigo-600 dark:text-indigo-400"><Layers size={48} /></div>
              <h3 className="text-lg font-bold text-center text-slate-800 dark:text-white mb-2">Editar Transação Fixa</h3>
              <p className="text-center text-sm text-slate-500 dark:text-slate-400 mb-6">Você está editando uma transação recorrente. Como deseja aplicar as alterações?</p>
              <div className="space-y-3">
                 <button onClick={() => handleConfirmRecurringUpdate(false)} className="w-full py-3 px-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700 rounded-xl flex items-center transition"><div className="bg-slate-100 dark:bg-slate-700 p-2 rounded-lg mr-3"><Copy size={20} className="text-slate-500 dark:text-slate-300"/></div><div className="text-left"><span className="block text-sm font-bold text-slate-700 dark:text-slate-200">Apenas esta</span><span className="block text-[10px] text-slate-400">Alterar somente o lançamento atual</span></div></button>
                 <button onClick={() => handleConfirmRecurringUpdate(true)} className="w-full py-3 px-4 bg-indigo-50 dark:bg-indigo-900/20 border border-indigo-100 dark:border-indigo-800/50 hover:bg-indigo-100 dark:hover:bg-indigo-900/30 rounded-xl flex items-center transition"><div className="bg-indigo-100 dark:bg-indigo-800 p-2 rounded-lg mr-3"><Layers size={20} className="text-indigo-600 dark:text-indigo-300"/></div><div className="text-left"><span className="block text-sm font-bold text-indigo-700 dark:text-indigo-300">Esta e futuras</span><span className="block text-[10px] text-indigo-400/80">Aplicar em todos os lançamentos seguintes</span></div></button>
                 <button onClick={() => setShowRecurringEditModal(false)} className="w-full py-3 text-sm font-bold text-slate-400 hover:text-slate-600 dark:hover:text-slate-300">Cancelar</button>
              </div>
           </div>
        </div>
      )}
    </>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { useFinance } from '../context/FinanceContext';
import { Transaction, TransactionType, TransactionStatus } from '../types';
import { 
  X, Check, Trash2, Bell, BellRing, Repeat, Copy, Layers, 
  Sparkles, Loader2, TrendingUp, ArrowRightLeft, Calculator, 
  AlertTriangle, RefreshCw, Lock, AlertCircle, Calendar as CalendarIcon,
  ChevronDown, Wallet
} from 'lucide-react';
import { getIcon } from '../constants';
import { GeminiService } from '../services/geminiService';
import { CalendarModal } from './CalendarModal';

interface Props {
  onClose: () => void;
  initialType?: TransactionType;
  transaction?: Transaction | null;
}

export const TransactionForm: React.FC<Props> = ({ onClose, initialType = 'expense', transaction }) => {
  const { addTransaction, updateTransactionSeries, updateDebtTransaction, deleteTransaction, categories, transactions, accounts } = useFinance();

  const [type, setType] = useState<TransactionType>(initialType);
  const [amount, setAmount] = useState('');
  const [description, setDescription] = useState('');
  const [categoryId, setCategoryId] = useState('');
  const [accountId, setAccountId] = useState('');
  const [destinationAccountId, setDestinationAccountId] = useState('');
  const [date, setDate] = useState(new Date().toISOString().slice(0, 10));
  const [status, setStatus] = useState<TransactionStatus>('paid');
  const [hasReminder, setHasReminder] = useState(false);
  const [reminderDate, setReminderDate] = useState('');
  const [isFixed, setIsFixed] = useState(false);
  const [showRecurringEditModal, setShowRecurringEditModal] = useState(false);
  const [isPredicting, setIsPredicting] = useState(false);
  const [baseAmount, setBaseAmount] = useState<number>(0);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // Calendar Modal State
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);

  useEffect(() => {
    if (!accountId && accounts.length > 0) {
      setAccountId(accounts[0].id);
    }
  }, [accounts]);

  useEffect(() => {
    if (transaction) {
      setType(transaction.type);
      setAmount(transaction.amount.toString());
      if (transaction.debtId) {
          const originalBase = transaction.amount - (transaction.interest || 0);
          setBaseAmount(originalBase);
      }
      setDescription(transaction.description);
      setCategoryId(transaction.categoryId);
      setAccountId(transaction.accountId || accounts[0]?.id);
      setDestinationAccountId(transaction.destinationAccountId || '');
      setDate(transaction.date);
      setStatus(transaction.status);
      if (transaction.reminderDate) {
        setHasReminder(true);
        setReminderDate(transaction.reminderDate);
      }
      if (transaction.isFixed) {
        setIsFixed(true);
      }
    }
  }, [transaction]);

  // Hook to check for future dates on NEW transactions
  const handleDateSelect = (newDate: string) => {
    setDate(newDate);
    // Only auto-change status if creating a new transaction
    if (!transaction) {
      const selected = new Date(newDate + 'T12:00:00');
      const today = new Date();
      today.setHours(0, 0, 0, 0); // Normalize today to midnight

      if (selected > today) {
        setStatus('pending');
      } else {
        setStatus('paid');
      }
    }
  };

  const diffAmount = useMemo(() => {
    if (!transaction?.debtId) return 0;
    const currentVal = parseFloat(amount);
    if (isNaN(currentVal)) return 0;
    return currentVal - baseAmount;
  }, [amount, baseAmount, transaction]);

  const isAmountInvalid = transaction?.debtId && diffAmount < -0.01;

  const handleSmartFill = async () => {
    if (!description || description.length < 3) return;
    setIsPredicting(true);
    const prediction = await GeminiService.predictTransaction(description, transactions, categories);
    setIsPredicting(false);
    if (prediction) {
      if (prediction.categoryId) setCategoryId(prediction.categoryId);
      if (prediction.type) setType(prediction.type as TransactionType);
      if (prediction.amount && prediction.amount > 0) setAmount(prediction.amount.toString());
    }
  };

  const handleReminderToggle = () => {
    setHasReminder(!hasReminder);
    if (!hasReminder && !reminderDate) {
       const now = new Date();
       now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
       setReminderDate(now.toISOString().slice(0, 16));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const val = parseFloat(amount);

    if (!val || val <= 0 || !description || !accountId) {
        alert("Preencha todos os campos obrigatórios.");
        return;
    }

    if (isAmountInvalid) {
        alert("Valor inválido para dívida.");
        return;
    }

    if (type !== 'transfer' && !categoryId) {
       alert("Selecione uma categoria.");
       return;
    }

    if (type === 'transfer') {
       if (!destinationAccountId) {
         alert("Selecione a conta de destino.");
         return;
       }
       if (accountId === destinationAccountId) {
         alert("Contas iguais.");
         return;
       }
    }

    const data: any = {
      type, amount: val, description, categoryId: type === 'transfer' ? '' : categoryId,
      accountId, destinationAccountId: type === 'transfer' ? destinationAccountId : undefined,
      date, status,
      reminderDate: (status === 'pending' && hasReminder) ? reminderDate : undefined,
      reminderSent: (status === 'pending' && hasReminder && transaction?.reminderDate === reminderDate) ? transaction.reminderSent : false,
      isFixed,
      interest: (transaction?.debtId && diffAmount > 0.01) ? diffAmount : 0
    };

    if (transaction) {
      if (transaction.debtId) {
         updateDebtTransaction({ ...transaction, ...data }, false);
         onClose();
      } else if (transaction.fixedGroupId) {
         setShowRecurringEditModal(true);
      } else {
         updateTransactionSeries({ ...transaction, ...data }, false);
         onClose();
      }
    } else {
      addTransaction(data);
      onClose();
    }
  };

  const handleConfirmRecurringUpdate = (updateFuture: boolean) => {
    if (!transaction) return;
    const val = parseFloat(amount);
    const data: any = {
      type, amount: val, description, categoryId: type === 'transfer' ? '' : categoryId,
      accountId, destinationAccountId: type === 'transfer' ? destinationAccountId : undefined,
      date, status,
      reminderDate: (status === 'pending' && hasReminder) ? reminderDate : undefined,
      reminderSent: (status === 'pending' && hasReminder && transaction?.reminderDate === reminderDate) ? transaction.reminderSent : false,
      isFixed
    };
    updateTransactionSeries({ ...transaction, ...data }, updateFuture);
    onClose();
  };

  const handleDelete = () => { if (transaction) setShowDeleteConfirm(true); };
  const confirmDelete = () => { if (transaction) { deleteTransaction(transaction.id); onClose(); } };
  const filteredCategories = categories.filter(c => c.type === type);

  // Styles based on Type
  const themeColor = type === 'expense' ? 'rose' : type === 'income' ? 'emerald' : 'blue';
  const ThemeIcon = type === 'expense' ? TrendingUp : type === 'income' ? TrendingUp : ArrowRightLeft;

  return (
    <>
      <div className="fixed inset-0 bg-slate-950/80 z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4 backdrop-blur-sm animate-fade-in">
        <div className="bg-white dark:bg-slate-900 w-full max-w-md h-[95dvh] sm:h-auto sm:max-h-[90dvh] rounded-t-[2.5rem] sm:rounded-[3rem] shadow-2xl animate-slide-up flex flex-col relative overflow-hidden">

          {/* --- Header / Type Selector --- */}
          <div className="px-6 pt-6 pb-2 flex justify-between items-center z-20">
             <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-full">
                <button onClick={() => { setType('expense'); setCategoryId(''); }} className={`px-4 py-2 rounded-full text-xs font-black uppercase transition-all ${type === 'expense' ? 'bg-white dark:bg-slate-700 text-rose-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>Despesa</button>
                <button onClick={() => { setType('income'); setCategoryId(''); }} className={`px-4 py-2 rounded-full text-xs font-black uppercase transition-all ${type === 'income' ? 'bg-white dark:bg-slate-700 text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>Receita</button>
                <button onClick={() => { setType('transfer'); setCategoryId(''); setDescription('Transferência'); }} className={`px-4 py-2 rounded-full text-xs font-black uppercase transition-all ${type === 'transfer' ? 'bg-white dark:bg-slate-700 text-blue-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>Transf.</button>
             </div>
             <button onClick={onClose} className="p-2.5 bg-slate-100 dark:bg-slate-800 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700 transition">
               <X size={20} className="text-slate-500" />
             </button>
          </div>

          <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto no-scrollbar pb-32">

            {/* --- Hero Amount Input --- */}
            <div className="flex flex-col items-center justify-center py-8 relative">
               <span className={`text-[10px] font-black uppercase tracking-[0.2em] mb-2 ${isAmountInvalid ? 'text-rose-500' : 'text-slate-400'}`}>Valor da Transação</span>
               <div className="flex items-baseline justify-center relative w-full px-8">
                  <span className={`text-3xl font-black mr-2 ${amount ? (type === 'expense' ? 'text-rose-600' : type === 'income' ? 'text-emerald-600' : 'text-blue-600') : 'text-slate-300'}`}>R$</span>
                  <input 
                    type="number" 
                    step="0.01" 
                    min={transaction?.debtId ? baseAmount : 0.01} 
                    value={amount} 
                    onChange={(e) => setAmount(e.target.value)} 
                    className={`w-full bg-transparent text-center text-6xl font-black outline-none placeholder:text-slate-200 dark:placeholder:text-slate-800 transition-colors ${type === 'expense' ? 'text-rose-600 caret-rose-600' : type === 'income' ? 'text-emerald-600 caret-emerald-600' : 'text-blue-600 caret-blue-600'}`}
                    placeholder="0" 
                    required 
                    autoFocus={!transaction}
                  />
               </div>
               {transaction?.debtId && diffAmount > 0.01 && (
                 <div className="mt-2 text-[10px] font-bold text-amber-500 flex items-center bg-amber-50 dark:bg-amber-900/20 px-2 py-1 rounded-lg">
                    <TrendingUp size={12} className="mr-1" /> + R$ {diffAmount.toFixed(2)} (Juros)
                 </div>
               )}
            </div>

            {/* --- Main Inputs Container --- */}
            <div className="px-6 space-y-6">

               {/* Description with AI */}
               {type !== 'transfer' && (
                 <div className="relative">
                    <input 
                      type="text" 
                      value={description} 
                      onChange={(e) => setDescription(e.target.value)} 
                      className="w-full bg-slate-50 dark:bg-slate-800/50 border-b-2 border-slate-200 dark:border-slate-800 focus:border-indigo-500 dark:focus:border-indigo-500 px-4 py-4 text-lg font-bold text-slate-800 dark:text-white outline-none placeholder:text-slate-400 dark:placeholder:text-slate-600 rounded-t-2xl transition-all"
                      placeholder="Descrição (ex: Almoço)"
                      required 
                    />
                    {!transaction && (
                      <button 
                        type="button" 
                        onClick={handleSmartFill} 
                        disabled={isPredicting || !description} 
                        className="absolute right-3 top-1/2 -translate-y-1/2 p-2 text-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-xl transition disabled:opacity-30"
                      >
                        {isPredicting ? <Loader2 size={20} className="animate-spin" /> : <Sparkles size={20} />}
                      </button>
                    )}
                 </div>
               )}

               {/* Grid for Date, Status, Account */}
               <div className="grid grid-cols-2 gap-3">
                  <div 
                    onClick={() => setIsCalendarOpen(true)}
                    className="bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl flex flex-col justify-center cursor-pointer border border-transparent hover:border-indigo-200 transition-all active:scale-95"
                  >
                     <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 flex items-center">
                        <CalendarIcon size={10} className="mr-1"/> Data
                     </span>
                     <span className="text-sm font-black text-slate-800 dark:text-white truncate">
                        {new Date(date + 'T12:00:00').toLocaleDateString('pt-BR', {day: '2-digit', month: 'short', year: 'numeric'})}
                     </span>
                  </div>

                  <div className="bg-slate-50 dark:bg-slate-800 p-2 rounded-2xl flex items-center relative">
                     <select 
                       value={status} 
                       onChange={(e) => setStatus(e.target.value as TransactionStatus)} 
                       className="w-full h-full bg-transparent outline-none font-black text-sm text-slate-800 dark:text-white appearance-none px-3 z-10 cursor-pointer"
                     >
                        <option value="paid">{type === 'expense' ? 'Pago' : type === 'transfer' ? 'Realizado' : 'Recebido'}</option>
                        <option value="pending">Pendente</option>
                     </select>
                     <ChevronDown size={16} className="absolute right-4 text-slate-400 pointer-events-none" />
                     <span className="absolute top-2 left-5 text-[10px] font-black text-slate-400 uppercase tracking-widest pointer-events-none">Status</span>
                  </div>

                  <div className={`col-span-2 bg-slate-50 dark:bg-slate-800 p-2 rounded-2xl flex items-center relative ${type === 'transfer' ? 'border-2 border-indigo-100 dark:border-indigo-900/30' : ''}`}>
                     <select 
                       value={accountId} 
                       onChange={(e) => setAccountId(e.target.value)} 
                       className="w-full h-full bg-transparent outline-none font-black text-sm text-slate-800 dark:text-white appearance-none pl-10 pr-4 py-4 cursor-pointer"
                     >
                        {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                     </select>
                     <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none">
                        <Wallet size={18} />
                     </div>
                     <ChevronDown size={16} className="absolute right-4 text-slate-400 pointer-events-none" />
                     <span className="absolute top-1 left-10 text-[9px] font-black text-slate-400 uppercase tracking-widest pointer-events-none">
                        {type === 'transfer' ? 'De (Origem)' : 'Conta / Carteira'}
                     </span>
                  </div>

                  {type === 'transfer' && (
                    <div className="col-span-2 bg-slate-50 dark:bg-slate-800 p-2 rounded-2xl flex items-center relative border-2 border-indigo-100 dark:border-indigo-900/30">
                       <select 
                         value={destinationAccountId} 
                         onChange={(e) => setDestinationAccountId(e.target.value)} 
                         className="w-full h-full bg-transparent outline-none font-black text-sm text-slate-800 dark:text-white appearance-none pl-10 pr-4 py-4 cursor-pointer"
                       >
                          <option value="">Selecione...</option>
                          {accounts.filter(a => a.id !== accountId).map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                       </select>
                       <div className="absolute left-4 top-1/2 -translate-y-1/2 text-indigo-500 pointer-events-none">
                          <ArrowRightLeft size={18} />
                       </div>
                       <ChevronDown size={16} className="absolute right-4 text-slate-400 pointer-events-none" />
                       <span className="absolute top-1 left-10 text-[9px] font-black text-indigo-500 uppercase tracking-widest pointer-events-none">Para (Destino)</span>
                    </div>
                  )}
               </div>

               {/* Recurring & Reminder Toggles */}
               {!transaction && !transaction?.debtId && type !== 'transfer' && (
                  <div className="flex space-x-3">
                     <button 
                       type="button"
                       onClick={() => setIsFixed(!isFixed)}
                       className={`flex-1 py-3 rounded-2xl border-2 flex flex-col items-center justify-center transition-all ${isFixed ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400' : 'border-slate-100 dark:border-slate-800 text-slate-400'}`}
                     >
                        <Repeat size={20} className="mb-1" />
                        <span className="text-[9px] font-black uppercase">Fixa Mensal</span>
                     </button>

                     <button 
                       type="button"
                       onClick={handleReminderToggle}
                       className={`flex-1 py-3 rounded-2xl border-2 flex flex-col items-center justify-center transition-all ${hasReminder ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400' : 'border-slate-100 dark:border-slate-800 text-slate-400'}`}
                     >
                        {hasReminder ? <BellRing size={20} className="mb-1" /> : <Bell size={20} className="mb-1" />}
                        <span className="text-[9px] font-black uppercase">Lembrete</span>
                     </button>
                  </div>
               )}

               {hasReminder && (
                  <div className="animate-fade-in">
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1 ml-1">Data Hora do Lembrete</label>
                     <input type="datetime-local" value={reminderDate} onChange={(e) => setReminderDate(e.target.value)} className="w-full px-4 py-3 bg-indigo-50 dark:bg-indigo-900/20 border border-indigo-200 dark:border-indigo-800 rounded-xl text-sm text-slate-700 dark:text-slate-200 outline-none font-bold" />
                  </div>
               )}

               {/* Category Grid */}
               {type !== 'transfer' && (
                 <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 px-1">Categoria</label>
                    <div className="grid grid-cols-4 sm:grid-cols-5 gap-3">
                        {filteredCategories.map(cat => {
                          const Icon = getIcon(cat.icon);
                          const isSelected = categoryId === cat.id;
                          return (
                            <button 
                              key={cat.id} 
                              type="button" 
                              onClick={() => setCategoryId(cat.id)} 
                              className={`flex flex-col items-center justify-center p-2 rounded-2xl transition-all aspect-square ${isSelected ? `bg-slate-800 dark:bg-white text-white dark:text-slate-900 shadow-xl scale-110 z-10` : 'bg-slate-50 dark:bg-slate-800 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                            >
                              <Icon size={20} className="mb-1.5" />
                              <span className="text-[8px] font-bold text-center leading-tight line-clamp-1 w-full">{cat.name}</span>
                            </button>
                          );
                        })}
                    </div>
                 </div>
               )}
            </div>
          </form>

          {/* --- Floating Footer Actions --- */}
          <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-white via-white to-transparent dark:from-slate-900 dark:via-slate-900 z-30 flex items-center space-x-4">
             {transaction && (
                <button 
                  type="button" 
                  onClick={handleDelete} 
                  className="w-16 h-16 rounded-[1.5rem] bg-rose-50 dark:bg-rose-900/20 text-rose-500 flex items-center justify-center hover:bg-rose-100 transition active:scale-90"
                >
                   <Trash2 size={24} />
                </button>
             )}
             <button 
               onClick={handleSubmit} 
               disabled={isAmountInvalid}
               className={`flex-1 h-16 rounded-[1.5rem] font-black text-sm uppercase tracking-[0.2em] shadow-xl transition-all active:scale-95 flex items-center justify-center space-x-3 text-white ${isAmountInvalid ? 'bg-slate-300 dark:bg-slate-800 cursor-not-allowed' : 'bg-lime-500 hover:bg-lime-600 dark:bg-lime-600 dark:hover:bg-lime-500 text-slate-900 shadow-lime-200 dark:shadow-none'}`}
             >
                <Check size={24} strokeWidth={3} />
                <span>{transaction ? 'Salvar' : 'Confirmar'}</span>
             </button>
          </div>

          {/* Delete Confirmation Overlay */}
          {showDeleteConfirm && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-white/90 dark:bg-slate-950/90 backdrop-blur-sm animate-fade-in">
                <div className="text-center p-8">
                    <div className="w-20 h-20 bg-rose-100 dark:bg-rose-900/30 text-rose-600 dark:text-rose-400 rounded-full flex items-center justify-center mx-auto mb-6 animate-bounce">
                       <Trash2 size={32} />
                    </div>
                    <h3 className="text-2xl font-black text-slate-800 dark:text-white mb-2">Excluir Lançamento?</h3>
                    <p className="text-sm text-slate-500 dark:text-slate-400 mb-8 font-medium max-w-[200px] mx-auto">Essa ação não pode ser desfeita.</p>
                    <div className="flex space-x-4 justify-center">
                        <button onClick={() => setShowDeleteConfirm(false)} className="px-6 py-3 text-slate-500 font-bold bg-slate-100 dark:bg-slate-800 rounded-xl text-xs uppercase tracking-wider">Cancelar</button>
                        <button onClick={confirmDelete} className="px-8 py-3 text-white font-bold bg-rose-500 rounded-xl shadow-lg shadow-rose-200 dark:shadow-none text-xs uppercase tracking-wider">Sim, Excluir</button>
                    </div>
                </div>
            </div>
          )}
        </div>
      </div>

      <CalendarModal 
         isOpen={isCalendarOpen} 
         onClose={() => setIsCalendarOpen(false)} 
         selectedDate={date} 
         onSelect={handleDateSelect} 
      />

      {showRecurringEditModal && (
        <div className="fixed inset-0 bg-black/60 z-[120] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
           <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 w-full max-w-sm shadow-2xl border border-slate-200 dark:border-slate-800 animate-scale-in">
              <div className="flex justify-center mb-6 text-indigo-600 dark:text-indigo-400"><Layers size={56} /></div>
              <h3 className="text-xl font-black text-center text-slate-800 dark:text-white mb-2">Editar Recorrência</h3>
              <p className="text-center text-sm text-slate-500 dark:text-slate-400 mb-8 font-medium">Este é um lançamento recorrente. Como deseja aplicar as mudanças?</p>
              <div className="space-y-3">
                 <button onClick={() => handleConfirmRecurringUpdate(false)} className="w-full py-4 px-5 bg-white dark:bg-slate-800 border-2 border-slate-100 dark:border-slate-700 hover:border-indigo-500 transition-all rounded-2xl flex items-center group"><div className="bg-slate-100 dark:bg-slate-700 p-2 rounded-xl mr-4 text-slate-500 group-hover:text-indigo-600"><Copy size={20} /></div><div className="text-left"><span className="block text-sm font-bold text-slate-800 dark:text-white">Apenas esta</span><span className="block text-[10px] text-slate-400 uppercase font-bold tracking-wider">Somente atual</span></div></button>
                 <button onClick={() => handleConfirmRecurringUpdate(true)} className="w-full py-4 px-5 bg-indigo-50 dark:bg-indigo-900/10 border-2 border-indigo-100 dark:border-indigo-900/30 hover:border-indigo-500 transition-all rounded-2xl flex items-center group"><div className="bg-indigo-100 dark:bg-indigo-900/50 p-2 rounded-xl mr-4 text-indigo-600"><Layers size={20} /></div><div className="text-left"><span className="block text-sm font-bold text-indigo-900 dark:text-indigo-100">Esta e futuras</span><span className="block text-[10px] text-indigo-400 uppercase font-bold tracking-wider">Daqui para frente</span></div></button>
                 <button onClick={() => setShowRecurringEditModal(false)} className="w-full py-4 text-xs font-black text-slate-400 hover:text-slate-600 uppercase tracking-widest mt-2">Cancelar</button>
              </div>
           </div>
        </div>
      )}
    </>
  );
};

import React, { useState, useRef } from 'react';
import { Link } from 'react-router-dom';
import { 
  ChevronRight, Layers, Trash2, Moon, Sun, Download, 
  Upload, Palette, Plus, X, Wallet, CheckCircle2, 
  TrendingUp, FileSpreadsheet, RefreshCw,
  ShieldCheck, Landmark, History, User, Bell, Clock,
  ChevronLeft, LayoutGrid, Database, AppWindow,
  GripVertical, Eye, EyeOff, ArrowUp, ArrowDown, AlertTriangle,
  LogOut, Zap
} from 'lucide-react';
import { StorageService } from '../services/storageService';
import { useFinance } from '../context/FinanceContext';
import { Account, DashboardWidgetConfig } from '../types';

export const Settings = () => {
  const { 
    refreshData, settings, updateSettings, transactions, categories, 
    debts, accounts, budgets, goals, 
    addAccount, updateAccount, deleteAccount, reconcileBalance, getAccountBalance, 
    restoreAutoBackup, getBackupInfo 
  } = useFinance();

  const [isAccountModalOpen, setIsAccountModalOpen] = useState(false);
  const [isReconcileModalOpen, setIsReconcileModalOpen] = useState(false);
  const [isLayoutModalOpen, setIsLayoutModalOpen] = useState(false);

  // Custom Confirmation Modal State
  const [confirmation, setConfirmation] = useState<{ title: string; message: string; onConfirm?: () => void; isAlert?: boolean } | null>(null);

  // Account Form State
  const [editingAccount, setEditingAccount] = useState<Account | null>(null);
  const [accName, setAccName] = useState('');
  const [accType, setAccType] = useState<'wallet'|'bank'|'investment'>('bank');
  const [accColor, setAccColor] = useState('#6366f1');

  // Reconcile State
  const [reconcileAccountId, setReconcileAccountId] = useState('');
  const [actualBalance, setActualBalance] = useState('');

  const backupInputRef = useRef<HTMLInputElement>(null);
  const backupInfo = getBackupInfo();

  const handleClearData = () => {
    setConfirmation({
        title: 'Apagar Tudo',
        message: 'Tem certeza que deseja apagar todos os dados? Esta ação não pode ser desfeita.',
        onConfirm: () => {
            StorageService.clearData();
            refreshData();
            setConfirmation({ title: 'Sucesso', message: 'Dados apagados com sucesso.', isAlert: true });
            setTimeout(() => window.location.reload(), 1500);
        }
    });
  };

  const openAccountModal = (acc?: Account) => {
    if (acc) {
      setEditingAccount(acc);
      setAccName(acc.name);
      setAccType(acc.type as any);
      setAccColor(acc.color);
    } else {
      setEditingAccount(null);
      setAccName('');
      setAccType('bank');
      setAccColor('#6366f1');
    }
    setIsAccountModalOpen(true);
  };

  const handleSaveAccount = () => {
    if (!accName) return;
    const accountData = {
      name: accName,
      type: accType,
      color: accColor,
      initialBalance: editingAccount ? editingAccount.initialBalance : 0,
      enabled: true
    };

    if (editingAccount) {
      updateAccount({ ...editingAccount, ...accountData });
    } else {
      addAccount(accountData);
    }
    setIsAccountModalOpen(false);
  };

  const handleDeleteAccount = (acc: Account) => {
      setConfirmation({
          title: 'Excluir Conta',
          message: 'Deseja excluir esta conta e desvincular todas as transações associadas?',
          onConfirm: () => {
              deleteAccount(acc.id);
              setIsAccountModalOpen(false);
          }
      });
  };

  const openReconcileModal = (acc: Account) => {
    setReconcileAccountId(acc.id);
    setActualBalance(getAccountBalance(acc.id).toString());
    setIsReconcileModalOpen(true);
  };

  const handleReconcile = () => {
    if (!reconcileAccountId || isNaN(parseFloat(actualBalance))) return;
    reconcileBalance(reconcileAccountId, parseFloat(actualBalance));
    setIsReconcileModalOpen(false);
  };

  const handleAutoRestore = () => {
    if (!backupInfo) return;
    setConfirmation({
        title: 'Restaurar Backup',
        message: `Deseja restaurar o backup automático de ${backupInfo.date.toLocaleString()}? Os dados atuais serão substituídos.`,
        onConfirm: () => {
            const success = restoreAutoBackup();
            if (success) {
                setConfirmation({ title: 'Sucesso', message: 'Backup restaurado com sucesso!', isAlert: true });
                setTimeout(() => window.location.reload(), 1500);
            } else {
                setConfirmation({ title: 'Erro', message: 'Falha ao restaurar.', isAlert: true });
            }
        }
    });
  };

  const toggleWidget = (id: string) => {
    const newLayout = settings.dashboardLayout.map(w => 
      w.id === id ? { ...w, visible: !w.visible } : w
    );
    updateSettings({ dashboardLayout: newLayout });
  };

  const moveWidget = (index: number, direction: 'up' | 'down') => {
    const newLayout = [...settings.dashboardLayout];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newLayout.length) return;

    [newLayout[index], newLayout[targetIndex]] = [newLayout[targetIndex], newLayout[index]];
    updateSettings({ dashboardLayout: newLayout });
  };

  const colors = [
    { key: 'indigo', label: 'Lime', hex: '#84cc16' }, // Primary Lime (mapped to indigo var)
    { key: 'blue', label: 'Azul', hex: '#3b82f6' },
    { key: 'emerald', label: 'Verde', hex: '#10b981' },
    { key: 'violet', label: 'Roxo', hex: '#8b5cf6' },
    { key: 'rose', label: 'Rosa', hex: '#f43f5e' },
    { key: 'orange', label: 'Laranja', hex: '#f97316' },
  ];

  const handleExport = () => {
      const data = { 
        version: '1.1', 
        timestamp: new Date().toISOString(), 
        transactions, categories, settings, debts, accounts, budgets, goals 
      };

      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a'); 
      a.href = url; 
      const dateStr = new Date().toISOString().slice(0,10);
      a.download = `financas_pro_backup_${dateStr}.json`;
      document.body.appendChild(a); 
      a.click(); 
      document.body.removeChild(a); 
      URL.revokeObjectURL(url);
  };

  const handleRestoreClick = () => { 
      if (backupInputRef.current) {
          backupInputRef.current.value = '';
          backupInputRef.current.click();
      }
  };

  const processRestoreFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      setConfirmation({
          title: 'Importar Backup',
          message: 'ATENÇÃO: Restaurar um backup substituirá TODOS os dados atuais do aplicativo. Deseja continuar?',
          onConfirm: async () => {
              try {
                  const text = await file.text(); 
                  const data = JSON.parse(text);

                  if (!Array.isArray(data.transactions) && !Array.isArray(data.categories)) {
                      throw new Error("Arquivo de backup inválido ou corrompido.");
                  }

                  StorageService.saveTransactions(data.transactions || []); 
                  StorageService.saveCategories(data.categories || []);
                  StorageService.saveSettings(data.settings || {}); 
                  StorageService.saveDebts(data.debts || []); 
                  StorageService.saveAccounts(data.accounts || []);
                  StorageService.saveBudgets(data.budgets || []);
                  StorageService.saveGoals(data.goals || []);

                  const txCount = (data.transactions || []).length;
                  setConfirmation({ 
                      title: 'Sucesso', 
                      message: `Backup restaurado!\nRecuperados: ${txCount} Transações.`, 
                      isAlert: true 
                  });
                  setTimeout(() => window.location.reload(), 2000);

              } catch (err) { 
                  setConfirmation({ title: 'Erro', message: 'Arquivo inválido.', isAlert: true });
                  console.error(err);
              }
          }
      });
      if (backupInputRef.current) backupInputRef.current.value = '';
  };

  const getAccountIcon = (type: string) => {
      switch(type) {
          case 'wallet': return Wallet;
          case 'investment': return TrendingUp;
          case 'bank': default: return Landmark;
      }
  }

  return (
    <div className="pb-32 animate-fade-in text-slate-900 dark:text-slate-100 max-w-md mx-auto relative">

      {/* --- Sticky App Header --- */}
      <div className="sticky top-0 bg-slate-50/80 dark:bg-slate-950/80 backdrop-blur-lg z-30 pt-4 pb-4 px-2 flex items-center justify-between border-b border-slate-200/50 dark:border-slate-800/50">
        <div className="flex items-center">
          <Link to="/" className="p-2 mr-2 hover:bg-white dark:hover:bg-slate-800 rounded-full transition-all active:scale-90">
             <ChevronLeft size={24} className="text-slate-500" />
          </Link>
          <h1 className="text-xl font-black tracking-tight text-slate-800 dark:text-white">Ajustes</h1>
        </div>
        <div className="w-8"></div> {/* Spacer for balance */}
      </div>

      <div className="space-y-6 px-3 pt-4">

        {/* --- Profile & Main Settings --- */}
        <section className="bg-white dark:bg-slate-900 rounded-[2.2rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800 relative overflow-hidden">
           <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/10 rounded-full -mr-10 -mt-10 blur-2xl"></div>

           {/* Profile Input */}
           <div className="flex items-center space-x-4 relative z-10 mb-8">
              <div className="w-16 h-16 bg-gradient-to-tr from-indigo-600 to-indigo-400 rounded-[1.2rem] flex items-center justify-center text-white shadow-lg shadow-indigo-200 dark:shadow-none shrink-0">
                 <User size={32} strokeWidth={1.5} />
              </div>
              <div className="flex-1">
                 <label className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest block mb-1">Nome de Usuário</label>
                 <input 
                   value={settings.userName || ''} 
                   onChange={(e) => updateSettings({ userName: e.target.value })} 
                   placeholder="Seu Nome"
                   className="w-full bg-transparent text-xl font-black text-slate-800 dark:text-white outline-none placeholder:text-slate-300 dark:placeholder:text-slate-700 border-b border-transparent focus:border-indigo-200 transition-colors pb-1"
                 />
              </div>
           </div>

           {/* Settings Grid */}
           <div className="grid grid-cols-2 gap-3">
              {/* Theme Toggle */}
              <button 
                onClick={() => updateSettings({ theme: settings.theme === 'light' ? 'dark' : 'light' })}
                className="bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl flex flex-col items-start border border-slate-100 dark:border-slate-700 transition active:scale-95"
              >
                 <div className="flex justify-between w-full mb-2">
                    <span className="text-[10px] font-bold text-slate-400 uppercase">Tema</span>
                    {settings.theme === 'dark' ? <Moon size={16} className="text-indigo-400" /> : <Sun size={16} className="text-amber-500" />}
                 </div>
                 <span className="text-sm font-bold dark:text-white capitalize">{settings.theme === 'light' ? 'Claro' : 'Escuro'}</span>
              </button>

              {/* Notification Toggle (Simulated cycle) */}
              <button 
                onClick={() => {
                   const next = settings.notificationInterval === 0 ? 12 : settings.notificationInterval === 12 ? 24 : 0;
                   updateSettings({ notificationInterval: next });
                }}
                className="bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl flex flex-col items-start border border-slate-100 dark:border-slate-700 transition active:scale-95"
              >
                 <div className="flex justify-between w-full mb-2">
                    <span className="text-[10px] font-bold text-slate-400 uppercase">Alertas</span>
                    <Bell size={16} className={settings.notificationInterval ? 'text-indigo-500' : 'text-slate-300'} />
                 </div>
                 <span className="text-sm font-bold dark:text-white">{settings.notificationInterval ? `${settings.notificationInterval}h` : 'Desligado'}</span>
              </button>

              {/* Categories */}
              <Link to="/categories" className="bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl flex flex-col items-start border border-slate-100 dark:border-slate-700 transition active:scale-95 col-span-2 flex-row items-center justify-between">
                 <div className="flex items-center space-x-3">
                    <div className="p-2 bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-xl">
                       <LayoutGrid size={18} />
                    </div>
                    <div className="text-left">
                       <span className="text-sm font-bold text-slate-800 dark:text-white block">Categorias</span>
                       <span className="text-[10px] text-slate-400">Gerenciar etiquetas</span>
                    </div>
                 </div>
                 <ChevronRight size={18} className="text-slate-300" />
              </Link>
           </div>
        </section>

        {/* --- Accounts Management --- */}
        <section>
           <div className="flex justify-between items-center mb-3 px-2">
              <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Minhas Contas</h2>
              <button onClick={() => openAccountModal()} className="p-2 bg-indigo-600 text-white rounded-xl shadow-lg shadow-indigo-200 dark:shadow-none active:scale-90 transition-all">
                 <Plus size={16} strokeWidth={3} />
              </button>
           </div>

           <div className="space-y-3">
              {accounts.map(acc => {
                const Icon = getAccountIcon(acc.type);
                const balance = getAccountBalance(acc.id);
                return (
                  <div key={acc.id} onClick={() => openAccountModal(acc)} className="bg-white dark:bg-slate-900 p-4 rounded-3xl border border-slate-100 dark:border-slate-800 flex items-center justify-between active:scale-[0.98] transition-all cursor-pointer group">
                     <div className="flex items-center space-x-4">
                        <div className="w-12 h-12 rounded-2xl flex items-center justify-center text-white shadow-sm transition-transform group-hover:scale-110" style={{ backgroundColor: acc.color }}>
                           <Icon size={20} strokeWidth={2} />
                        </div>
                        <div>
                           <h3 className="font-bold text-slate-800 dark:text-white text-sm leading-tight">{acc.name}</h3>
                           <span className="text-[10px] font-medium text-slate-400 uppercase tracking-wide">{acc.type === 'wallet' ? 'Carteira' : acc.type === 'bank' ? 'Conta Corrente' : 'Investimento'}</span>
                        </div>
                     </div>
                     <div className="flex flex-col items-end">
                        <span className={`font-black text-sm ${balance >= 0 ? 'text-slate-800 dark:text-white' : 'text-rose-500'}`}>
                           R$ {balance.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </span>
                        <button 
                          onClick={(e) => { e.stopPropagation(); openReconcileModal(acc); }}
                          className="flex items-center text-[9px] font-bold text-indigo-500 bg-indigo-50 dark:bg-indigo-900/20 px-2 py-1 rounded-lg mt-1 group-hover:bg-indigo-100 transition-colors"
                        >
                           <RefreshCw size={10} className="mr-1" /> Ajustar
                        </button>
                     </div>
                  </div>
                );
              })}
           </div>
        </section>

        {/* --- Data & Security --- */}
        <section className="bg-white dark:bg-slate-900 rounded-[2.2rem] overflow-hidden border border-slate-100 dark:border-slate-800">
           <div className="p-5 border-b border-slate-50 dark:border-slate-800/50">
              <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center">
                 <Database size={14} className="mr-2" /> Dados e Backup
              </h2>

              {/* Backup Status */}
              <div className="bg-emerald-50 dark:bg-emerald-950/30 p-4 rounded-2xl flex items-center justify-between border border-emerald-100 dark:border-emerald-900/50 mb-4">
                 <div className="flex items-center space-x-3">
                    <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                    <div>
                       <span className="text-[10px] font-black text-emerald-600 dark:text-emerald-400 uppercase tracking-wide block">Backup Automático</span>
                       <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">
                          {backupInfo ? `Última cópia: ${backupInfo.date.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}` : 'Aguardando sincronização...'}
                       </span>
                    </div>
                 </div>
                 {backupInfo && (
                    <button onClick={handleAutoRestore} className="p-2 bg-white dark:bg-emerald-900 text-emerald-600 dark:text-emerald-400 rounded-xl shadow-sm hover:shadow-md transition active:scale-95">
                       <RefreshCw size={16} />
                    </button>
                 )}
              </div>

              {/* Actions Grid */}
              <div className="grid grid-cols-2 gap-3">
                 <button onClick={handleExport} className="flex flex-col items-center justify-center p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl transition active:scale-95 hover:bg-slate-100 dark:hover:bg-slate-700">
                    <Download size={20} className="text-indigo-500 mb-2" />
                    <span className="text-[10px] font-bold text-slate-600 dark:text-slate-300">Exportar JSON</span>
                 </button>
                 <button onClick={handleRestoreClick} className="flex flex-col items-center justify-center p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl transition active:scale-95 hover:bg-slate-100 dark:hover:bg-slate-700">
                    <Upload size={20} className="text-indigo-500 mb-2" />
                    <span className="text-[10px] font-bold text-slate-600 dark:text-slate-300">Importar JSON</span>
                 </button>
                 <input type="file" accept=".json" ref={backupInputRef} onChange={processRestoreFile} className="hidden" />
              </div>
           </div>

           {/* Danger Zone */}
           <button 
             onClick={handleClearData}
             className="w-full p-5 flex items-center justify-center space-x-2 text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-950/30 transition-colors"
           >
              <LogOut size={16} />
              <span className="text-xs font-black uppercase tracking-widest">Resetar Aplicativo</span>
           </button>
        </section>

        {/* --- Customization Link --- */}
        <button 
           onClick={() => setIsLayoutModalOpen(true)}
           className="w-full py-4 text-xs font-bold text-slate-400 uppercase tracking-widest hover:text-indigo-500 transition-colors flex items-center justify-center"
        >
           <Palette size={14} className="mr-2" /> Personalizar Dashboard
        </button>

      </div>

      {/* --- Dashboard Layout Modal --- */}
      {isLayoutModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 z-[70] flex items-end sm:items-center justify-center backdrop-blur-md animate-fade-in p-0 sm:p-4">
           <div className="bg-white dark:bg-slate-900 rounded-t-[3rem] sm:rounded-[3rem] p-8 w-full max-w-sm shadow-2xl border border-slate-100 dark:border-slate-800 animate-slide-up max-h-[90vh] overflow-y-auto no-scrollbar">
              <div className="flex justify-between items-center mb-8">
                 <h3 className="text-2xl font-black text-slate-800 dark:text-white tracking-tight">Organizar Início</h3>
                 <button onClick={() => setIsLayoutModalOpen(false)} className="p-2 bg-slate-50 dark:bg-slate-800 rounded-full transition-all active:scale-90"><X size={24} className="text-slate-400"/></button>
              </div>

              <div className="space-y-3">
                 {settings.dashboardLayout.map((widget, index) => (
                    <div key={widget.id} className="bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-800 p-4 rounded-3xl flex items-center justify-between group">
                       <div className="flex items-center space-x-3">
                          <div className="flex flex-col space-y-1">
                             <button 
                               onClick={() => moveWidget(index, 'up')}
                               disabled={index === 0}
                               className="p-1 text-slate-300 hover:text-indigo-500 disabled:opacity-20"
                             >
                                <ArrowUp size={14} />
                             </button>
                             <button 
                               onClick={() => moveWidget(index, 'down')}
                               disabled={index === settings.dashboardLayout.length - 1}
                               className="p-1 text-slate-300 hover:text-indigo-500 disabled:opacity-20"
                             >
                                <ArrowDown size={14} />
                             </button>
                          </div>
                          <span className="text-sm font-bold text-slate-700 dark:text-slate-200">{widget.label}</span>
                       </div>

                       <button 
                         onClick={() => toggleWidget(widget.id)}
                         className={`p-2 rounded-xl transition-all ${widget.visible ? 'bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600' : 'bg-slate-200 dark:bg-slate-700 text-slate-400 opacity-50'}`}
                       >
                          {widget.visible ? <Eye size={20} /> : <EyeOff size={20} />}
                       </button>
                    </div>
                 ))}
              </div>

              <div className="mt-8 pt-6 border-t border-slate-100 dark:border-slate-800">
                 <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 block">Cor de Destaque</h4>
                 <div className="flex justify-between items-center px-1">
                    {colors.map(c => {
                      const isSelected = (settings.primaryColor || 'indigo') === c.key;
                      return (
                        <button 
                          key={c.key} 
                          onClick={() => updateSettings({ primaryColor: c.key })} 
                          className={`w-10 h-10 rounded-full transition-all flex items-center justify-center relative ${isSelected ? 'scale-110 shadow-xl shadow-indigo-200 dark:shadow-none ring-4 ring-white dark:ring-slate-800' : 'hover:scale-105 opacity-60 hover:opacity-100'}`} 
                          style={{ backgroundColor: c.hex }}
                        >
                          {isSelected && <CheckCircle2 size={18} className="text-white drop-shadow-md" />}
                        </button>
                      );
                    })}
                 </div>
              </div>

              <button 
                onClick={() => setIsLayoutModalOpen(false)}
                className="w-full mt-8 py-5 bg-indigo-600 text-white rounded-[1.5rem] font-black text-sm uppercase tracking-widest shadow-xl shadow-indigo-100 dark:shadow-none hover:bg-indigo-700 active:scale-[0.98] transition-all"
              >
                Concluir
              </button>
           </div>
        </div>
      )}

      {/* --- Account Form Modal --- */}
      {isAccountModalOpen && (
         <div className="fixed inset-0 bg-slate-900/60 z-[70] flex items-end sm:items-center justify-center backdrop-blur-md animate-fade-in p-0 sm:p-4">
            <div className="bg-white dark:bg-slate-900 rounded-t-[3rem] sm:rounded-[3rem] p-8 w-full max-w-sm shadow-2xl border border-slate-100 dark:border-slate-800 animate-slide-up">
               <div className="flex justify-between items-center mb-8">
                  <h3 className="text-2xl font-black text-slate-800 dark:text-white tracking-tight">
                     {editingAccount ? 'Editar Conta' : 'Nova Conta'}
                  </h3>
                  <button onClick={() => setIsAccountModalOpen(false)} className="p-2 bg-slate-50 dark:bg-slate-800 rounded-full transition-all active:scale-90"><X size={24} className="text-slate-400"/></button>
               </div>

               <div className="space-y-6">
                  <div>
                     <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 px-1">Identificação</label>
                     <input 
                       value={accName} 
                       onChange={e => setAccName(e.target.value)} 
                       className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-800 border-2 border-transparent focus:border-indigo-500 rounded-[1.5rem] dark:text-white outline-none font-bold text-lg" 
                       placeholder="Ex: Nubank, Bradesco..." 
                     />
                  </div>

                  <div>
                     <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 px-1">Categoria</label>
                     <div className="flex p-1 bg-slate-50 dark:bg-slate-800 rounded-2xl">
                        {(['bank', 'wallet', 'investment'] as const).map(t => (
                           <button 
                             key={t} 
                             onClick={() => setAccType(t)} 
                             className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${accType === t ? 'bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 shadow-md scale-[1.02]' : 'text-slate-400'}`}
                           >
                              {t === 'bank' ? 'Banco' : t === 'wallet' ? 'Bolso' : 'Inv.'}
                           </button>
                        ))}
                     </div>
                  </div>

                  <div>
                     <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 px-1">Cor Personalizada</label>
                     <div className="grid grid-cols-5 gap-3">
                        {['#6366f1', '#ef4444', '#10b981', '#f59e0b', '#ec4899'].map(c => (
                           <button 
                             key={c} 
                             onClick={() => setAccColor(c)} 
                             className={`aspect-square rounded-2xl transition-all relative ${accColor === c ? 'scale-110 ring-4 ring-white dark:ring-slate-800 shadow-lg' : 'opacity-60 hover:opacity-100'}`} 
                             style={{ backgroundColor: c }} 
                           >
                              {accColor === c && <CheckCircle2 size={16} className="text-white mx-auto drop-shadow-md" />}
                           </button>
                        ))}
                     </div>
                  </div>

                  <div className="pt-4 flex flex-col space-y-3">
                    <button 
                      onClick={handleSaveAccount} 
                      className="w-full py-5 bg-indigo-600 text-white rounded-[1.5rem] font-black text-sm uppercase tracking-widest shadow-xl shadow-indigo-100 dark:shadow-none hover:bg-indigo-700 active:scale-[0.98] transition-all"
                    >
                      Confirmar Conta
                    </button>

                    {editingAccount && (
                       <button 
                         onClick={() => handleDeleteAccount(editingAccount)} 
                         className="w-full py-4 text-rose-500 font-bold text-xs uppercase tracking-widest hover:bg-rose-50 dark:hover:bg-rose-950/20 rounded-[1.5rem] transition"
                       >
                         Excluir Definitivamente
                       </button>
                    )}
                  </div>
               </div>
            </div>
         </div>
      )}

      {/* --- Reconcile Modal --- */}
      {isReconcileModalOpen && (
         <div className="fixed inset-0 bg-slate-900/60 z-[70] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
            <div className="bg-white dark:bg-slate-900 rounded-[3rem] p-8 w-full max-w-sm shadow-2xl border border-slate-100 dark:border-slate-800 animate-scale-in">
               <div className="text-center mb-8">
                 <div className="w-20 h-20 bg-indigo-50 dark:bg-indigo-900/30 rounded-[2rem] flex items-center justify-center mx-auto mb-4 text-indigo-600 dark:text-indigo-400 shadow-inner">
                    <RefreshCw size={36} strokeWidth={1.5} />
                 </div>
                 <h3 className="text-2xl font-black text-slate-800 dark:text-white tracking-tight">Ajuste de Saldo</h3>
                 <p className="text-xs text-slate-500 dark:text-slate-400 mt-2 px-4">
                    O saldo real no banco é diferente? Informe o valor correto para sincronizar.
                 </p>
               </div>

               <div className="space-y-6">
                 <div className="bg-slate-50 dark:bg-slate-800/50 p-4 rounded-3xl flex justify-between items-center border border-slate-100 dark:border-slate-800">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Saldo no App</span>
                    <span className="text-lg font-black text-slate-800 dark:text-white">R$ {reconcileAccountId ? getAccountBalance(reconcileAccountId).toLocaleString('pt-BR', {minimumFractionDigits:2}) : '0,00'}</span>
                 </div>

                 <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 px-1">Novo Saldo Real</label>
                    <div className="relative">
                       <span className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 font-black text-xl">R$</span>
                       <input 
                         type="number" 
                         step="0.01" 
                         value={actualBalance} 
                         onChange={e => setActualBalance(e.target.value)} 
                         className="w-full pl-14 pr-5 py-5 bg-white dark:bg-slate-800 border-2 border-indigo-100 dark:border-indigo-900/50 focus:border-indigo-500 rounded-[1.5rem] dark:text-white outline-none font-black text-2xl shadow-sm" 
                         placeholder="0,00"
                       />
                    </div>
                 </div>

                 <div className="flex space-x-3 pt-4">
                    <button onClick={() => setIsReconcileModalOpen(false)} className="flex-1 py-4 text-slate-400 font-black text-xs uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-800 rounded-2xl transition">Cancelar</button>
                    <button onClick={handleReconcile} className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl shadow-indigo-100 dark:shadow-none hover:bg-indigo-700 transition active:scale-[0.98]">Confirmar</button>
                 </div>
               </div>
            </div>
         </div>
      )}

      {/* Global Confirmation Modal */}
      {confirmation && (
        <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-6 backdrop-blur-sm animate-fade-in">
           <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 w-full max-w-sm shadow-2xl border border-slate-100 dark:border-slate-800 animate-scale-in text-center">
              <div className={`w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 ${confirmation.isAlert ? 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900/30 dark:text-indigo-400' : 'bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400'}`}>
                 {confirmation.isAlert ? <CheckCircle2 size={32} /> : <AlertTriangle size={32} />}
              </div>
              <h3 className="text-xl font-black text-slate-800 dark:text-white mb-2">{confirmation.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-8 font-medium leading-relaxed whitespace-pre-line">
                 {confirmation.message}
              </p>

              <div className="flex space-x-3">
                 {!confirmation.isAlert && (
                    <button 
                      onClick={() => setConfirmation(null)}
                      className="flex-1 py-4 text-slate-500 font-bold bg-slate-100 dark:bg-slate-800 rounded-2xl text-xs uppercase tracking-wider"
                    >
                       Cancelar
                    </button>
                 )}
                 <button 
                   onClick={() => {
                      if (confirmation.onConfirm) confirmation.onConfirm();
                      setConfirmation(null);
                   }}
                   className={`flex-1 py-4 text-white font-bold rounded-2xl text-xs uppercase tracking-wider shadow-lg ${confirmation.isAlert ? 'bg-indigo-600 w-full' : 'bg-rose-600 shadow-rose-200 dark:shadow-none'}`}
                 >
                    {confirmation.isAlert ? 'OK' : 'Confirmar'}
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};
